def save_post_content(message, previous=None):
    data = dict(previous or {})
    if getattr(message, 'media_group_id', None):
        capture_album(message, data, replace_text=True)
        return
    if message.content_type == 'text':
        data.update(text=message.text or '', entities=entity_dicts(message.entities))
    elif message.content_type in {'photo', 'video', 'animation'} or message.content_type == 'document' and getattr(message.document, 'mime_type', '') == 'image/gif':
        data.update(text=message.caption or '', entities=entity_dicts(message.caption_entities), photo_id=None, video_id=None, animation_id=None, album=[])
        if message.content_type == 'photo':
            data['photo_id'] = message.photo[-1].file_id
        elif message.content_type == 'video':
            data['video_id'] = message.video.file_id
        else:
            data['animation_id'] = (message.animation if message.content_type == 'animation' else message.document).file_id
    else:
        raise UserError('Send text, a photo, a video, an album or a GIF.')
    data.pop('content', None)
    validate_post(data)
    if any(data.get(key) for key in ('photo_id', 'video_id', 'animation_id', 'album')):
        button_choice(message.chat.id, message.from_user.id, data)
    else:
        media_choice(message.chat.id, message.from_user.id, data)



def save_photo(message, data):
    if getattr(message, 'media_group_id', None):
        raise UserError('Use Add Album to attach multiple photos/videos.')
    if not getattr(message, 'photo', None):
        raise UserError('Send a single photo or use /cancel.')
    data = dict(data, photo_id=message.photo[-1].file_id, video_id=None, animation_id=None, album=[])
    validate_post(data)
    button_choice(message.chat.id, message.from_user.id, data)



def save_video(message, data):
    if not getattr(message, 'video', None) or getattr(message, 'media_group_id', None):
        raise UserError('Send a single video or use /cancel.')
    data = dict(data, video_id=message.video.file_id, photo_id=None, animation_id=None, album=[])
    validate_post(data)
    button_choice(message.chat.id, message.from_user.id, data)



def send_post(chat_id, data):
    if USER_CLIENT is not None and (RUN_MODE == "userbot" or isinstance(chat_id, int) and chat_id < 0 or has_user_media(data) and chat_id == USER_CLIENT.me.id):
        result = USER_CLIENT.post(chat_id, data, actor=userbot_actor(data))
        if RUN_MODE == "hybrid" and chat_id == USER_CLIENT.me.id and has_user_media(data):
            ui(chat_id, "Preview sent to your Saved Messages because this post uses user-account media.")
        return result
    outgoing = copy.deepcopy(data)
    validate_post(outgoing)
    text = outgoing.get('content', outgoing.get('text', '')) or ''
    entities = entity_dicts(outgoing.get('entities'))
    quote = outgoing.get('quote_theme')
    quote = setting_on('quote_theme') if quote is None else quote
    if text and quote and not any(item['type'] in {'blockquote', 'expandable_blockquote', 'pre', 'code'} for item in entities):
        entities.append({'type': background_entity_type(), 'offset': 0, 'length': u16(text)})
    keyboard = post_keyboard(outgoing)
    options = dict(reply_markup=keyboard, **effect_args(chat_id))
    if outgoing.get('album'):
        media = []
        for index, item in enumerate(outgoing['album']):
            cls = types.InputMediaPhoto if item['type'] == 'photo' else types.InputMediaVideo
            media.append(cls(item['file_id'], caption=text if index == 0 else None, caption_entities=entity_objects(entities) if index == 0 else None))
        messages = tg(BOT.send_media_group, chat_id, media=media)
        if keyboard:
            try:
                messages.append(tg(BOT.send_message, chat_id, smallcaps('🔗 Post links'), reply_markup=keyboard))
            except Exception as error:
                raise DeliveryUncertain('Album was sent, but its buttons were not confirmed. Check the channel before retrying.') from error
        return messages
    for key, method in (('photo_id', 'send_photo'), ('video_id', 'send_video'), ('animation_id', 'send_animation')):
        if outgoing.get(key):
            return tg(getattr(BOT, method), chat_id, outgoing[key], caption=text, caption_entities=entity_objects(entities), **options)
    return tg(BOT.send_message, chat_id, text, entities=entity_objects(entities), **options)



def post_controls(chat_id, data):
    post_id = data['id']
    keyboard = types.InlineKeyboardMarkup(row_width=2)
    for label, verb, glyph in (
        ('Send to Channels', 'post_send', '📤'), ('Schedule', 'post_schedule', '⏰'),
        ('Edit Post', 'post_edit', '✏️'), ('Preview', 'post_preview', '👁️'),
        ('Rename', 'post_rename', '📝'), ('Duplicate', 'post_duplicate', '📋'),
        ('Delete', 'post_delete', '🗑️'), ('My Posts', 'posts', '📂'),
    ):
        keyboard.add(button(label, action='posts:0' if verb == 'posts' else f'{verb}:{post_id}', glyph=glyph, color='red' if verb == 'post_delete' else 'blue'))
    keyboard.add(button('Home', action='home', glyph='🏠'))
    title = data.get('title') or post_title(data)
    ui(chat_id, f'✅ {title}\nPost ID: {post_id}', keyboard, codes=[post_id])



def finish_post(chat_id, user_id, data):
    validate_post(data)
    raw_text, raw_entities = data.get('text', ''), entity_dicts(data.get('entities'))
    preferences = STORE.profile(user_id)['settings']
    text, entities = premium_text(raw_text, raw_entities, preferences=preferences)
    saved = dict(data, raw_text=raw_text, raw_entities=raw_entities, content=text, entities=entities, buttons=normalized_buttons(data))
    if 'quote_theme' in preferences:
        saved['quote_theme'] = bool(preferences['quote_theme'])
    for key in ('_album_group', '_album_message_ids', 'edit_id', 'schedule_id'):
        saved.pop(key, None)
    validate_post(saved)
    if data.get('schedule_id'):
        STORE.change_schedule(data['schedule_id'], user_id, 'content', post=saved)
    saved = STORE.save_post(user_id, chat_id, saved, data.get('edit_id'))
    STORE.clear_state(chat_id, user_id)
    try:
        send_post(chat_id, saved)
    except Exception:
        ui(chat_id, 'Post saved. Preview delivery was not confirmed. Open My Posts to try its preview again.')
        raise
    post_controls(chat_id, saved)



def destination_id(message):
    chat = forwarded_chat(message)
    if chat:
        return chat.id
    value = (message.text or "").strip()
    if re.fullmatch(r"-?\d+", value):
        return int(value)
    if re.fullmatch(r"@[A-Za-z0-9_]+", value):
        return value
    raise UserError("Forward a channel post or send its numeric chat ID.")


def publish(chat_id, user_id, post_id, target):
    if not require_post(chat_id, user_id):
        return False
    data = STORE.post(post_id, user_id)
    destination = checked_destination(user_id, target)
    try:
        send_post(destination.id, data)
    except Exception as error:
        STORE.record_delivery(user_id, data['id'], destination.id, 'failed', str(error))
        raise
    STORE.record_delivery(user_id, data['id'], destination.id, 'success')
    ui(chat_id, '✅ Sent successfully.')
    return True



def cancel(chat_id, user_id):
    invalidate_intro(chat_id, user_id)
    STORE.clear_state(chat_id, user_id)
    if user_id == ADMIN_ID and BROADCAST_LOCK.locked():
        BROADCAST_CANCEL.set()
    ui(chat_id, "✅ Cancelled.", main_menu(user_id))


def broadcast(message):
    owner_only(message.chat.id, message.from_user.id)
    if not BROADCAST_LOCK.acquire(blocking=False):
        raise UserError("A broadcast is already running. Use /cancel to stop it.")
    BROADCAST_CANCEL.clear()
    STORE.clear_state(message.chat.id, message.from_user.id)
    source_chat, source_message = message.chat.id, message.message_id
    recipients = STORE.audience()

    def worker():
        success = failed = 0
        try:
            for user_id in recipients:
                if STOP.is_set() or BROADCAST_CANCEL.is_set():
                    break
                try:
                    tg(BOT.copy_message, user_id, source_chat, source_message,
                       max_wait=3600, cancel=BROADCAST_CANCEL, **effect_args(user_id))
                    success += 1
                except Exception as error:
                    if STOP.is_set() or BROADCAST_CANCEL.is_set():
                        break
                    failed += 1
                    log_error("broadcast delivery", error)
                wait_cancel(0.06, BROADCAST_CANCEL)
        except UserError:
            pass
        except Exception as error:
            log_error("broadcast worker", error)
        finally:
            try:
                if not STOP.is_set():
                    with contextlib.suppress(Exception):
                        status = "Cancelled" if BROADCAST_CANCEL.is_set() else "Complete"
                        ui(source_chat, f"📢 Broadcast {status}\nSuccess: {success}\nFailed: {failed}\nAudience: {len(recipients)}")
            finally:
                BROADCAST_LOCK.release()
    threading.Thread(target=worker, name="broadcast", daemon=True).start()
    ui(source_chat, "📢 Broadcast started. Use /cancel to stop it.")


def command(message):
    chat_id, user_id = message.chat.id, message.from_user.id
    name, _, argument = (message.text or "").partition(" ")
    name, argument = name.split("@", 1)[0].lower(), argument.strip()
    if feature_command(message):
        return
    if name == "/start":
        referrer = None
        with contextlib.suppress(ValueError, IndexError):
            referrer = int(argument.split()[0])
        STORE.clear_state(chat_id, user_id)
        created = STORE.register(user_id, message.from_user.username, referrer)
        STORE.touch_user(user_id, " ".join(filter(None, [message.from_user.first_name, getattr(message.from_user, "last_name", "")])), created)
        start_animation(message)
    elif name == "/cancel":
        cancel(chat_id, user_id)
    elif name == "/access":
        access_status(chat_id, user_id)
    elif name == "/effect":
        set_effect(message, argument)
    elif name == "/send":
        parts = argument.split()
        if len(parts) != 2:
            raise UserError("Use /send latest -100CHAT_ID or use the Send to Channel button.")
        publish(chat_id, user_id, parts[0], parts[1])
    elif name == "/help":
        ui(chat_id, "⭐ KD Premium Emoji Bot\n/start — Open the menu\n/access — Check access\n/cancel — Cancel the current step\n/send — Publish a saved post\n\nUse Make Post for text, photos, videos, albums, GIFs and buttons. /posts /channels /schedules /templates /emojis /vip open the new features. Times use IST.\nOwner settings are available in Owner Panel.", main_menu(user_id))
    else:
        raise UserError("Unknown command. Use /help or /cancel.")


