def choose_user_emoji(glyph, preferences=None, ui=False):
    preferences = preferences or {}
    pack = preferences.get('pack', 'classic')
    if ui or pack == 'classic':
        return CATALOG.choose(glyph, ui=ui)
    if pack == 'original':
        return None
    favourite = preferences.get('favorites', {}).get(glyph)
    if pack == 'favorites' and favourite:
        with CATALOG.lock:
            if favourite not in CATALOG.unavailable:
                return favourite
    with CATALOG.lock:
        options = list(dict.fromkeys(str(v) for v in CATALOG.mapping.get(glyph, []) if str(v) not in CATALOG.unavailable))
        if USER_CLIENT is not None:
            options = [value for value in options if CATALOG.records.get(value, {}).get('emoji', '').replace('\ufe0f', '') == glyph.replace('\ufe0f', '')]
    if options:
        return random.choice(options) if pack == 'random' else options[min(1, len(options) - 1)] if pack == 'alternate' else options[0]
    return CATALOG.choose(glyph)


