def normalized_buttons(data):
    rows = data.get('buttons')
    if rows is None:
        rows = [[{'label': data['btn_name'], 'url': data['btn_url'], 'color': 'blue', 'glyph': '🔗'}]] if data.get('btn_name') and data.get('btn_url') else []
    if not isinstance(rows, list) or len(rows) > 8:
        raise UserError('Use up to 8 button rows.')
    result, total = [], 0
    for row in rows:
        if not isinstance(row, list) or not 1 <= len(row) <= 6:
            raise UserError('Use 1–6 buttons per row.')
        converted = []
        for item in row:
            label = str(item.get('label', item.get('text', ''))).strip()
            color = item.get('color', 'blue')
            if not label or u16(label) > 64 or color not in COLORS:
                raise UserError('Each button needs a label up to 64 units and a supported color.')
            glyph = item.get('glyph', '🔗')
            custom_id = str(item.get('custom_id') or '')
            if custom_id and not re.fullmatch(r'\d{5,25}', custom_id):
                raise UserError('Invalid custom emoji ID for a button.')
            if not custom_id and (len(emoji.emoji_list(glyph)) != 1 or emoji.replace_emoji(glyph, replace='').strip()):
                raise UserError('Use one emoji per button.')
            converted.append({'label': label, 'url': good_url(str(item.get('url', ''))), 'color': color, 'glyph': glyph, 'custom_id': custom_id})
            total += 1
        result.append(converted)
    if total > 24:
        raise UserError('Use up to 24 buttons per post.')
    return result


def parse_buttons(text):
    rows = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = [p.strip() for p in line.split('|')]
        if len(parts) not in (4, 5) or not parts[0].isdigit() or not 1 <= int(parts[0]) <= 8:
            raise UserError('Each line: ROW | LABEL | URL | COLOR | EMOJI (optional).')
        icon = parts[4] if len(parts) == 5 else '🔗'
        item = {'label': parts[1], 'url': parts[2], 'color': parts[3].translate(NORMAL_TABLE).lower(), 'glyph': icon if not icon.isdigit() else CATALOG.alt(icon)}
        if icon.isdigit():
            item['custom_id'] = icon
        rows.setdefault(int(parts[0]), []).append(item)
    if not rows:
        raise UserError('Send at least one button line.')
    return normalized_buttons({'buttons': [rows[key] for key in sorted(rows)]})


def post_keyboard(data):
    rows = normalized_buttons(data)
    if not rows:
        return None
    keyboard = types.InlineKeyboardMarkup()
    for row in rows:
        buttons = []
        for item in row:
            value = button(item['label'], url=item['url'], color=item['color'], glyph=item['glyph'])
            if item.get('custom_id'):
                value.icon_custom_emoji_id = item['custom_id']
                value.text = emoji.replace_emoji(item['label'], replace='').strip().translate(SMALL_TABLE) or 'Open'
            buttons.append(value)
        keyboard.row(*buttons)
    return keyboard


