def checked_destination(user_id, target):
    guard_user(user_id)
    target = int(target) if str(target).lstrip('-').isdigit() else target
    chat = tg(BOT.get_chat, target)
    if chat.type not in {'channel', 'supergroup', 'group'}:
        raise UserError('Choose a channel or group.')
    user_member = tg(BOT.get_chat_member, chat.id, user_id)
    bot_member = tg(BOT.get_chat_member, chat.id, BOT_ME.id)
    if user_member.status not in {'administrator', 'creator'}:
        raise UserError('You must be an administrator of the destination.')
    if bot_member.status not in {'administrator', 'creator'}:
        raise UserError('Make this bot an administrator of the destination.')
    if chat.type == 'channel' and bot_member.status != 'creator' and not getattr(bot_member, 'can_post_messages', False):
        raise UserError('Give the bot permission to post messages.')
    return chat


