def publish_many(chat_id, user_id, post_id, targets):
    data = STORE.post(post_id, user_id)
    with PUBLISH_GUARD:
        if user_id in PUBLISHING:
            raise UserError('Your previous multi-channel delivery is still running.')
        PUBLISHING.add(user_id)
    STORE.clear_state(chat_id, user_id)
    def work():
        success, failed = [], []
        try:
            for target in targets:
                if STOP.is_set():
                    break
                try:
                    if not has_access(user_id) or missing_channels(user_id):
                        raise UserError('Access expired or required channel membership is missing.')
                    chat = checked_destination(user_id, target)
                    send_post(chat.id, data)
                    STORE.record_delivery(user_id, post_id, chat.id, 'success')
                    success.append(str(chat.id))
                except Exception as error:
                    STORE.record_delivery(user_id, post_id, target, 'failed', str(error))
                    failed.append(f'{target}: {scrub(error)[:100]}')
                STOP.wait(0.1)
            with contextlib.suppress(Exception):
                ui(chat_id, f'📢 Delivery finished\nSent: {len(success)}\nFailed: {len(failed)}\n' + '\n'.join(failed[:10]), home_keys())
        finally:
            with PUBLISH_GUARD:
                PUBLISHING.discard(user_id)
    threading.Thread(target=work, name=f'publish-{user_id}', daemon=True).start()
    ui(chat_id, f'📤 Publishing to {len(targets)} destinations. Results will appear here.')


def capture_album(message, data, replace_text=False):
    group = str(getattr(message, 'media_group_id', '') or '')
    if not group or message.content_type not in {'photo', 'video'}:
        raise UserError('Send 2–10 photos/videos together as an album.')
    data = copy.deepcopy(data)
    first = '_album_group' not in data
    if first:
        data.update(_album_group=group, _album_message_ids=[], album=[], photo_id=None, video_id=None, animation_id=None)
        data.pop('content', None)
        if replace_text or not data.get('text'):
            data['text'], data['entities'] = message.caption or '', entity_dicts(message.caption_entities)
    if data['_album_group'] != group:
        raise UserError('Finish the current album or use /cancel before sending another.')
    if message.message_id not in data['_album_message_ids']:
        if len(data['album']) >= 10:
            raise UserError('An album supports up to 10 items.')
        data['album'].append({'type': message.content_type, 'file_id': message.photo[-1].file_id if message.content_type == 'photo' else message.video.file_id})
        data['_album_message_ids'].append(message.message_id)
    old = STORE.state(message.chat.id, message.from_user.id)
    prompt_id = old['prompt_id'] if old else None
    if first:
        keyboard = types.InlineKeyboardMarkup().add(button('Album Uploaded — Continue', action='album_done', glyph='✅', color='green'), button('Cancel', action='cancel', glyph='❌', color='red'))
        prompt_id = ui(message.chat.id, '🖼️ Receiving your album.\nWait until every photo/video finishes uploading, then tap Continue.', keyboard).message_id
    STORE.set_state(message.chat.id, message.from_user.id, 'album_collect', data, prompt_id)


