def parse_schedule(text):
    parts = [part.strip() for part in text.split('|')]
    if len(parts) not in (1, 2):
        raise UserError('Use YYYY-MM-DD HH:MM | once, daily or weekly.')
    try:
        moment = datetime.strptime(parts[0], '%Y-%m-%d %H:%M').replace(tzinfo=IST)
    except ValueError:
        raise UserError('Invalid date. Use YYYY-MM-DD HH:MM in IST (24-hour time).')
    repeat = {'once': 0, 'daily': 86400, 'weekly': 604800}.get(parts[1].translate(NORMAL_TABLE).lower() if len(parts) == 2 else 'once')
    if repeat is None:
        raise UserError('Repeat must be once, daily or weekly.')
    when = int(moment.timestamp())
    if not int(time.time()) < when <= int(time.time()) + 366 * 86400:
        raise UserError('Choose a future date within one year.')
    return when, repeat


