def send_backup(chat_id, user_id, create=True):
    owner_only(chat_id, user_id)
    def work():
        try:
            if create:
                path = STORE.create_backup()
            else:
                files = list((STORE.folder / 'backups').glob('*.zip'))
                if not files:
                    raise UserError('No backup exists yet.')
                path = max(files, key=lambda p: p.stat().st_mtime)
            upload_limit = (2048 if isinstance(BOT, UserBotAPI) else 49) * 1024 * 1024
            if path.stat().st_size > upload_limit:
                raise UserError('Backup exceeds the current interface upload limit. Copy it from the server backups folder.')
            with path.open('rb') as stream:
                tg(BOT.send_document, chat_id, stream, caption=smallcaps('💾 Database backup · Keep this file private.'), visible_file_name=path.name, max_wait=30)
        except Exception as error:
            log_error('backup', error)
            with contextlib.suppress(Exception):
                ui(chat_id, f'❌ Backup download failed: {scrub(error)[:200]}')
    threading.Thread(target=work, name='owner-backup', daemon=True).start()
    ui(chat_id, '💾 Preparing your backup. It will be sent here shortly.')


def detailed_status(chat_id, user_id):
    owner_only(chat_id, user_id)
    day_start = int(datetime.now(IST).replace(hour=0, minute=0, second=0, microsecond=0).timestamp())
    now = int(time.time())
    with STORE.db() as c:
        users = c.execute('SELECT COUNT(*) FROM users').fetchone()[0]
        active = c.execute('SELECT COUNT(*) FROM users u LEFT JOIN nxt_profiles p USING(user_id) WHERE u.access_expiry>? AND COALESCE(p.banned,0)=0', (now,)).fetchone()[0]
        banned = c.execute('SELECT COUNT(*) FROM nxt_profiles WHERE banned=1').fetchone()[0]
        posts = c.execute('SELECT COUNT(*) FROM nxt_posts').fetchone()[0]
        delivered = c.execute("SELECT COUNT(*) FROM nxt_post_events WHERE created_at>=? AND status='success'", (day_start,)).fetchone()[0]
        failed = c.execute("SELECT COUNT(*) FROM nxt_post_events WHERE created_at>=? AND status!='success'", (day_start,)).fetchone()[0]
        pending = c.execute("SELECT COUNT(*) FROM nxt_schedules WHERE status='pending'").fetchone()[0]
        proofs = c.execute("SELECT COUNT(*) FROM nxt_payments WHERE status='pending'").fetchone()[0]
    ui(chat_id, f'📊 Bot Status\nUsers: {users}\nActive access: {active}\nBanned: {banned}\nSaved posts: {posts}\nSent today (IST): {delivered}\nFailed / unconfirmed today: {failed}\nPending schedules: {pending}\nPending proofs: {proofs}\nValidated custom emojis: {len(CATALOG.records)}\nBroadcast running: {BROADCAST_LOCK.locked()}', types.InlineKeyboardMarkup().add(button('Owner Panel', action='admin_owner_panel', glyph='⬅️')))


def feature_menu(message, action):
    if action not in {'posts', 'channels', 'scheduled', 'templates', 'emojis', 'vip'}:
        return False
    chat_id, user_id = message.chat.id, message.from_user.id
    if not require_join(chat_id, user_id):
        return True
    if action == 'posts':
        posts_panel(chat_id, user_id)
    elif action == 'channels':
        channels_panel(chat_id, user_id)
    elif action == 'scheduled':
        schedules_panel(chat_id, user_id)
    elif action == 'templates':
        if require_post(chat_id, user_id):
            templates_panel(chat_id)
    elif action == 'emojis':
        emoji_panel(chat_id, user_id)
    else:
        vip_panel(chat_id, user_id)
    return True


def feature_command(message):
    command = (message.text or '').split()[0].split('@')[0].lower()
    actions = {'/posts': 'posts', '/channels': 'channels', '/schedules': 'scheduled', '/templates': 'templates', '/emojis': 'emojis', '/vip': 'vip'}
    if command == '/backup':
        send_backup(message.chat.id, message.from_user.id)
        return True
    if command in actions:
        STORE.clear_state(message.chat.id, message.from_user.id)
        feature_menu(message, actions[command])
        return True
    return False


def feature_callback(call):
    chat_id, user_id, action = call.message.chat.id, call.from_user.id, call.data or ''
    exact = {'post_search', 'post_reset', 'channel_add', 'dest_all', 'dest_done', 'dest_confirm', 'multi_buttons', 'keep_buttons', 'add_album', 'add_animation', 'album_done', 'emoji_settings', 'emoji_preview', 'emoji_add', 'emoji_favorites', 'emoji_font', 'emoji_quote', 'emoji_reminders', 'vip', 'admin_status', 'admin_plans', 'admin_payment_instructions', 'admin_payment_confirm', 'admin_user_search', 'admin_user_reset', 'admin_welcome_editor', 'admin_welcome_buttons', 'admin_welcome_live', 'admin_menu_labels', 'admin_backups', 'admin_backup_now', 'admin_backup_latest', 'admin_backup_toggle', 'schedule_retry_confirm'}
    prefixes = ('posts:', 'post_open:', 'post_rename:', 'post_duplicate:', 'post_delete:', 'post_delete_yes:', 'post_send:', 'post_schedule:', 'channel_remove:', 'dest_pick:', 'template:', 'emoji_pack:', 'emoji_remove:', 'schedules:', 'schedule_open:', 'schedule_time:', 'schedule_content:', 'schedule_cancel:', 'schedule_preview:', 'schedule_retry:', 'vip_plan:', 'payment_cancel:', 'payment_history:', 'admin_users:', 'admin_user:', 'admin_user_ban:', 'admin_user_unban:', 'admin_user_balance:', 'admin_user_extend:', 'admin_user_revoke:', 'admin_revoke_confirm:', 'admin_payments:', 'admin_payment_open:', 'admin_payment_approve:', 'admin_payment_reject:', 'admin_plan:', 'admin_welcome_field:')
    if action not in exact and not action.startswith(prefixes):
        return False
    if action.startswith('admin_'):
        owner_only(chat_id, user_id)
    else:
        guard_user(user_id)
        if not require_join(chat_id, user_id):
            return True
    verb, _, value = action.partition(':')
    if verb == 'posts':
        posts_panel(chat_id, user_id, max(0, int(value)))
    elif verb == 'post_open':
        post_controls(chat_id, STORE.post(value, user_id))
    elif action == 'post_search':
        ask(chat_id, user_id, 'post_search', '🔎 Send a title, phrase or post ID to search.')
    elif action == 'post_reset':
        STORE.update_profile(user_id, post_search='')
        posts_panel(chat_id, user_id)
    elif verb == 'post_rename':
        STORE.post(value, user_id)
        ask(chat_id, user_id, 'post_rename', '📝 Send a name for this post (1–60 characters).', {'id': value})
    elif verb == 'post_duplicate':
        data = STORE.post(value, user_id)
        for key in ('id', 'edit_id', 'schedule_id'):
            data.pop(key, None)
        data['title'] = ('Copy · ' + post_title(data))[:60]
        data = STORE.save_post(user_id, chat_id, data)
        post_controls(chat_id, data)
    elif verb in {'post_delete', 'post_delete_yes'}:
        STORE.post(value, user_id)
        if verb == 'post_delete':
            keyboard = types.InlineKeyboardMarkup().add(button('Delete Post', action='post_delete_yes:' + value, glyph='🗑️', color='red'), button('Keep Post', action='post_open:' + value, glyph='⬅️'))
            ui(chat_id, '🗑️ Delete this saved post?\nIts pending schedules will also be cancelled. Published messages remain in their channels.', keyboard)
        else:
            STORE.delete_post(value, user_id)
            STORE.clear_state(chat_id, user_id)
            posts_panel(chat_id, user_id)
    elif verb in {'post_send', 'post_schedule'}:
        if require_post(chat_id, user_id):
            destination_panel(chat_id, user_id, value, 'schedule' if verb == 'post_schedule' else 'send')
    elif action == 'channel_add':
        ask(chat_id, user_id, 'channel_add', '📢 Make the bot an administrator.\nForward a channel post or send its numeric ID / @username.')
    elif verb == 'channel_remove':
        STORE.destination(int(value), user_id)
        STORE.remove_destination(int(value), user_id)
        channels_panel(chat_id, user_id)
    elif verb == 'dest_pick' or action in {'dest_all', 'dest_done'}:
        if not require_post(chat_id, user_id):
            return True
        data = active_prompt(call, {'post_destination'})
        selected = list(data.get('selected', []))
        if verb == 'dest_pick':
            entry = STORE.destination(int(value), user_id)
            selected.remove(entry['id']) if entry['id'] in selected else selected.append(entry['id'])
        elif action == 'dest_all':
            selected = [item['id'] for item in STORE.destinations(user_id)]
        else:
            targets = [STORE.destination(entry_id, user_id)['chat_id'] for entry_id in selected]
            prepare_destinations(chat_id, user_id, data, targets)
            return True
        destination_panel(chat_id, user_id, data['id'], data.get('purpose', 'send'), selected)
    elif action == 'dest_confirm':
        if require_post(chat_id, user_id):
            data = active_prompt(call, {'publish_confirm'})
            publish_many(chat_id, user_id, data['id'], data['targets'])
    elif action in {'multi_buttons', 'keep_buttons'}:
        if not require_post(chat_id, user_id):
            return True
        data = active_prompt(call, {'button_choice'})
        if action == 'keep_buttons':
            finish_post(chat_id, user_id, data)
        else:
            ask(chat_id, user_id, 'multi_buttons', buttons_help(), data, back='back_buttons', codes=[line for line in buttons_help().splitlines() if ' | ' in line])
    elif action in {'add_album', 'add_animation'}:
        if not require_post(chat_id, user_id):
            return True
        data = active_prompt(call, {'media_choice'})
        if u16(data.get('text', '')) > 1024:
            raise UserError('Shorten your caption to 1024 units before attaching media.')
        ask(chat_id, user_id, 'album_input' if action == 'add_album' else 'gif_input', '🖼️ Send 2–10 photos/videos as one album.' if action == 'add_album' else '🎞️ Send an animated GIF.', data, back='back_media')
    elif action == 'album_done':
        if require_post(chat_id, user_id):
            data = active_prompt(call, {'album_collect'})
            validate_post(data)
            data.pop('_album_group', None)
            data.pop('_album_message_ids', None)
            button_choice(chat_id, user_id, data)
    elif verb == 'template':
        if require_post(chat_id, user_id):
            if value not in TEMPLATES:
                raise UserError('Unknown template.')
            label, fields, template = TEMPLATES[value]
            form = '\n'.join(field + '=' for field in fields)
            ask(chat_id, user_id, 'template_fields', f'📝 {label}\nSend each field on its own line:\n{form}', {'template': value}, codes=[form])
    elif action == 'emoji_settings':
        emoji_panel(chat_id, user_id)
    elif verb == 'emoji_pack':
        if value not in PACKS:
            raise UserError('Unknown emoji pack.')
        STORE.update_profile(user_id, pack=value)
        emoji_panel(chat_id, user_id)
    elif action in {'emoji_font', 'emoji_quote', 'emoji_reminders'}:
        prefs = STORE.profile(user_id)['settings']
        if action == 'emoji_font':
            STORE.update_profile(user_id, font='normal' if prefs.get('font', 'smallcaps') == 'smallcaps' else 'smallcaps')
        elif action == 'emoji_quote':
            STORE.update_profile(user_id, quote_theme=not prefs.get('quote_theme', setting_on('quote_theme')))
        else:
            STORE.update_profile(user_id, reminders=not prefs.get('reminders', True))
        emoji_panel(chat_id, user_id)
    elif action == 'emoji_preview':
        prefs = STORE.profile(user_id)['settings']
        text, entities = premium_text('🎨 My emoji preview\n🔥 ⭐ 💎 ❤️ ✅ 🎉 👑', preferences=prefs)
        send_post(chat_id, {'content': text, 'entities': entities, 'quote_theme': prefs.get('quote_theme', setting_on('quote_theme'))})
    elif action == 'emoji_add':
        ask(chat_id, user_id, 'emoji_favorite', '⭐ Send one premium custom emoji to save as a favourite.')
    elif action == 'emoji_favorites':
        favourites_panel(chat_id, user_id)
    elif verb == 'emoji_remove':
        prefs = STORE.profile(user_id)['settings']
        items = {glyph: custom_id for glyph, custom_id in prefs.get('favorites', {}).items() if custom_id != value}
        STORE.update_profile(user_id, favorites=items)
        favourites_panel(chat_id, user_id)
    elif verb == 'schedules':
        schedules_panel(chat_id, user_id, max(0, int(value)))
    elif verb == 'schedule_open':
        schedule_panel(chat_id, user_id, value)
    elif verb == 'schedule_preview':
        send_post(chat_id, STORE.schedule(value, user_id)['post'])
    elif verb == 'schedule_cancel':
        STORE.change_schedule(value, user_id, 'cancel')
        schedule_panel(chat_id, user_id, value)
    elif verb == 'schedule_time':
        job = STORE.schedule(value, user_id)
        if job['status'] != 'pending':
            raise UserError('Only pending schedules can be edited.')
        ask(chat_id, user_id, 'schedule_edit_time', '⏰ Send YYYY-MM-DD HH:MM | once, daily or weekly.\nAll times use IST.', {'job_id': value})
    elif verb == 'schedule_content':
        if require_post(chat_id, user_id):
            job = STORE.schedule(value, user_id)
            if job['status'] != 'pending':
                raise UserError('Only pending schedule content can be edited.')
            draft = dict(job['post'], text=job['post'].get('raw_text', job['post'].get('text', '')), entities=job['post'].get('raw_entities', []), schedule_id=value)
            draft.pop('content', None)
            draft.pop('edit_id', None)
            ask(chat_id, user_id, 'post_text', '✏️ Send the updated text, photo, video, GIF or album for this schedule.', draft)
    elif verb == 'schedule_retry':
        job = STORE.schedule(value, user_id)
        if job['status'] not in {'failed', 'needs_review'}:
            raise UserError('This schedule does not need a retry.')
        keyboard = types.InlineKeyboardMarkup().add(button('Retry Unconfirmed Targets', action='schedule_retry_confirm', color='yellow', glyph='🔄'), button('Back', action='schedule_open:' + value, glyph='⬅️'))
        prompt = ui(chat_id, '🔄 Check the destination channels before retrying.\nAn interrupted request may already have delivered a post. Retrying an unconfirmed target can duplicate it.\nConfirmed successful targets will be skipped.', keyboard)
        STORE.set_state(chat_id, user_id, 'schedule_retry_confirm', {'job_id': value}, prompt.message_id)
    elif action == 'schedule_retry_confirm':
        if require_post(chat_id, user_id):
            data = active_prompt(call, {'schedule_retry_confirm'})
            STORE.change_schedule(data['job_id'], user_id, 'retry')
            STORE.clear_state(chat_id, user_id)
            schedule_panel(chat_id, user_id, data['job_id'])
    elif action == 'vip':
        vip_panel(chat_id, user_id)
    elif verb == 'vip_plan':
        private_only(chat_id, user_id)
        plan = STORE.plan(value)
        instructions = STORE.meta('payment_instructions', '')
        if not plan['enabled'] or not instructions:
            raise UserError('The owner has not opened purchases for this plan.')
        pending, _ = STORE.payment_list(user_id)
        if any(row['status'] == 'pending' for row in pending):
            raise UserError('You already have a pending proof. Check VIP Plans.')
