def feature_input(message, state):
    stage, data = state['stage'], state['data']
    stages = {'post_search', 'post_rename', 'channel_add', 'post_destination', 'multi_buttons', 'album_input', 'album_collect', 'gif_input', 'template_fields', 'emoji_favorite', 'schedule_time', 'schedule_edit_time', 'vip_proof', 'admin_plan', 'admin_payment_instructions', 'admin_user_search', 'admin_user_adjust', 'admin_welcome_field', 'admin_welcome_buttons', 'admin_menu_labels'}
    if stage not in stages:
        return False
    chat_id, user_id = message.chat.id, message.from_user.id
    text = (message.text or '').strip()
    if stage.startswith('admin_'):
        owner_only(chat_id, user_id)
    else:
        guard_user(user_id)
        if not require_join(chat_id, user_id):
            return True
    if stage in {'post_destination', 'multi_buttons', 'album_input', 'album_collect', 'gif_input', 'template_fields', 'schedule_time', 'schedule_edit_time'} and not require_post(chat_id, user_id):
        return True
    if stage == 'post_search':
        STORE.update_profile(user_id, post_search=text[:100])
        STORE.clear_state(chat_id, user_id)
        posts_panel(chat_id, user_id)
    elif stage == 'post_rename':
        if not 1 <= len(text) <= 60:
            raise UserError('Use a name containing 1–60 characters.')
        post = STORE.post(data['id'], user_id)
        post['title'] = text
        STORE.save_post(user_id, chat_id, post, data['id'])
        STORE.clear_state(chat_id, user_id)
        post_controls(chat_id, post)
    elif stage == 'channel_add':
        chat = checked_destination(user_id, destination_id(message))
        STORE.save_destination(user_id, chat.id, getattr(chat, 'title', '') or str(chat.id))
        STORE.clear_state(chat_id, user_id)
        channels_panel(chat_id, user_id)
    elif stage == 'post_destination':
        prepare_destinations(chat_id, user_id, data, [destination_id(message)])
    elif stage == 'multi_buttons':
        finish_post(chat_id, user_id, dict(data, buttons=parse_buttons(text), btn_name=None, btn_url=None))
    elif stage in {'album_input', 'album_collect'}:
        capture_album(message, data)
    elif stage == 'gif_input':
        animation = getattr(message, 'animation', None)
        document = getattr(message, 'document', None)
        if not animation and not (document and getattr(document, 'mime_type', '') == 'image/gif'):
            raise UserError('Send an animated GIF.')
        data = dict(data, animation_id=(animation or document).file_id, photo_id=None, video_id=None, album=[])
        validate_post(data)
        button_choice(chat_id, user_id, data)
    elif stage == 'template_fields':
        label, fields, template = TEMPLATES[data['template']]
        values = {}
        for line in text.splitlines():
            key, separator, value = line.partition('=')
            if not separator or key.strip() not in fields or not value.strip() or key.strip() in values:
                raise UserError('Fill each listed field once, using FIELD=value on its own line.')
            values[key.strip()] = value.strip()
        if set(values) != set(fields):
            raise UserError('Complete every field: ' + ', '.join(fields))
        values['link'] = good_url(values['link'])
        post = {'text': render_template_text(template, values), 'entities': [], 'title': label}
        validate_post(post)
        media_choice(chat_id, user_id, post)
    elif stage == 'emoji_favorite':
        custom = next((item for item in entity_dicts(message.entities or message.caption_entities) if item['type'] == 'custom_emoji'), None)
        if not custom:
            raise UserError('Send a premium custom emoji as text.')
        custom_id = str(custom['custom_emoji_id'])
        stickers = tg(BOT.get_custom_emoji_stickers, [custom_id])
        sticker = next((item for item in stickers if str(getattr(item, 'custom_emoji_id', '')) == custom_id), None)
        if sticker is None or not getattr(sticker, 'emoji', None):
            raise UserError('Telegram did not validate that custom emoji.')
        CATALOG.accept(stickers, [custom_id])
        favorites = STORE.profile(user_id)['settings'].get('favorites', {})
        if len(favorites) >= 30 and sticker.emoji not in favorites:
            raise UserError('Remove a favourite before adding more than 30.')
        favorites[sticker.emoji] = custom_id
        STORE.update_profile(user_id, favorites=favorites)
        STORE.clear_state(chat_id, user_id)
        favourites_panel(chat_id, user_id)
    elif stage in {'schedule_time', 'schedule_edit_time'}:
        run_at, repeat = parse_schedule(text)
        if stage == 'schedule_time':
            post = STORE.post(data['id'], user_id)
            job_id = STORE.create_schedule(user_id, chat_id, post, data['targets'], run_at, repeat)
        else:
            job_id = data['job_id']
            STORE.change_schedule(job_id, user_id, 'time', run_at=run_at, repeat_seconds=repeat)
        STORE.clear_state(chat_id, user_id)
        schedule_panel(chat_id, user_id, job_id)
    elif stage == 'vip_proof':
        private_only(chat_id, user_id)
        if getattr(message, 'media_group_id', None):
            raise UserError('Send one proof photo or document at a time.')
        document = getattr(message, 'document', None)
        if message.content_type == 'photo':
            kind, file_id = 'photo', message.photo[-1].file_id
        elif document and (str(getattr(document, 'mime_type', '')).startswith('image/') or getattr(document, 'mime_type', '') == 'application/pdf'):
            kind, file_id = 'document', document.file_id
        else:
            raise UserError('Send proof as one photo, image document or PDF.')
        request_id = STORE.submit_payment(user_id, data['plan'], kind, file_id, chat_id, message.message_id)
        STORE.clear_state(chat_id, user_id)
        ui(chat_id, f'🧾 Proof submitted\nRequest: {request_id}\nWaiting for owner review. Use VIP Plans to check status.', home_keys(), codes=[request_id])
        try:
            payment_review_panel(ADMIN_ID, ADMIN_ID, request_id)
        except Exception as error:
            log_error('payment owner notification', error)
    elif stage == 'admin_plan':
        parts = [part.strip() for part in text.split('|')]
        if len(parts) != 4 or not parts[1].isdigit() or parts[3].lower() not in {'on', 'off'}:
            raise UserError('Use NAME | DAYS | PRICE | on/off.')
        STORE.update_plan(data['plan_id'], parts[0], int(parts[1]), parts[2], parts[3].lower() == 'on')
        STORE.audit('plan_edit', user_id, data['plan_id'])
        STORE.clear_state(chat_id, user_id)
        plans_panel(chat_id, user_id)
    elif stage == 'admin_payment_instructions':
        if not text or u16(text) > 1800:
            raise UserError('Use 1–1800 text units.')
        STORE.setting('payment_instructions', '' if text.upper() == 'CLEAR' else text)
        STORE.clear_state(chat_id, user_id)
        plans_panel(chat_id, user_id)
    elif stage == 'admin_user_search':
        STORE.update_profile(user_id, user_search=text[:100])
        STORE.clear_state(chat_id, user_id)
        users_panel(chat_id, user_id)
    elif stage == 'admin_user_adjust':
        if not re.fullmatch(r'[+-]?\d{1,10}', text):
            raise UserError('Send a whole number.')
        STORE.manage_user(data['target'], data['action'], int(text))
        STORE.clear_state(chat_id, user_id)
        user_panel(chat_id, user_id, data['target'])
    elif stage == 'admin_welcome_field':
        key = data['key']
        if key not in {'welcome_text', 'owner_label', 'owner_link', 'developer_label', 'developer_link'}:
            raise UserError('Unknown welcome setting.')
        value = '' if text.upper() == 'CLEAR' else text
        if value and key.endswith('_link'):
            value = good_url(value)
        elif key == 'welcome_text':
            if u16(value) > 2600 or set(re.findall(r'\{([^{}]+)\}', value)) - WELCOME_FIELDS:
                raise UserError('Use up to 2600 units and only the listed placeholders.')
        elif len(value) > 80:
            raise UserError('Use a name up to 80 characters.')
        STORE.setting(key, value)
        STORE.clear_state(chat_id, user_id)
        welcome_editor(chat_id, user_id)
    elif stage == 'admin_welcome_buttons':
        rows = [] if text.upper() == 'CLEAR' else parse_buttons(text)
        STORE.setting('welcome_buttons', json.dumps(rows, ensure_ascii=False))
        STORE.clear_state(chat_id, user_id)
        welcome_editor(chat_id, user_id)
    elif stage == 'admin_menu_labels':
        labels = {} if text.upper() == 'CLEAR' else json.loads(STORE.meta('menu_labels', '{}'))
        if text.upper() != 'CLEAR':
            for line in text.splitlines():
                key, separator, label = line.partition('=')
                key, label = key.strip(), label.strip()
                if not separator or key not in MENU or not 1 <= len(label) <= 40 or not normal_label(label):
                    raise UserError('Use known KEY=LABEL pairs with labels of 1–40 characters.')
                if any(normal_label(label) == normal_label(MENU[other]) for other in MENU if other != key):
                    raise UserError('A label cannot use another menu option\'s original name.')
                labels[key] = label
        all_labels = [normal_label(labels.get(key, MENU[key])) for key in MENU]
        if len(set(all_labels)) != len(all_labels):
            raise UserError('Every menu label must be different.')
        STORE.setting('menu_labels', json.dumps(labels, ensure_ascii=False))
        STORE.clear_state(chat_id, user_id)
        ui(chat_id, '✅ Menu labels saved.', main_menu(user_id))
    return True


def delivered_ids(result):
    items = result if isinstance(result, list) else [result]
    return [int(item.message_id) for item in items if getattr(item, 'message_id', None)]


def process_schedule(job):
    job_id, user_id, cycle = job['id'], job['user_id'], job['run_at']
    failure, uncertain = [], False
    try:
        guard_user(user_id)
        if not has_access(user_id):
            raise UserError('Access expired. Renew access before retrying.')
        if missing_channels(user_id):
            raise UserError('Required channel membership is missing.')
        for target in job['targets']:
            if STOP.is_set():
                raise DeliveryUncertain('Bot stopped during delivery. Check channels before retrying.')
            with STORE.db() as c:
                previous = c.execute('SELECT status FROM nxt_deliveries WHERE job_id=? AND cycle_at=? AND target_id=?', (job_id, cycle, target)).fetchone()
            if previous and previous[0] == 'success':
                continue
            if previous and previous[0] in {'sending', 'uncertain'}:
                uncertain = True
                failure.append(f'{target}: previous delivery unconfirmed')
                continue
            # Revalidate user and bot permissions for every channel at delivery time.
            try:
                guard_user(user_id)
                if not has_access(user_id):
                    raise UserError('Access expired during delivery.')
                chat = checked_destination(user_id, target)
            except Exception as error:
                detail = scrub(error)[:250]
                with STORE.db() as c:
                    c.execute("INSERT INTO nxt_deliveries(job_id,cycle_at,target_id,status,detail) VALUES (?,?,?,'failed',?) ON CONFLICT(job_id,cycle_at,target_id) DO UPDATE SET status=excluded.status,detail=excluded.detail", (job_id, cycle, target, detail))
                STORE.record_delivery(user_id, job['post_id'], target, 'failed', detail)
                failure.append(f'{target}: {detail}')
                continue
            with STORE.db() as c:
                c.execute("INSERT INTO nxt_deliveries(job_id,cycle_at,target_id,status) VALUES (?,?,?,'sending') ON CONFLICT(job_id,cycle_at,target_id) DO UPDATE SET status='sending',detail=''", (job_id, cycle, target))
            try:
                result = send_post(chat.id, job['post'])
            except Exception as error:
                # Explicit API rejection is known failure; transport errors may have delivered.
                ambiguous = not isinstance(error, (ApiTelegramException, UserError)) or isinstance(error, DeliveryUncertain)
                status = 'uncertain' if ambiguous else 'failed'
                uncertain = uncertain or ambiguous
                detail = scrub(error)[:250]
                with STORE.db() as c:
                    c.execute('UPDATE nxt_deliveries SET status=?,detail=? WHERE job_id=? AND cycle_at=? AND target_id=?', (status, detail, job_id, cycle, target))
                STORE.record_delivery(user_id, job['post_id'], target, status, detail)
                failure.append(f'{target}: {detail}')
            else:
                with STORE.db() as c:
                    c.execute("UPDATE nxt_deliveries SET status='success',message_ids=?,detail='' WHERE job_id=? AND cycle_at=? AND target_id=?", (json.dumps(delivered_ids(result)), job_id, cycle, target))
                STORE.record_delivery(user_id, job['post_id'], target, 'success')
            STOP.wait(0.1)
    except Exception as error:
        uncertain = uncertain or isinstance(error, DeliveryUncertain)
        failure.append(scrub(error)[:250])
    status = 'needs_review' if uncertain else 'failed' if failure else 'done'
    next_run = cycle
    if not failure and job['repeat_seconds']:
        interval = job['repeat_seconds']
        next_run = cycle + (max(0, int(time.time()) - cycle) // interval + 1) * interval
        status = 'pending'
    with STORE.db() as c:
        c.execute('UPDATE nxt_schedules SET status=?,run_at=?,last_error=? WHERE id=? AND status=\'running\'', (status, next_run, '\n'.join(failure)[:1500], job_id))
    with contextlib.suppress(Exception):
        keyboard = types.InlineKeyboardMarkup().add(button('View Schedule', action='schedule_open:' + job_id, glyph='⏰'))
        ui(job['origin_chat'], f'⏰ Scheduled post {job_id}\nResult: {status}\n' + ('\n'.join(failure)[:1200] if failure else 'Delivered to all selected destinations.'), keyboard, codes=[job_id])


def send_expiry_reminders(now=None):
    now = int(time.time()) if now is None else now
    with STORE.db() as c:
        rows = c.execute("SELECT u.user_id,u.access_expiry FROM users u LEFT JOIN nxt_profiles p USING(user_id) WHERE COALESCE(p.banned,0)=0 AND COALESCE(json_extract(p.settings_json,'$.reminders'),1)=1 AND u.access_expiry>? AND u.access_expiry<=? AND u.user_id!=? AND NOT EXISTS (SELECT 1 FROM nxt_expiry_notices n WHERE n.user_id=u.user_id AND n.expiry=u.access_expiry AND n.kind=CASE WHEN u.access_expiry>? THEN 'expiring' ELSE 'expired' END) ORDER BY u.access_expiry LIMIT 100", (now - 7 * 86400, now + 86400, ADMIN_ID, now)).fetchall()
    for row in rows:
        if STOP.is_set():
            return
        user_id, expiry = row['user_id'], row['access_expiry']
        if not STORE.profile(user_id)['settings'].get('reminders', True):
            continue
        kind = 'expiring' if expiry > now else 'expired'
        with STORE.db() as c:
            inserted = c.execute("INSERT OR IGNORE INTO nxt_expiry_notices VALUES (?,?,?,'sending')", (user_id, expiry, kind)).rowcount
        if inserted != 1:
            continue
        try:
            keyboard = types.InlineKeyboardMarkup().add(button('VIP Plans', action='vip', glyph='💎'))
            text = f'⏰ Your access expires on {datetime.fromtimestamp(expiry, IST):%d %b %Y %H:%M} IST.' if kind == 'expiring' else '⏰ Your posting access has expired. Renew VIP or invite a new verified friend to extend access.'
            ui(user_id, text, keyboard)
            status = 'sent'
        except Exception as error:
            log_error('expiry reminder', error)
            status = 'failed'
        with STORE.db() as c:
            c.execute('UPDATE nxt_expiry_notices SET status=? WHERE user_id=? AND expiry=? AND kind=?', (status, user_id, expiry, kind))
        STOP.wait(0.06)


def feature_worker_tick():
    for _ in range(10):
        if STOP.is_set():
            return
        job = STORE.claim_due()
        if job is None:
            break
        try:
            process_schedule(job)
        except Exception as error:
            log_error('scheduled delivery', error)
            with STORE.db() as c:
                c.execute("UPDATE nxt_schedules SET status='needs_review',last_error=? WHERE id=? AND status='running'", (scrub(error)[:500], job['id']))
    now = int(time.time())
    last_reminder = int(STORE.meta('last_expiry_check', '0'))
    if now - last_reminder >= 300:
        send_expiry_reminders(now)
        STORE.setting('last_expiry_check', str(now))
    if setting_on('automatic_backups') and now - int(STORE.meta('last_auto_backup', '0')) >= 86400:
        STORE.create_backup(automatic=True)


def start_feature_worker():
    global FEATURE_THREAD
    STORE.recover_schedules()
    def work():
        while not STOP.is_set():
            try:
                feature_worker_tick()
            except Exception as error:
                log_error('feature worker', error)
            STOP.wait(5)
    FEATURE_THREAD = threading.Thread(target=work, name='schedule-backup-reminders', daemon=True)
    FEATURE_THREAD.start()


def feature_regression(fake, check, rejected):
    """Integration checks use the same local fake and temporary DB as self_test."""
    fake.send_animation = lambda chat_id, content, **kwargs: fake.send('animation', chat_id, content, kwargs)
    fake.send_document = lambda chat_id, content, **kwargs: fake.send('document', chat_id, content, kwargs)
    def album_send(chat_id, media, **kwargs):
        return [fake.send('photo' if isinstance(item, types.InputMediaPhoto) else 'video', chat_id, item.media, {'caption': item.caption or '', 'caption_entities': item.caption_entities or []}) for item in media]
    fake.send_media_group = album_send
    def deny(function, label):
        try:
            function()
        except UserError:
            check(True, label)
        else:
            raise AssertionError(label)
    def callback(action, uid=222):
        callback_action(fake.callback(uid, action))
    def input_text(text, uid=222, **extra):
        process_input(fake.message(uid, text, **extra), STORE.state(uid, uid))
    def start_text(text='A useful post 🔥'):
        menu_action(fake.message(222, 'Make Post'), 'post')
        input_text(text)
        callback('no_media')
    def due(job_id):
        with STORE.db() as c:
            c.execute('UPDATE nxt_schedules SET run_at=? WHERE id=?', (int(time.time()) - 3, job_id))
    def sent_to(target):
        return sum(event['chat'] == target and event['kind'] in {'text', 'photo', 'video', 'animation'} for event in fake.events if 'chat' in event)
    def new_job(post, targets=None, repeat=0):
        return STORE.create_schedule(222, 222, post, targets or [-100100], int(time.time()) + 7200, repeat)

    check(STORE.meta('premium_features_version') == '1', 'additive premium schema initialized')
    check(bool(list(STORE.folder.glob('bot.db.before-premium-*.bak'))), 'premium migration backs up the old DB')
    check(not any('leaderboard' in row[0] for row in sqlite3.connect(STORE.path).execute("SELECT name FROM sqlite_master WHERE type='table'")), 'no referral leaderboard added')
    for action in ('admin_users:0', 'admin_plans', 'admin_payments:0', 'admin_welcome_editor', 'admin_backups', 'admin_menu_labels', 'admin_status'):
        deny(lambda action=action: callback(action, 333), 'all new owner routes reject non-owner')

    rows = parse_buttons('1 | Support | https://example.com/Aa | blue | 💬\n1 | Join | https://t.me/test | green | 📢\n2 | Owner | tg://user?id=111 | red | 👑')
    check([len(row) for row in rows] == [2, 1], 'button rows and per-button colors parsed')
    deny(lambda: parse_buttons('1 | Bad | javascript:alert(1) | blue'), 'invalid button scheme rejected')
    deny(lambda: parse_buttons('1 | Bad | https://example.com | purple'), 'unsupported color rejected')
    deny(lambda: normalized_buttons({'buttons': [rows[0] * 4]}), 'button row width capped')
    start_text()
    stale = STORE.state(222, 222)['prompt_id']
    callback('multi_buttons')
    sample_prompt = next(e for e in reversed(fake.events) if e['kind'] == 'text')
    check('1 | Support | https://t.me/YourGroup | blue | 💬' in sample_prompt['text'], 'button editor example stays copyable in the small-caps UI')
    input_text('1 | Support | https://example.com/Aa | blue | 💬\n1 | Join | https://t.me/test | green | 📢\n2 | Owner | tg://user?id=111 | red | 👑')
    multi = STORE.post('latest', 222)
    check([len(row) for row in multi['buttons']] == [2, 1], 'multi-button builder saves rows')
    deny(lambda: callback_action(fake.callback(222, 'multi_buttons', message_id=stale)), 'stale multi-button prompts rejected')
    keyboard = post_keyboard(multi).to_dict()['inline_keyboard']
    check(keyboard[0][1]['style'] == 'success' and keyboard[1][0]['style'] == 'danger', 'individual button styles retained')

    callback('post_rename:' + multi['id'])
    input_text('Launch Post')
    callback('post_duplicate:' + multi['id'])
    duplicate = STORE.post('latest', 222)
    check(duplicate['id'] != multi['id'] and duplicate['buttons'] == multi['buttons'], 'duplicate creates an independent saved post')
    STORE.update_profile(222, post_search='Launch Post')
    found, _ = STORE.posts_page(222, 'Launch Post')
    check(any(p['id'] == multi['id'] for p in found), 'post title search works')
    deny(lambda: STORE.delete_post(multi['id'], 333), 'cross-user post deletion rejected')
    callback('post_reset')

    callback('channel_add')
    input_text('-100100')
    first = STORE.destinations(222)[0]
    STORE.save_destination(222, -100200, 'Second Channel')
    STORE.save_destination(222, -100100, 'Renamed Channel')
    check(len(STORE.destinations(222)) == 2, 'saving a destination twice does not duplicate it')
    deny(lambda: STORE.destination(first['id'], 333), 'saved channels isolated by user')
