USER_CLIENT = None
USERBOT_SECRETS = []
RUN_MODE = (os.environ.get('RUN_MODE') or 'userbot').strip().lower()


def userbot_config():
    api_id = str(os.environ.get('API_ID') or os.environ.get('TELEGRAM_API_ID') or API_ID)
    api_hash = os.environ.get('API_HASH') or os.environ.get('TELEGRAM_API_HASH') or API_HASH
    session = os.environ.get('SESSION_STRING') or os.environ.get('STRING_SESSION') or ''
    USERBOT_SECRETS[:] = list(dict.fromkeys(value for raw in (api_hash, session) for value in (raw, raw.strip()) if value))
    api_id, api_hash = api_id.strip(), api_hash.strip()
    if RUN_MODE not in {'userbot', 'hybrid'}:
        raise UserError('RUN_MODE must be userbot or hybrid.')
    if not api_id.isdigit() or not 0 < int(api_id) < 2**31:
        raise UserError('Set a valid numeric Telegram API_ID in code or environment.')
    if not re.fullmatch(r'[a-fA-F0-9]{32}', api_hash):
        raise UserError('Set a valid 32-character Telegram API_HASH in code or environment.')
    if not session.strip():
        raise UserError('Set SESSION_STRING to your Telethon StringSession. Do not send it in chat.')
    allowed = {ADMIN_ID}
    for value in os.environ.get('USERBOT_ALLOWED_USERS', '').split(','):
        if value.strip():
            if not value.strip().isdigit():
                raise UserError('USERBOT_ALLOWED_USERS must contain comma-separated numeric user IDs.')
            allowed.add(int(value.strip()))
    return SimpleNamespace(api_id=int(api_id), api_hash=api_hash, session=session.strip(), owner_id=ADMIN_ID, mode=RUN_MODE, allowed_users=allowed)


def mt_entities(entities):
    classes = {'bold': 'MessageEntityBold', 'italic': 'MessageEntityItalic', 'underline': 'MessageEntityUnderline',
               'strikethrough': 'MessageEntityStrike', 'spoiler': 'MessageEntitySpoiler', 'code': 'MessageEntityCode',
               'url': 'MessageEntityUrl', 'email': 'MessageEntityEmail', 'mention': 'MessageEntityMention',
               'hashtag': 'MessageEntityHashtag', 'cashtag': 'MessageEntityCashtag', 'bot_command': 'MessageEntityBotCommand',
               'phone_number': 'MessageEntityPhone'}
    result = []
    for item in entity_dicts(entities):
        args = dict(offset=int(item['offset']), length=int(item['length']))
        kind = item['type']
        if kind == 'custom_emoji':
            value = tl_types.MessageEntityCustomEmoji(**args, document_id=int(item['custom_emoji_id']))
        elif kind == 'text_link':
            value = tl_types.MessageEntityTextUrl(**args, url=item['url'])
        elif kind == 'text_mention':
            user = item.get('user') or {}
            value = tl_types.MessageEntityTextUrl(**args, url=f'tg://user?id={user["id"]}')
        elif kind == 'pre':
            value = tl_types.MessageEntityPre(**args, language=item.get('language', ''))
        elif kind in {'blockquote', 'expandable_blockquote'}:
            value = tl_types.MessageEntityBlockquote(**args, collapsed=kind == 'expandable_blockquote')
        elif kind in classes:
            value = getattr(tl_types, classes[kind])(**args)
        else:
            continue
        result.append(value)
    return result


def bot_entities_from_mt(entities):
    names = {'MessageEntityBold': 'bold', 'MessageEntityItalic': 'italic', 'MessageEntityUnderline': 'underline',
             'MessageEntityStrike': 'strikethrough', 'MessageEntitySpoiler': 'spoiler', 'MessageEntityCode': 'code',
             'MessageEntityPre': 'pre', 'MessageEntityTextUrl': 'text_link', 'MessageEntityUrl': 'url',
             'MessageEntityEmail': 'email', 'MessageEntityMention': 'mention', 'MessageEntityHashtag': 'hashtag',
             'MessageEntityCashtag': 'cashtag', 'MessageEntityBotCommand': 'bot_command', 'MessageEntityPhone': 'phone_number',
             'MessageEntityCustomEmoji': 'custom_emoji'}
    result = []
    for entity in entities or []:
        name = type(entity).__name__
        kind = names.get(name)
        if name == 'MessageEntityBlockquote':
            kind = 'expandable_blockquote' if getattr(entity, 'collapsed', False) else 'blockquote'
        if name in {'MessageEntityMentionName', 'InputMessageEntityMentionName'}:
            kind = 'text_link'
        if not kind:
            continue
        item = {'type': kind, 'offset': entity.offset, 'length': entity.length}
        if kind == 'custom_emoji':
            item['custom_emoji_id'] = str(entity.document_id)
        if kind == 'text_link':
            user = getattr(entity, 'user_id', None)
            item['url'] = getattr(entity, 'url', None) or f'tg://user?id={getattr(user, "user_id", user)}'
        if kind == 'pre':
            item['language'] = entity.language
        result.append(item)
    return result


def replace_emoji_spans(text, entities, replacements):
    """Apply UTF-16 emoji variation fixes and remap every formatting boundary."""
    original = text.encode('utf-16-le')
    ordered = sorted(replacements, key=lambda value: value[0])
    output, position = [], 0
    for start, length, replacement in ordered:
        if start < position:
            raise UserError('Overlapping custom emoji entities.')
        output.extend((original[position * 2:start * 2], replacement.encode('utf-16-le')))
        position = start + length
    output.append(original[position * 2:])
    def boundary(value):
        delta = 0
        for start, length, replacement in ordered:
            if value >= start + length:
                delta += u16(replacement) - length
            elif start < value < start + length:
                raise UserError('A formatting boundary splits a custom emoji.')
        return value + delta
    result = []
    for item in entity_dicts(entities):
        start, end = boundary(item['offset']), boundary(item['offset'] + item['length'])
        result.append(dict(item, offset=start, length=end - start))
    return b''.join(output).decode('utf-16-le'), result


def userbot_actor(data):
    if data.get('id') and STORE is not None:
        with STORE.db() as c:
            row = c.execute('SELECT owner_id FROM nxt_posts WHERE id=?', (data['id'],)).fetchone()
        if row and row[0] is not None:
            return row[0]
    return ADMIN_ID


def media_reference(chat_id, message_id, kind):
    return f'user-media:{int(chat_id)}:{int(message_id)}:{kind}'


def parse_media_reference(value):
    match = re.fullmatch(r'user-media:(-?\d+):(\d+):(photo|video|animation|document)', str(value))
    return (int(match[1]), int(match[2]), match[3]) if match else None


def has_user_media(data):
    return any(parse_media_reference(data.get(key)) for key in ('photo_id', 'video_id', 'animation_id')) or any(parse_media_reference(item.get('file_id')) for item in data.get('album') or [])


def post_links(data):
    text, entities = '', []
    for row in normalized_buttons(data):
        if text:
            text += '\n'
        for index, item in enumerate(row):
            if index:
                text += '  ·  '
            icon_start = u16(text)
            text += item['glyph'] + ' '
            icon_id = item.get('custom_id') or (CATALOG.choose(item['glyph'], ui=True) if CATALOG is not None else None)
            if icon_id:
                entities.append({'type': 'custom_emoji', 'offset': icon_start, 'length': u16(item['glyph']), 'custom_emoji_id': str(icon_id)})
            start = u16(text)
            text += item['label']
            entities.append({'type': 'text_link', 'offset': start, 'length': u16(item['label']), 'url': item['url']})
    return text, entities


class UserTransport:
    """One MTProto connection, owned by one asyncio loop; sync callers use a bridge."""
    def __init__(self, config, client_factory=TelegramClient):
        self.config, self.factory = config, client_factory
        self.loop, self.thread, self.client, self.me, self.error = None, None, None, None, None
        self.ready = threading.Event()
        self.documents = {}
        self.entities = {}
        self.generated = set()
        self.pending_outputs = 0
        self.idle = None
        self.on_event = None
        self._command_lock = None
        self.expected_echoes = {}
        self.stopping = threading.Event()

    def start(self):
        self.thread = threading.Thread(target=self._run, name='premium-user-account', daemon=True)
        self.thread.start()
        if not self.ready.wait(45):
            self.stop()
            raise UserError('Telegram user account connection timed out. Check network and API settings.')
        if self.error:
            self.thread.join(timeout=3)
            raise UserError(scrub(self.error))
        return self

    def _run(self):
        self.loop = asyncio.new_event_loop()
        asyncio.set_event_loop(self.loop)
        try:
            self.loop.run_until_complete(self._connect())
            self.loop.call_soon(self.ready.set)
            self.loop.run_forever()
        except Exception as error:
            self.error = scrub(error)
        finally:
            self.ready.set()
            if self.client is not None:
                with contextlib.suppress(Exception):
                    self.loop.run_until_complete(self.client.disconnect())
            tasks = asyncio.all_tasks(self.loop)
            for task in tasks:
                task.cancel()
            if tasks:
                self.loop.run_until_complete(asyncio.gather(*tasks, return_exceptions=True))
            self.loop.close()

    async def _connect(self):
        try:
            session = StringSession(self.config.session)
        except Exception:
            raise UserError('SESSION_STRING is not a valid Telethon StringSession.') from None
        self.client = self.factory(session, self.config.api_id, self.config.api_hash, request_retries=0,
                                   flood_sleep_threshold=0, connection_retries=3, auto_reconnect=True,
                                   receive_updates=self.config.mode == 'userbot')
        self.idle, self._command_lock = asyncio.Event(), asyncio.Lock()
        self.idle.set()
        await self.client.connect()
        if not await self.client.is_user_authorized():
            raise UserError('The session is expired or unauthorized. Create a fresh session on your own device.')
        self.me = await self.client.get_me()
        if not self.me or getattr(self.me, 'bot', False):
            raise UserError('SESSION_STRING must belong to a user account, not a bot.')
        if self.me.id != self.config.owner_id:
            raise UserError('Session account ID differs from BOT_ADMIN_ID. Set BOT_ADMIN_ID to your Premium account ID.')
        if not getattr(self.me, 'premium', False):
            raise UserError('The session account does not currently have Telegram Premium.')
        self.entities[self.me.id] = self.me
        if self.config.mode == 'userbot':
            self.client.add_event_handler(self._event, events.NewMessage(outgoing=True))
        if hasattr(self.client, 'disconnected'):
            asyncio.create_task(self._watch_disconnect())

    async def _watch_disconnect(self):
        await self.client.disconnected
        if not self.stopping.is_set():
            self.error = 'User account disconnected after reconnect attempts. Restart and check the session.'
            queue_alert('account_connection', self.error)
            self.loop.stop()

    def call(self, coroutine, timeout=120):
        if not self.loop or not self.loop.is_running() or self.thread is threading.current_thread():
            coroutine.close()
            raise UserError('User account connection is unavailable.')
        future = asyncio.run_coroutine_threadsafe(coroutine, self.loop)
        try:
            return future.result(timeout=timeout)
        except concurrent.futures.TimeoutError:
            future.cancel()
            raise DeliveryUncertain('Telegram response timed out. Check the destination before retrying.') from None
        except telethon_errors.FloodWaitError as error:
            raise UserError(f'Telegram FloodWait: wait {error.seconds} seconds before retrying.') from None
        except telethon_errors.RPCError as error:
            raise UserError(f'Telegram rejected the request: {type(error).__name__}.') from None

    def stop(self):
        self.stopping.set()
        if self.loop and self.loop.is_running():
            if self.thread is threading.current_thread():
                self.loop.stop()
                return
            with contextlib.suppress(Exception):
                asyncio.run_coroutine_threadsafe(self.client.disconnect(), self.loop).result(timeout=10)
            with contextlib.suppress(RuntimeError):
                self.loop.call_soon_threadsafe(self.loop.stop)
        if self.thread and self.thread is not threading.current_thread():
            self.thread.join(timeout=10)

    async def resolve(self, target):
        if str(target) in {'me', str(self.me.id)}:
            return self.me
        target = int(target) if str(target).lstrip('-').isdigit() else target
        if target in self.entities:
            return self.entities[target]
        try:
            entity = await self.client.get_entity(target)
        except ValueError:
            if not isinstance(target, int):
                raise UserError('Destination not found. Use a channel @username or its numeric ID.') from None
            entity = None
            async for dialog in self.client.iter_dialogs():
                self.entities[dialog.id] = dialog.entity
                if dialog.id == target:
                    entity = dialog.entity
                    break
            if entity is None:
                raise UserError('Join the destination with your Premium account first, or use its @username.') from None
        self.entities[tl_utils.get_peer_id(entity)] = entity
        return entity

    async def checked_target(self, target, actor=None):
        actor = self.me.id if actor is None else int(actor)
        if actor not in self.config.allowed_users:
            raise UserError('Premium account publishing is owner-only unless USERBOT_ALLOWED_USERS explicitly allows your ID.')
        entity = await self.resolve(target)
        if tl_utils.get_peer_id(entity) == self.me.id:
            return entity
        if isinstance(entity, tl_types.User):
            raise UserError('Use Saved Messages or a channel/group you administer for user-account posts.')
        permission = await self.client.get_permissions(entity, self.me)
        if not (getattr(permission, 'is_admin', False) or getattr(permission, 'is_creator', False)):
            raise UserError('Make your Premium account an administrator of the destination.')
        if getattr(entity, 'broadcast', False) and not getattr(permission, 'is_creator', False):
            rights = getattr(getattr(permission, 'participant', None), 'admin_rights', None)
            if not getattr(rights, 'post_messages', False):
                raise UserError('Your Premium account needs permission to post in this channel.')
        return entity

    async def emoji_documents(self, ids):
        ids = list(dict.fromkeys(int(value) for value in ids))
        missing = [value for value in ids if value not in self.documents]
        for start in range(0, len(missing), 100):
            documents = await self.client(tl_functions.messages.GetCustomEmojiDocumentsRequest(missing[start:start + 100]))
            for document in documents:
                for attribute in getattr(document, 'attributes', []):
                    if isinstance(attribute, tl_types.DocumentAttributeCustomEmoji):
                        self.documents[document.id] = (document, attribute.alt)
        return {value: self.documents[value] for value in ids if value in self.documents}

    async def prepare(self, text, entities):
        values = entity_dicts(entities)
        valid_entities(text, values)
        requested = [item['custom_emoji_id'] for item in values if item['type'] == 'custom_emoji']
        docs = await self.emoji_documents(requested) if requested else {}
        kept, replacements = [], []
        for item in values:
            if item['type'] != 'custom_emoji':
                kept.append(item)
                continue
            record = docs.get(int(item['custom_emoji_id']))
            if not record:
                raise UserError('A custom emoji in this post is unavailable. Replace it or select another emoji pack.')
            begin, end = item['offset'] * 2, (item['offset'] + item['length']) * 2
            glyph = text.encode('utf-16-le')[begin:end].decode('utf-16-le')
            alt = record[1]
            if glyph.replace('\ufe0f', '') != alt.replace('\ufe0f', ''):
                # Old catalog fallback IDs may represent a different glyph. Keep the
                # intended Unicode emoji instead of silently changing its meaning.
                continue
            kept.append(item)
            if glyph != alt:
                replacements.append((item['offset'], item['length'], alt))
        if replacements:
            text, kept = replace_emoji_spans(text, kept, replacements)
        valid_entities(text, kept)
        return text, mt_entities(kept)

    async def emit(self, operation, echo_text=None):
        if echo_text is not None:
            self.expected_echoes[str(echo_text)] = time.monotonic() + 120
            if len(self.expected_echoes) > 1000:
                self.expected_echoes = {key: end for key, end in self.expected_echoes.items() if end > time.monotonic()}
        self.pending_outputs += 1
        self.idle.clear()
        try:
            result = await operation
            for message in result if isinstance(result, list) else [result]:
                if getattr(message, 'id', None):
                    self.generated.add((getattr(message, 'chat_id', self.me.id), message.id))
            if len(self.generated) > 2000:
                self.generated = set(sorted(self.generated, key=lambda item: item[1])[-1000:])
            return result
        finally:
            self.pending_outputs -= 1
            if not self.pending_outputs:
                self.idle.set()

    async def _event(self, event):
        if not event.out or event.sender_id != self.me.id or event.chat_id != self.me.id or self.on_event is None:
            return
        await self.idle.wait()
        if (event.chat_id, event.id) in self.generated:
            self.expected_echoes.pop(event.raw_text or '', None)
            return
        if self.expected_echoes.get(event.raw_text or '', 0) > time.monotonic():
            return
        async with self._command_lock:
            try:
                await self.on_event(event)
            except Exception as error:
                log_error('userbot command', error)
                with contextlib.suppress(Exception):
                    text = '❌ ' + scrub(error)[:600]
                    await self.emit(self.client.send_message(self.me, text, parse_mode=None), echo_text=text)

    async def _media(self, value, temporary):
        reference = parse_media_reference(value)
        if reference:
            chat_id, message_id, kind = reference
            if chat_id != self.me.id:
                raise UserError('User media must be sourced from your own Saved Messages.')
            source = await self.client.get_messages(self.me, ids=message_id)
            if not source or not source.media:
                raise UserError('Saved media source was deleted. Attach it again in My Posts.')
            return source.media
        if isinstance(BOT, UserBotAPI):
            raise UserError('This media belongs to the old bot. Reattach it from Saved Messages, or use hybrid mode.')
        return await asyncio.to_thread(download_bot_media, value, temporary)

    async def _post(self, target, data, actor):
        destination = await self.checked_target(target, actor)
        account = await self.client.get_me()
        if not getattr(account, 'premium', False):
            raise UserError('Telegram Premium is no longer active on this account.')
        validate_post(data)
        text = data.get('content', data.get('text', '')) or ''
        entities = entity_dicts(data.get('entities'))
        quote = data.get('quote_theme', setting_on('quote_theme'))
        if text and quote and not any(item['type'] in {'blockquote', 'expandable_blockquote', 'pre', 'code'} for item in entities):
            entities.append({'type': background_entity_type(), 'offset': 0, 'length': u16(text)})
        text, formatted = await self.prepare(text, entities)
        prepared_links = None
        rows = normalized_buttons(data)
        if rows:
            icons = await self.emoji_documents([item['custom_id'] for row in rows for item in row if item.get('custom_id')])
            for row in rows:
                for item in row:
                    if item.get('custom_id') and int(item['custom_id']) in icons:
                        item['glyph'] = icons[int(item['custom_id'])][1]
            links, link_entities = post_links({'buttons': rows})
            prepared_links = await self.prepare(links, link_entities)
        messages = []
        with tempfile.TemporaryDirectory(prefix='kd-user-media-') as temporary:
            if data.get('album'):
                files = [await self._media(item['file_id'], temporary) for item in data['album']]
                result = await self.emit(self.send_with_effect(self.client.send_file, destination, files, caption=[text] + [''] * (len(files) - 1), formatting_entities=[formatted] + [[] for _ in files[1:]], parse_mode=None, message_effect_id=effect_id()), echo_text=text if tl_utils.get_peer_id(destination) == self.me.id else None)
            else:
                key = next((key for key in ('photo_id', 'video_id', 'animation_id') if data.get(key)), None)
                if key:
                    media = await self._media(data[key], temporary)
                    result = await self.emit(self.send_with_effect(self.client.send_file, destination, media, caption=text, formatting_entities=formatted, parse_mode=None, supports_streaming=key == 'video_id', attributes=[tl_types.DocumentAttributeAnimated()] if key == 'animation_id' else None, message_effect_id=effect_id()), echo_text=text if tl_utils.get_peer_id(destination) == self.me.id else None)
                else:
                    result = await self.emit(self.send_with_effect(self.client.send_message, destination, text, formatting_entities=formatted, parse_mode=None, link_preview=False, message_effect_id=effect_id()), echo_text=text if tl_utils.get_peer_id(destination) == self.me.id else None)
            messages.extend(result if isinstance(result, list) else [result])
        if prepared_links:
            try:
                # User accounts have no native bot keyboard. Preserve every URL as
                # an actual TextUrl entity in a following user-account message.
                link_text, link_formatting = prepared_links
                messages.append(await self.emit(self.client.send_message(destination, link_text, formatting_entities=link_formatting, parse_mode=None, link_preview=False), echo_text=link_text if tl_utils.get_peer_id(destination) == self.me.id else None))
            except Exception as error:
                uncertain = DeliveryUncertain('Post was sent, but the following links were not confirmed. Check the destination before retrying.')
                uncertain.message_ids = [message.id for message in messages]
                raise uncertain from error
        return [SimpleNamespace(message_id=message.id, id=message.id) for message in messages]

    def post(self, target, data, actor=None):
        return self.call(self._post(target, copy.deepcopy(data), self.me.id if actor is None else actor))


def download_bot_media(file_id, directory):
    info = tg(BOT.get_file, file_id)
    if (getattr(info, 'file_size', 0) or 0) > 20 * 1024 * 1024:
        raise UserError('This bot-hosted media exceeds the cloud Bot API download limit. Attach it from Saved Messages in userbot mode.')
    suffix = Path(info.file_path).suffix[:10] or '.bin'
    path = Path(directory) / (secrets.token_hex(8) + suffix)
    url = f'https://api.telegram.org/file/bot{TOKEN}/{info.file_path}'
    try:
        with requests.get(url, stream=True, timeout=(10, 60)) as response:
            response.raise_for_status()
            length = 0
            with path.open('wb') as stream:
                os.chmod(path, 0o600)
                for chunk in response.iter_content(128 * 1024):
                    length += len(chunk)
                    if length > 20 * 1024 * 1024:
                        raise UserError('Bot media exceeds the download limit. Attach it through Saved Messages instead.')
                    stream.write(chunk)
    except requests.RequestException:
        raise UserError('Could not download the old bot media for your user account. Reattach the media.') from None
    return str(path)


class UserBotAPI:
    """Compatibility layer: existing workflows use numbered commands, never fake keyboards."""
    def __init__(self, transport):
        self.transport = transport
        self.message_handler = self.callback_handler = None
        self.menus = {}
        self.latest_menu = None
        transport.on_event = self._handle_event

    def register_message_handler(self, function, **kwargs):
        self.message_handler = function

    def register_callback_query_handler(self, function, **kwargs):
        self.callback_handler = function

    def get_me(self):
        me = self.transport.me
        return SimpleNamespace(id=me.id, username=me.username or 'premium_account', first_name=me.first_name)

    async def _chat(self, target):
        entity = await self.transport.resolve(target)
        private = isinstance(entity, tl_types.User)
        return SimpleNamespace(id=tl_utils.get_peer_id(entity), type='private' if private else 'channel' if getattr(entity, 'broadcast', False) else 'supergroup' if isinstance(entity, tl_types.Channel) else 'group', title=getattr(entity, 'title', None), username=getattr(entity, 'username', None), first_name=getattr(entity, 'first_name', ''), last_name=getattr(entity, 'last_name', ''), invite_link=None)

    def get_chat(self, target):
        return self.transport.call(self._chat(target))

    async def _member(self, target, user_id):
        entity = await self.transport.resolve(target)
        if isinstance(entity, tl_types.User):
            return SimpleNamespace(status='member', is_member=True)
        try:
            permission = await self.transport.client.get_permissions(entity, int(user_id))
        except telethon_errors.UserNotParticipantError:
            return SimpleNamespace(status='left', is_member=False)
        creator = bool(getattr(permission, 'is_creator', False))
        admin = bool(getattr(permission, 'is_admin', False))
        rights = getattr(getattr(permission, 'participant', None), 'admin_rights', None)
        return SimpleNamespace(status='creator' if creator else 'administrator' if admin else 'member', is_member=True,
                               can_post_messages=creator or bool(getattr(rights, 'post_messages', False)) or not getattr(entity, 'broadcast', False),
                               can_invite_users=creator or bool(getattr(rights, 'invite_users', False)))

    def get_chat_member(self, target, user_id):
        return self.transport.call(self._member(target, user_id))

    async def _stickers(self, ids):
        records = await self.transport.emoji_documents(ids)
        return [SimpleNamespace(custom_emoji_id=str(key), emoji=alt, file_id='user-emoji:' + str(key), is_animated=document.mime_type == 'application/x-tgsticker', is_video=document.mime_type == 'video/webm') for key, (document, alt) in records.items()]

    def get_custom_emoji_stickers(self, values):
        return self.transport.call(self._stickers(values))

    def _markup(self, markup):
        if markup is None:
            return '', [], []
        data = markup.to_dict() if hasattr(markup, 'to_dict') else markup
        inline = 'inline_keyboard' in data
        options, lines, entities = [], [], []
        text = '\n\n'
        for row in data.get('inline_keyboard', data.get('keyboard', [])):
            for raw in row:
                item = {'text': raw} if isinstance(raw, str) else raw
                label = item.get('text', 'Open')
                if item.get('url'):
                    start = u16(text)
                    text += label
                    entities.append({'type': 'text_link', 'offset': start, 'length': u16(label), 'url': item['url']})
                    text += '\n'
                    continue
                options.append(('callback', item['callback_data']) if inline else ('message', label))
                command = '.tap ' + str(len(options))
                start = u16(text)
                text += command
                entities.append({'type': 'code', 'offset': start, 'length': u16(command)})
                text += ' — ' + label + '\n'
        if options:
            text += 'Reply with .tap NUMBER to choose an option.'
        return text, entities, options

    def _message_result(self, result, text=''):
        return types.Message.de_json({'message_id': result.id, 'date': int(time.time()), 'chat': {'id': self.transport.me.id, 'type': 'private'}, 'text': text, 'effect_id': str(getattr(result, 'effect', None) or getattr(result, '_requested_effect_id', '')) or None})

    async def _send_text(self, target, text, entities=None, markup=None, requested_effect=None):
        destination = await self.transport.checked_target(target)
        navigation, extra_entities, options = self._markup(markup)
        values = entity_dicts(entities)
        separate = navigation and u16(text + navigation) > 4096
        if navigation and not separate:
            extra_entities = [dict(item, offset=item['offset'] + u16(text)) for item in extra_entities]
            text += navigation
            values.extend(extra_entities)
        text, formatted = await self.transport.prepare(text, values)
        result = await self.transport.emit(self.transport.send_with_effect(self.transport.client.send_message, destination, text, formatting_entities=formatted, parse_mode=None, link_preview=False, message_effect_id=requested_effect), echo_text=text if target == self.transport.me.id else None)
        if separate:
            nav, formatted = await self.transport.prepare(navigation.lstrip('\n'), [dict(item, offset=item['offset'] - 2) for item in extra_entities])
            result = await self.transport.emit(self.transport.client.send_message(destination, nav, formatting_entities=formatted, parse_mode=None), echo_text=nav if target == self.transport.me.id else None)
        if options:
            self.menus[result.id] = options
            if STORE is not None:
                STORE.save_menu(self.transport.me.id, result.id, options)
            self.latest_menu = result.id
            for key in sorted(self.menus)[:-100]:
                del self.menus[key]
        return self._message_result(result, text)

    def send_message(self, chat_id, text, **kwargs):
        return self.transport.call(self._send_text(chat_id, text, kwargs.get('entities'), kwargs.get('reply_markup'), kwargs.get('message_effect_id')))

    async def _send_media(self, target, file, kind, kwargs):
        destination = await self.transport.checked_target(target)
        caption, entities = await self.transport.prepare(kwargs.get('caption', '') or '', kwargs.get('caption_entities') or [])
        if isinstance(file, (str, os.PathLike)):
            with tempfile.TemporaryDirectory(prefix='kd-user-ui-') as temporary:
                media = await self.transport._media(str(file), temporary)
        else:
            media = file
        if kwargs.get('has_spoiler'):
            if isinstance(media, tl_types.MessageMediaDocument):
                media = tl_types.InputMediaDocument(tl_utils.get_input_document(media.document), spoiler=True)
            elif isinstance(media, tl_types.MessageMediaPhoto):
                media = tl_types.InputMediaPhoto(tl_utils.get_input_photo(media.photo), spoiler=True)
        result = await self.transport.emit(self.transport.send_with_effect(self.transport.client.send_file, destination, media, caption=caption, formatting_entities=entities, parse_mode=None, force_document=kind == 'document', supports_streaming=kind == 'video', message_effect_id=kwargs.get('message_effect_id')), echo_text=caption if target == self.transport.me.id else None)
        markup = kwargs.get('reply_markup')
        if markup:
            await self._send_text(target, 'Choose an option:', markup=markup)
        return self._message_result(result, caption)

    def send_photo(self, chat_id, file, **kwargs):
        return self.transport.call(self._send_media(chat_id, file, 'photo', kwargs))

    def send_video(self, chat_id, file, **kwargs):
        return self.transport.call(self._send_media(chat_id, file, 'video', kwargs))

    def send_animation(self, chat_id, file, **kwargs):
        return self.transport.call(self._send_media(chat_id, file, 'animation', kwargs))

    def send_document(self, chat_id, file, **kwargs):
        return self.transport.call(self._send_media(chat_id, file, 'document', kwargs), timeout=900)

    def send_media_group(self, chat_id, media, **kwargs):
        album = [{'type': 'photo' if isinstance(item, types.InputMediaPhoto) else 'video', 'file_id': item.media} for item in media]
        return self.transport.post(chat_id, {'album': album, 'content': media[0].caption or '', 'entities': entity_dicts(media[0].caption_entities)})

    async def _delete(self, chat_id, message_id):
        if int(chat_id) != self.transport.me.id:
            raise UserError('Userbot popup deletion is limited to Saved Messages.')
        return await self.transport.client.delete_messages(self.transport.me, [message_id], revoke=True)

    def delete_message(self, chat_id, message_id):
        return self.transport.call(self._delete(chat_id, message_id))

    async def _reaction(self, chat_id, message_id, reaction, big):
        if chat_id != self.transport.me.id:
            raise UserError('Userbot start reactions run in Saved Messages.')
        converted = []
        for value in reaction:
            item = value.to_dict()
            converted.append(tl_types.ReactionCustomEmoji(int(item['custom_emoji_id'])) if item['type'] == 'custom_emoji' else tl_types.ReactionEmoji(item['emoji']))
        return await self.transport.client(tl_functions.messages.SendReactionRequest(await self.transport.resolve(chat_id), message_id, big=big, reaction=converted))

    def set_message_reaction(self, chat_id, message_id, reaction, is_big=False, **kwargs):
        return self.transport.call(self._reaction(chat_id, message_id, reaction, is_big))

    def answer_callback_query(self, *args, **kwargs):
        return True

    def remove_webhook(self, *args, **kwargs):
        return True

    def set_my_commands(self, *args, **kwargs):
        return True

    async def _invite(self, target):
        destination = await self.transport.checked_target(target)
        result = await self.transport.client(tl_functions.messages.ExportChatInviteRequest(destination))
        return SimpleNamespace(invite_link=result.link)

    def create_chat_invite_link(self, target, **kwargs):
        return self.transport.call(self._invite(target))

    async def _copy(self, target, source_chat, source_id):
        destination = await self.transport.checked_target(target)
        if source_chat != self.transport.me.id:
            raise UserError('Copy sources must be your own Saved Messages.')
        message = await self.transport.client.get_messages(self.transport.me, ids=source_id)
        result = await self.transport.emit(self.transport.client.send_message(destination, message), echo_text=message.raw_text if target == self.transport.me.id else None)
        return self._message_result(result)

    def copy_message(self, target, source_chat, source_id, **kwargs):
        return self.transport.call(self._copy(target, source_chat, source_id))

    def infinity_polling(self, **kwargs):
        while not STOP.wait(1):
            if not self.transport.thread.is_alive():
                raise SystemExit('Userbot connection stopped. Restart after checking the session.')

    def stop_polling(self):
        self.transport.stop()

    def convert_message(self, message, text_override=None):
        me = self.transport.me
        text = message.raw_text or ''
        values = bot_entities_from_mt(message.entities)
        payload = {'message_id': message.id, 'date': int(message.date.timestamp()) if getattr(message, 'date', None) else int(time.time()),
                   'chat': {'id': me.id, 'type': 'private'}, 'from': {'id': me.id, 'is_bot': False, 'first_name': me.first_name or 'Owner', 'last_name': me.last_name or '', 'username': me.username}}
        if message.photo:
            payload['photo'] = [{'file_id': media_reference(me.id, message.id, 'photo'), 'file_unique_id': f'user-photo-{message.id}', 'width': 1, 'height': 1}]
        elif message.document:
            document = message.document
            video = next((a for a in document.attributes if isinstance(a, tl_types.DocumentAttributeVideo)), None)
            animated = any(isinstance(a, tl_types.DocumentAttributeAnimated) for a in document.attributes) or document.mime_type == 'image/gif'
            kind = 'animation' if animated else 'video' if video else 'document'
            file = {'file_id': media_reference(me.id, message.id, kind), 'file_unique_id': f'user-doc-{message.id}', 'mime_type': document.mime_type, 'file_size': document.size}
            if kind != 'document':
                file.update(width=getattr(video, 'w', 1), height=getattr(video, 'h', 1), duration=int(getattr(video, 'duration', 0)))
            payload[kind] = file
        if message.photo or message.document:
            payload['caption'], payload['caption_entities'] = text, values
        else:
            payload['text'], payload['entities'] = text, values
        if getattr(message, 'grouped_id', None):
            payload['media_group_id'] = str(message.grouped_id)
        forward = getattr(message, 'fwd_from', None)
        peer = getattr(forward, 'from_id', None)
        if isinstance(peer, (tl_types.PeerChannel, tl_types.PeerChat)):
            channel_id = tl_utils.get_peer_id(peer)
            payload['forward_origin'] = {'type': 'channel', 'date': int(time.time()), 'chat': {'id': channel_id, 'type': 'channel', 'title': 'Forwarded Channel'}, 'message_id': getattr(forward, 'channel_post', None) or 1}
        if text_override is not None:
            for key in ('photo', 'video', 'animation', 'document', 'caption', 'caption_entities', 'media_group_id'):
                payload.pop(key, None)
            payload['text'], payload['entities'] = text_override, []
        return types.Message.de_json(payload)

    async def _choose(self, event, argument):
        parts = argument.split()
        if len(parts) not in (1, 2) or any(not part.isdigit() for part in parts):
            raise UserError('Use .tap NUMBER or .tap MESSAGE_ID NUMBER.')
        menu_id = int(parts[0]) if len(parts) == 2 else self.latest_menu
        number = int(parts[-1])
        options = self.menus.get(menu_id, [])
        if not 1 <= number <= len(options):
            raise UserError('That option is unavailable. Use .start for a fresh menu.')
        kind, value = options[number - 1]
        if kind == 'message':
            await asyncio.to_thread(self.message_handler, self.convert_message(event.message, value))
        else:
            source = self.convert_message(event.message, 'Menu')
            source.message_id = menu_id
            callback = SimpleNamespace(id=f'userbot:{event.id}', from_user=source.from_user, message=source, data=value)
            await asyncio.to_thread(self.callback_handler, callback)

    async def _handle_event(self, event):
        if event.sender_id != self.transport.me.id or event.chat_id != self.transport.me.id or not event.out:
            return
        text = event.raw_text or ''
        if not text.startswith('.'):
            if STORE.state(self.transport.me.id, self.transport.me.id):
                await asyncio.to_thread(self.message_handler, self.convert_message(event.message))
            return
        command, _, argument = text.partition(' ')
        command, argument = command.lower(), argument.strip()
        if command == '.help':
            await asyncio.to_thread(self.send_message, self.transport.me.id, USERBOT_HELP)
        elif command == '.tap':
            await self._choose(event, argument)
        elif command == '.new':
            await asyncio.to_thread(menu_action, self.convert_message(event.message, 'Make Post'), 'post')
            if event.is_reply:
                reply = await event.get_reply_message()
                if getattr(reply, 'grouped_id', None):
                    raise UserError('For albums, use .new then send the complete album to Saved Messages.')
                await asyncio.to_thread(self.message_handler, self.convert_message(reply))
        elif command == '.preview':
            if not argument:
                raise UserError('Use .preview POST_ID or .preview latest.')
            data = STORE.post(argument, self.transport.me.id)
            await asyncio.to_thread(send_post, self.transport.me.id, data)
        elif command == '.owner':
            await asyncio.to_thread(owner_panel, self.transport.me.id, self.transport.me.id)
        elif command == '.emoji':
            if not argument.isdigit():
                raise UserError('Use .emoji CUSTOM_EMOJI_ID.')
            docs = await self.transport.emoji_documents([argument])
            if int(argument) not in docs:
                raise UserError('Custom emoji not found.')
            glyph = docs[int(argument)][1]
            entities = [tl_types.MessageEntityCustomEmoji(offset=0, length=u16(glyph), document_id=int(argument))]
            await self.transport.emit(self.transport.client.send_message(self.transport.me, glyph, formatting_entities=entities, parse_mode=None), echo_text=glyph)
        elif command in {'.start', '.cancel', '.send', '.posts', '.channels', '.schedules', '.templates', '.emojis', '.backup', '.access'}:
            await asyncio.to_thread(self.message_handler, self.convert_message(event.message, '/' + command[1:] + (' ' + argument if argument else '')))
        else:
            await asyncio.to_thread(self.send_message, self.transport.me.id, 'Unknown userbot command. Use .help.')


USERBOT_HELP = '''KD Premium Userbot · Saved Messages commands
.start — Open numbered workflow menu
.tap NUMBER — Choose from the latest menu
.tap MESSAGE_ID NUMBER — Choose from a specific menu
.new — Create a post; optionally reply to a text/photo/video/GIF
.posts — Search, preview, edit, rename, duplicate or delete posts
.send POST_ID @channel — Publish a saved post as your Premium account
.send latest -100CHAT_ID — Publish the latest post
.preview POST_ID — Preview in Saved Messages
.channels — Manage saved channels/groups
.schedules — Manage one-time/daily/weekly IST schedules
.templates — Ready post templates
.emojis — Emoji packs, favourites and theme
.emoji CUSTOM_EMOJI_ID — Preview a custom emoji
.owner — Personal owner controls
.backup — Create and download a database backup
.cancel — Cancel the current workflow

Commands are accepted only from you in Saved Messages.
User-account posts use clickable URL links instead of native bot buttons.
New attachments are saved in durable media storage. Use .vault to store older sources.
Use RUN_MODE=hybrid for the existing public bot menus and subscriptions.'''


def userbot_menu():
    keyboard = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
    for row in (('post', 'posts'), ('channels', 'scheduled'), ('templates', 'emojis'), ('owner',)):
        keyboard.row(*(button(menu_label(key), reply=True, glyph='🎀' if key == 'post' else '✨') for key in row))
    return keyboard


def userbot_owner_panel(chat_id, user_id):
    STORE.clear_state(chat_id, user_id)
    keyboard = types.InlineKeyboardMarkup(row_width=2)
    for label, action, glyph in (
        ('Status', 'admin_status', '📊'), ('My Posts', 'posts:0', '📂'),
        ('Schedules', 'schedules:0', '⏰'), ('Emoji & Theme', 'emoji_settings', '🎨'),
        ('Effects & Theme', 'admin_theme', '✨'), ('Backups', 'admin_backups', '💾'),
        ('Home', 'home', '🏠'),
    ):
        keyboard.add(button(label, action=action, glyph=glyph))
    ui(chat_id, '👑 Premium Userbot Controls\nPersonal posting, schedules, themes and backups.\nPublic bot menus, subscriptions and subscriber broadcasts are available in hybrid mode.', keyboard)


