class PublisherPaused(UserError):
    pass


class PublishDeferred(UserError):
    def __init__(self, until):
        self.until = int(until)
        super().__init__('This channel reached its daily posting limit. Scheduled delivery will wait for the next local day.')


def channel_settings(values=None):
    result = {'footer': '', 'hashtags': '', 'timezone': 'Asia/Kolkata', 'daily_limit': 0}
    result.update(values or {})
    if set(result) - {'footer', 'hashtags', 'timezone', 'daily_limit'}:
        raise UserError('Unknown channel setting.')
    if not all(isinstance(result[key], str) for key in ('footer', 'hashtags', 'timezone')):
        raise UserError('Footer, hashtags and timezone must be text.')
    if u16(result['footer']) > 500 or u16(result['hashtags']) > 250:
        raise UserError('Use up to 500 footer units and 250 hashtag units.')
    tags = result['hashtags'].split()
    if any(not re.fullmatch(r'#[\w]+', tag, re.UNICODE) for tag in tags):
        raise UserError('Hashtags must look like #news #KD.')
    try:
        ZoneInfo(result['timezone'])
        limit = int(result['daily_limit'])
    except (ValueError, TypeError, ZoneInfoNotFoundError):
        raise UserError('Use a real timezone such as Asia/Kolkata and a whole-number daily limit.') from None
    if not 0 <= limit <= 10000:
        raise UserError('Daily limit must be 0–10000; 0 disables the local limit.')
    result['daily_limit'], result['hashtags'] = limit, ' '.join(tags)
    return result


def vault_reference(value):
    match = re.fullmatch(r'vault:([a-f0-9]{64}):(photo|video|animation|document)', str(value))
    return match.groups() if match else None


def file_sha256(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


_BaseStorage = Storage


class Storage(_BaseStorage):
    def __init__(self, folder):
        super().__init__(folder)
        with sqlite3.connect(str(self.path)) as source:
            if not source.execute("SELECT 1 FROM nxt_meta WHERE key='publishing_tools_version'").fetchone():
                stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
                with sqlite3.connect(str(self.folder / f'bot.db.before-tools-{stamp}.bak')) as target:
                    source.backup(target)
        with self.db() as c:
            for statement in (
                "CREATE TABLE IF NOT EXISTS kd_publications (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,post_id TEXT NOT NULL,target_id INTEGER NOT NULL,title TEXT NOT NULL,transport TEXT NOT NULL,message_ids TEXT NOT NULL DEFAULT '[]',payload_json TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,pending_json TEXT NOT NULL DEFAULT '')",
                'CREATE INDEX IF NOT EXISTS kd_publications_owner ON kd_publications(user_id,id DESC)',
                'CREATE INDEX IF NOT EXISTS kd_publications_quota ON kd_publications(target_id,created_at,status)',
                "CREATE TABLE IF NOT EXISTS kd_channel_settings (user_id INTEGER NOT NULL,target_id INTEGER NOT NULL,settings_json TEXT NOT NULL,PRIMARY KEY(user_id,target_id))",
                'CREATE TABLE IF NOT EXISTS kd_media (digest TEXT PRIMARY KEY,name TEXT NOT NULL,bytes INTEGER NOT NULL,created_at INTEGER NOT NULL)',
                'CREATE TABLE IF NOT EXISTS kd_media_sources (source TEXT PRIMARY KEY,reference TEXT NOT NULL)',
                'CREATE TABLE IF NOT EXISTS kd_menus (chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,options_json TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(chat_id,message_id))',
                'CREATE TABLE IF NOT EXISTS kd_prompts (chat_id INTEGER NOT NULL,message_id INTEGER NOT NULL,text TEXT NOT NULL,markup_json TEXT NOT NULL,PRIMARY KEY(chat_id,message_id))',
                'CREATE TABLE IF NOT EXISTS kd_emoji_packs (user_id INTEGER NOT NULL,slug TEXT NOT NULL,title TEXT NOT NULL,items_json TEXT NOT NULL,PRIMARY KEY(user_id,slug))',
                "CREATE TABLE IF NOT EXISTS kd_alerts (key TEXT PRIMARY KEY,text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',updated_at INTEGER NOT NULL,last_sent INTEGER NOT NULL DEFAULT 0)",
                'CREATE TABLE IF NOT EXISTS kd_schedule_wait (job_id TEXT PRIMARY KEY,until INTEGER NOT NULL)',
            ):
                c.execute(statement)
            c.execute("INSERT OR IGNORE INTO nxt_meta VALUES ('publishing_tools_version','1')")

    def config_for(self, user_id, target):
        with self.db() as c:
            row = c.execute('SELECT settings_json FROM kd_channel_settings WHERE user_id=? AND target_id=?', (user_id, int(target))).fetchone()
        return channel_settings(json.loads(row[0]) if row else {})

    def configure_channel(self, user_id, target, values):
        values = channel_settings(values)
        with self.db() as c:
            c.execute('INSERT INTO kd_channel_settings VALUES (?,?,?) ON CONFLICT(user_id,target_id) DO UPDATE SET settings_json=excluded.settings_json', (user_id, int(target), json.dumps(values, ensure_ascii=False)))
        return values

    def paused(self):
        return self.meta('publisher_paused', '0') == '1' or self.meta('restore_active', '0') == '1'

    def pause(self, paused):
        self.setting('publisher_paused', '1' if paused else '0')
        if paused:
            BROADCAST_CANCEL.set()
        self.audit('publisher_pause' if paused else 'publisher_resume', ADMIN_ID)

    def reserve_publication(self, user_id, target, data, title='', sender='user'):
        config = self.config_for(user_id, target)
        zone = ZoneInfo(config['timezone'])
        now = int(time.time())
        today = datetime.fromtimestamp(now, zone).replace(hour=0, minute=0, second=0, microsecond=0)
        with self.db() as c:
            paused = c.execute("SELECT value FROM nxt_meta WHERE key IN ('publisher_paused','restore_active') AND value='1'").fetchone()
            if paused:
                raise PublisherPaused('Publishing is paused. Use .resume or the owner controls to continue.')
            # Count reservations and ambiguous deliveries too. Deleting a message does not reset a quota.
            count = c.execute("SELECT COUNT(*) FROM kd_publications WHERE target_id=? AND created_at>=? AND status NOT IN ('failed','deferred')", (int(target), int(today.timestamp()))).fetchone()[0]
            if config['daily_limit'] and count >= config['daily_limit']:
                raise PublishDeferred((today + timedelta(days=1)).timestamp())
            cursor = c.execute("INSERT INTO kd_publications(user_id,post_id,target_id,title,transport,payload_json,status,created_at,updated_at) VALUES (?,?,?,?,?,?,'sending',?,?)", (user_id, str(data.get('id', '')), int(target), title[:120], sender, json.dumps(data, ensure_ascii=False), now, now))
            return cursor.lastrowid

    def publication(self, publication_id, user_id):
        with self.db() as c:
            row = c.execute('SELECT * FROM kd_publications WHERE id=? AND user_id=?', (int(publication_id), user_id)).fetchone()
        if not row:
            raise UserError('Delivery not found for your account.')
        result = dict(row)
        result['payload'] = json.loads(result.pop('payload_json'))
        result['ids'] = json.loads(result['message_ids'])
        return result

    def publications(self, user_id, offset=0):
        with self.db() as c:
            total = c.execute('SELECT COUNT(*) FROM kd_publications WHERE user_id=?', (user_id,)).fetchone()[0]
            rows = c.execute('SELECT id,post_id,target_id,title,status,created_at FROM kd_publications WHERE user_id=? ORDER BY id DESC LIMIT 6 OFFSET ?', (user_id, max(0, offset))).fetchall()
        return [dict(row) for row in rows], total

    def finish_publication(self, publication_id, status, ids=None, detail='', payload=None):
        with self.db() as c:
            c.execute('UPDATE kd_publications SET status=?,detail=?,updated_at=? WHERE id=?', (status, scrub(detail)[:1000], int(time.time()), publication_id))
            if ids is not None:
                c.execute('UPDATE kd_publications SET message_ids=? WHERE id=?', (json.dumps(list(map(int, ids))), publication_id))
            if payload is not None:
                c.execute("UPDATE kd_publications SET payload_json=?,pending_json='' WHERE id=?", (json.dumps(payload, ensure_ascii=False), publication_id))

    def begin_change(self, publication_id, user_id, status, pending=None):
        with self.db() as c:
            row = c.execute('SELECT status FROM kd_publications WHERE id=? AND user_id=?', (publication_id, user_id)).fetchone()
            if not row or row[0] in {'sending', 'editing', 'deleting', 'deleted'}:
                raise UserError('This delivery cannot be changed right now.')
            c.execute('UPDATE kd_publications SET status=?,pending_json=?,updated_at=? WHERE id=?', (status, json.dumps(pending or {}, ensure_ascii=False), int(time.time()), publication_id))

    def save_menu(self, chat_id, message_id, options):
        with self.db() as c:
            c.execute('INSERT OR REPLACE INTO kd_menus VALUES (?,?,?,?)', (chat_id, message_id, json.dumps(options, ensure_ascii=False), int(time.time())))
            c.execute('DELETE FROM kd_menus WHERE chat_id=? AND message_id NOT IN (SELECT message_id FROM kd_menus WHERE chat_id=? ORDER BY message_id DESC LIMIT 100)', (chat_id, chat_id))

    def menus(self, chat_id):
        with self.db() as c:
            return {row[0]: json.loads(row[1]) for row in c.execute('SELECT message_id,options_json FROM kd_menus WHERE chat_id=? ORDER BY message_id', (chat_id,))}

    def remember_prompt(self, chat_id, message_id, text, markup):
        if chat_id > 0:
            serialized = (markup.to_dict() if hasattr(markup, 'to_dict') else json.loads(markup.to_json())) if markup is not None else None
            with self.db() as c:
                c.execute('INSERT OR REPLACE INTO kd_prompts VALUES (?,?,?,?)', (chat_id, message_id, text, json.dumps(serialized, ensure_ascii=False)))
                c.execute('DELETE FROM kd_prompts WHERE chat_id=? AND message_id NOT IN (SELECT message_id FROM kd_prompts WHERE chat_id=? ORDER BY message_id DESC LIMIT 150)', (chat_id, chat_id))

    def media_path(self, reference):
        parsed = vault_reference(reference)
        if not parsed:
            raise UserError('Invalid media storage reference.')
        with self.db() as c:
            row = c.execute('SELECT name,bytes FROM kd_media WHERE digest=?', (parsed[0],)).fetchone()
        if not row or not re.fullmatch(r'[a-f0-9]{64}\.[a-z0-9]{1,8}', row[0]):
            raise UserError('Stored media is missing. Reattach it or restore a media backup.')
        path = self.folder / 'media' / row[0]
        if path.is_symlink() or not path.is_file() or path.stat().st_size != row[1]:
            raise UserError('Stored media is missing or incomplete. Restore it from a backup.')
        return path

    def source_media(self, source):
        with self.db() as c:
            row = c.execute('SELECT reference FROM kd_media_sources WHERE source=?', (source,)).fetchone()
        if row:
            try:
                self.media_path(row[0])
                return row[0]
            except UserError:
                pass
        return None

    def store_media(self, source, path, kind):
        if kind not in {'photo', 'video', 'animation', 'document'}:
            raise UserError('Unsupported media kind.')
        path = Path(path)
        size = path.stat().st_size
        if not 0 < size <= VAULT_FILE_LIMIT:
            raise UserError('Media exceeds the configured storage size limit.')
        digest = file_sha256(path)
        suffix = path.suffix.lower()
        suffix = suffix if re.fullmatch(r'\.[a-z0-9]{1,8}', suffix) else '.bin'
        with VAULT_LOCK:
            folder = self.folder / 'media'
            folder.mkdir(mode=0o700, exist_ok=True)
            with self.db() as c:
                old = c.execute('SELECT name FROM kd_media WHERE digest=?', (digest,)).fetchone()
                total = c.execute('SELECT COALESCE(SUM(bytes),0) FROM kd_media').fetchone()[0]
                name = old[0] if old else digest + suffix
                if not old and total + size > VAULT_TOTAL_LIMIT:
                    raise UserError('Media storage is full. Increase MEDIA_VAULT_TOTAL_MB or archive old media.')
                destination = folder / name
                if not destination.exists():
                    temporary = folder / (digest + '.' + secrets.token_hex(4) + '.partial')
                    try:
                        shutil.copyfile(path, temporary)
                        os.chmod(temporary, 0o600)
                        os.replace(temporary, destination)
                    finally:
                        temporary.unlink(missing_ok=True)
                c.execute('INSERT OR REPLACE INTO kd_media VALUES (?,?,?,?)', (digest, name, size, int(time.time())))
                reference = f'vault:{digest}:{kind}'
                c.execute('INSERT OR REPLACE INTO kd_media_sources VALUES (?,?)', (source, reference))
        return reference

    def save_post(self, user_id, chat_id, data, post_id=None):
        data = copy.deepcopy(data)
        for item, key in media_slots(data):
            item[key] = self.source_media(item[key]) or item[key]
        return super().save_post(user_id, chat_id, data, post_id)

    def imported_packs(self, user_id):
        with self.db() as c:
            return [dict(row) for row in c.execute('SELECT slug,title FROM kd_emoji_packs WHERE user_id=? ORDER BY title', (user_id,))]

    def imported_pack(self, user_id, slug):
        with self.db() as c:
            row = c.execute('SELECT * FROM kd_emoji_packs WHERE user_id=? AND slug=?', (user_id, slug)).fetchone()
        if not row:
            raise UserError('Imported emoji pack not found for your account.')
        result = dict(row)
        result['items'] = json.loads(result.pop('items_json'))
        return result

    def store_pack(self, user_id, slug, title, items):
        with self.db() as c:
            exists = c.execute('SELECT 1 FROM kd_emoji_packs WHERE user_id=? AND slug=?', (user_id, slug)).fetchone()
            if not exists and c.execute('SELECT COUNT(*) FROM kd_emoji_packs WHERE user_id=?', (user_id,)).fetchone()[0] >= 20:
                raise UserError('Remove an imported pack before saving more than 20.')
            c.execute('INSERT OR REPLACE INTO kd_emoji_packs VALUES (?,?,?,?)', (user_id, slug, title[:100], json.dumps(items, ensure_ascii=False)))

    def claim_due(self, now=None):
        if self.paused():
            return None
        now = int(time.time()) if now is None else now
        with self.db() as c:
            row = c.execute("SELECT s.id,s.user_id FROM nxt_schedules s LEFT JOIN kd_schedule_wait w ON w.job_id=s.id WHERE s.status='pending' AND s.run_at<=? AND COALESCE(w.until,0)<=? ORDER BY s.run_at LIMIT 1", (now, now)).fetchone()
            if not row:
                return None
            c.execute("UPDATE nxt_schedules SET status='running' WHERE id=? AND status='pending'", (row['id'],))
        return self.schedule(row['id'], row['user_id'])

    def recover_schedules(self):
        super().recover_schedules()
        with self.db() as c:
            c.execute("UPDATE kd_publications SET status='needs_review',detail='Application restarted before confirmation. Inspect the channel before another action.' WHERE status IN ('sending','editing','deleting')")
            c.execute("UPDATE nxt_meta SET value='0' WHERE key='restore_active'")

    def create_backup(self, automatic=False):
        with BACKUP_LOCK:
            folder = self.folder / 'backups'
            folder.mkdir(mode=0o700, exist_ok=True)
            name = ('auto' if automatic else 'manual') + '-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '-' + secrets.token_hex(3) + '.zip'
            destination = folder / name
            temporary = destination.with_suffix('.partial')
            try:
                with tempfile.TemporaryDirectory(prefix='kd-backup-') as staging:
                    snapshot = Path(staging) / 'bot.db'
                    with sqlite3.connect(str(self.path)) as source, sqlite3.connect(str(snapshot)) as target:
                        source.backup(target)
                        if target.execute('PRAGMA quick_check').fetchone()[0] != 'ok':
                            raise UserError('SQLite backup integrity check failed.')
                        media = target.execute('SELECT digest,name,bytes FROM kd_media').fetchall() if self.meta('backup_include_media', '1') == '1' else []
                    metrics_snapshot = backup_metrics(self.folder, staging)
                    with zipfile.ZipFile(temporary, 'w', zipfile.ZIP_DEFLATED, allowZip64=True) as archive:
                        archive.write(snapshot, 'bot.db')
                        if metrics_snapshot is not None:
                            archive.write(metrics_snapshot, 'metrics.db')
                        with self.io_lock:
                            for filename in ('users.json', 'redeem.txt', 'posts.json'):
                                path = self.folder / filename
                                if path.is_file():
                                    archive.write(path, filename)
                        for digest, filename, size in media:
                            path = self.media_path(f'vault:{digest}:document')
                            archive.write(path, 'media/' + filename)
                        archive.writestr('backup-info.json', json.dumps({'format': 2, 'created_at_utc': datetime.now(timezone.utc).isoformat(), 'media_files': len(media), 'note': 'SQLite snapshot and optional durable media. Account credentials are excluded.'}))
                    os.chmod(temporary, 0o600)
                    os.replace(temporary, destination)
            finally:
                temporary.unlink(missing_ok=True)
            for prefix, keep in (('auto-', 7), ('manual-', 10)):
                for old in sorted(folder.glob(prefix + '*.zip'), key=lambda p: p.stat().st_mtime, reverse=True)[keep:]:
                    old.unlink()
            if automatic:
                self.setting('last_auto_backup', int(time.time()))
            return destination


def media_slots(data):
    result = [(data, key) for key in ('photo_id', 'video_id', 'animation_id') if data.get(key)]
    result.extend((item, 'file_id') for item in data.get('album') or [] if item.get('file_id'))
    return result


def queue_alert(key, text):
    if STORE is None or not isinstance(STORE, Storage):
        return
    text = scrub(text)[:1200]
    with STORE.db() as c:
        c.execute("INSERT INTO kd_alerts(key,text,status,updated_at) VALUES (?,?,'pending',?) ON CONFLICT(key) DO UPDATE SET text=excluded.text,status=CASE WHEN kd_alerts.text=excluded.text AND kd_alerts.status='sent' AND kd_alerts.last_sent>? THEN 'sent' ELSE 'pending' END,updated_at=excluded.updated_at", (key[:160], text, int(time.time()), int(time.time()) - 3600))


def apply_channel_settings(data, config):
    result = copy.deepcopy(data)
    text = result.get('content', result.get('text', '')) or ''
    extra = '\n\n'.join(value for value in (config['footer'], config['hashtags']) if value)
    if extra:
        text += ('\n\n' if text else '') + extra
    result['content'] = text
    validate_post(result)
    return result


_send_post_base = send_post


def send_post(chat_id, data):
    if not isinstance(chat_id, int) or chat_id >= 0 or STORE is None:
        return _send_post_base(chat_id, data)
    user_id = userbot_actor(data)
    outgoing = apply_channel_settings(data, STORE.config_for(user_id, chat_id))
    title = str(chat_id)
    if USER_CLIENT is not None:
        cached = USER_CLIENT.entities.get(chat_id)
        title = getattr(cached, 'title', title)
    publication_id = STORE.reserve_publication(user_id, chat_id, outgoing, title, 'user' if USER_CLIENT is not None else 'bot')
    try:
        if STORE.paused():
            raise PublisherPaused('Publishing paused before this request started.')
        result = _send_post_base(chat_id, outgoing)
    except Exception as error:
        ambiguous = isinstance(error, DeliveryUncertain) or not isinstance(error, (UserError, ApiTelegramException))
        status = 'deferred' if isinstance(error, (PublisherPaused, PublishDeferred)) else 'uncertain' if ambiguous else 'failed'
        STORE.finish_publication(publication_id, status, getattr(error, 'message_ids', []), str(error))
        if status not in {'deferred'}:
            queue_alert('delivery:' + str(publication_id), f'Post {data.get("id", "draft")} to {chat_id}: {status}. {scrub(error)}')
        raise
    ids = delivered_ids(result)
    STORE.finish_publication(publication_id, 'success', ids)
    for item in result if isinstance(result, list) else [result]:
        with contextlib.suppress(Exception):
            item.publication_id = publication_id
    return result


def publication_links(row):
    channel_id, peer_type = tl_utils.resolve_id(int(row['target_id']))
    if peer_type is tl_types.PeerChannel:
        return [f'https://t.me/c/{channel_id}/{message_id}' for message_id in row['ids']]
    return []


