async def change_published(transport, row, replacement=None, delete=False):
    destination = await transport.checked_target(row['target_id'], row['user_id'])
    ids = row['ids']
    if not ids:
        raise UserError('This delivery has no confirmed message IDs.')
    for message_id in ids:
        message = await transport.client.get_messages(destination, ids=message_id)
        if not delete and (not message or isinstance(message, tl_types.MessageEmpty)):
            raise UserError('A published message no longer exists.')
    if delete:
        STORE.begin_change(row['id'], row['user_id'], 'deleting')
        row['_change_started'] = True
        await transport.client.delete_messages(destination, ids, revoke=True)
        for message_id in ids:
            remaining = await transport.client.get_messages(destination, ids=message_id)
            if remaining and not isinstance(remaining, tl_types.MessageEmpty):
                raise DeliveryUncertain('Some messages still appear in the channel. Check the channel before retrying deletion.')
        return
    original = row['payload']
    if [(key, item[key]) for item, key in media_slots(original)] != [(key, item[key]) for item, key in media_slots(replacement)]:
        raise UserError('Published editing supports text, captions and existing URL links. Keep the original media attachments.')
    old_links, new_links = bool(normalized_buttons(original)), bool(normalized_buttons(replacement))
    if old_links != new_links:
        raise UserError('Keep the existing link-message layout when editing a published post.')
    validate_post(replacement)
    text, values = replacement.get('content', replacement.get('text', '')) or '', entity_dicts(replacement.get('entities'))
    if text and replacement.get('quote_theme', setting_on('quote_theme')) and not any(item['type'] in {'blockquote', 'expandable_blockquote', 'pre', 'code'} for item in values):
        values.append({'type': background_entity_type(), 'offset': 0, 'length': u16(text)})
    text, formatted = await transport.prepare(text, values)
    prepared_links = await transport.prepare(*post_links(replacement)) if new_links else None
    STORE.begin_change(row['id'], row['user_id'], 'editing', replacement)
    row['_change_started'] = True
    try:
        await transport.client.edit_message(destination, ids[0], text, formatting_entities=formatted, parse_mode=None, link_preview=False)
    except telethon_errors.MessageNotModifiedError:
        pass
    if prepared_links:
        try:
            await transport.client.edit_message(destination, ids[-1], prepared_links[0], formatting_entities=prepared_links[1], parse_mode=None, link_preview=False)
        except telethon_errors.MessageNotModifiedError:
            pass


def update_delivery(chat_id, user_id, publication_id, replacement=None, delete=False):
    private_only(chat_id, user_id)
    row = STORE.publication(publication_id, user_id)
    if USER_CLIENT is None or row['transport'] != 'user':
        raise UserError('Connect the same Premium user account to manage this delivery.')
    if not delete and row['status'] not in {'success', 'edited'}:
        raise UserError('Inspect this delivery in the channel first; its last operation is unconfirmed.')
    try:
        USER_CLIENT.call(change_published(USER_CLIENT, row, replacement, delete))
    except Exception as error:
        if row.get('_change_started'):
            STORE.finish_publication(row['id'], 'delete_review' if delete else 'edit_review', detail=str(error))
            queue_alert('change:' + str(row['id']), f'Published message change #{row["id"]} needs review: {scrub(error)}')
        raise
    STORE.finish_publication(row['id'], 'deleted' if delete else 'edited', payload=None if delete else replacement)
    STORE.audit('published_delete' if delete else 'published_edit', user_id, str(row['id']))
    STORE.clear_state(chat_id, user_id)
    delivery_panel(chat_id, user_id, row['id'])


async def capture_user_media(transport, message):
    if message is None or not getattr(message, 'media', None):
        return None
    document = getattr(message, 'document', None)
    photo = getattr(message, 'photo', None)
    if not photo and not document:
        return None
    animated = bool(document and (document.mime_type == 'image/gif' or any(isinstance(a, tl_types.DocumentAttributeAnimated) for a in document.attributes)))
    video = bool(document and any(isinstance(a, tl_types.DocumentAttributeVideo) for a in document.attributes))
    kind = 'photo' if photo else 'animation' if animated else 'video' if video else 'document'
    source = media_reference(transport.me.id, message.id, kind)
    existing = STORE.source_media(source)
    if existing:
        return existing
    if document and document.size > VAULT_FILE_LIMIT:
        raise UserError('Media exceeds MEDIA_VAULT_MAX_MB. Increase the configured limit to store it.')
    with tempfile.TemporaryDirectory(prefix='kd-vault-') as temporary:
        path = await transport.client.download_media(message, file=temporary + os.sep)
        if not path:
            raise UserError('Telegram media download did not complete.')
        return await asyncio.to_thread(STORE.store_media, source, path, kind)


_media_base = UserTransport._media


async def durable_media(self, value, temporary):
    if vault_reference(value):
        return str(STORE.media_path(value))
    cached = STORE.source_media(value) if STORE is not None else None
    if cached:
        return str(STORE.media_path(cached))
    # Existing Saved Messages references become durable the next time they are reused.
    reference = parse_media_reference(value)
    if reference and reference[0] == self.me.id and hasattr(self.client, 'download_media'):
        message = await self.client.get_messages(self.me, ids=reference[1])
        if message and getattr(message, 'media', None):
            stored = await capture_user_media(self, message)
            if stored:
                return str(STORE.media_path(stored))
    media = await _media_base(self, value, temporary)
    if STORE is not None and isinstance(media, (str, os.PathLike)) and Path(media).is_file():
        suffix = Path(media).suffix.lower()
        kind = 'photo' if suffix in {'.jpg', '.jpeg', '.png', '.webp'} else 'animation' if suffix == '.gif' else 'video' if suffix in {'.mp4', '.mov', '.mkv', '.webm'} else 'document'
        reference = await asyncio.to_thread(STORE.store_media, value, media, kind)
        return str(STORE.media_path(reference))
    return media


UserTransport._media = durable_media


_convert_message_base = UserBotAPI.convert_message


def durable_message(self, message, text_override=None):
    result = _convert_message_base(self, message, text_override)
    if text_override is None and STORE is not None:
        for item in (getattr(result, 'photo', None) or []):
            item.file_id = STORE.source_media(item.file_id) or item.file_id
        for key in ('video', 'animation', 'document'):
            item = getattr(result, key, None)
            if item:
                item.file_id = STORE.source_media(item.file_id) or item.file_id
    return result


