def local_moment(text, zone_name):
    try:
        naive = datetime.strptime(text, '%Y-%m-%d %H:%M')
        zone = ZoneInfo(zone_name)
    except (ValueError, ZoneInfoNotFoundError):
        raise UserError('Use YYYY-MM-DD HH:MM and a real timezone such as Asia/Kolkata.') from None
    first, second = naive.replace(tzinfo=zone, fold=0), naive.replace(tzinfo=zone, fold=1)
    if first.astimezone(timezone.utc).astimezone(zone).replace(tzinfo=None) != naive:
        raise UserError('That local time does not exist because clocks change. Choose another time.')
    if first.utcoffset() != second.utcoffset():
        raise UserError('That local time occurs twice because clocks change. Choose an unambiguous time.')
    return first


def parse_schedule(text, zone_name='Asia/Kolkata'):
    parts = [part.strip() for part in text.split('|')]
    if not 1 <= len(parts) <= 3:
        raise UserError('Use YYYY-MM-DD HH:MM | once/daily/weekly | optional timezone.')
    zone_name = parts[2] if len(parts) == 3 else zone_name
    moment = local_moment(parts[0], zone_name)
    repeat = {'once': 0, 'daily': 86400, 'weekly': 604800}.get(parts[1].translate(NORMAL_TABLE).lower() if len(parts) > 1 else 'once')
    if repeat is None:
        raise UserError('Repeat must be once, daily or weekly.')
    when = int(moment.timestamp())
    if not int(time.time()) < when <= int(time.time()) + 366 * 86400:
        raise UserError('Choose a future date within one year.')
    return when, repeat


def schedule_zone(user_id, targets, text=''):
    parts = text.split('|')
    if len(parts) == 3:
        name = parts[2].strip()
        try:
            ZoneInfo(name)
        except ZoneInfoNotFoundError:
            raise UserError('Unknown timezone.') from None
        return name
    names = {STORE.config_for(user_id, target)['timezone'] for target in targets}
    if len(names) > 1:
        raise UserError('Selected channels use different timezones. Add | Asia/Kolkata (or your timezone) after the repeat setting.')
    return next(iter(names), 'Asia/Kolkata')


def next_schedule_cycle(job):
    zone = ZoneInfo(job['post'].get('_schedule_timezone', 'Asia/Kolkata'))
    moment = datetime.fromtimestamp(job['run_at'], zone)
    step = timedelta(days=7 if job['repeat_seconds'] == 604800 else 1)
    while True:
        moment += step
        if moment.timestamp() > time.time():
            # Skip a nonexistent/ambiguous local occurrence instead of guessing.
            try:
                return int(local_moment(moment.strftime('%Y-%m-%d %H:%M'), str(zone)).timestamp())
            except UserError:
                continue


