def pack_slug(value):
    value = value.strip()
    if value.startswith('https://') or value.startswith('http://'):
        parsed = urlparse(value)
        if parsed.hostname not in {'t.me', 'telegram.me', 'telegram.dog'} or parsed.query or parsed.fragment:
            raise UserError('Use a Telegram t.me/addemoji/PACK link.')
        match = re.fullmatch(r'/addemoji/([A-Za-z0-9_]{1,64})/?', parsed.path)
        if not match:
            raise UserError('Use a Telegram t.me/addemoji/PACK link.')
        value = match[1]
    if not re.fullmatch(r'[A-Za-z0-9_]{1,64}', value):
        raise UserError('Use an emoji pack link or its short name.')
    return value


def pack_key(slug):
    return hashlib.sha256(slug.encode()).hexdigest()[:12]


def pack_from_key(user_id, key):
    for pack in STORE.imported_packs(user_id):
        if pack_key(pack['slug']) == key:
            return STORE.imported_pack(user_id, pack['slug'])
    raise UserError('This emoji pack is unavailable.')


async def fetch_emoji_pack(transport, value, user_id):
    if user_id not in transport.config.allowed_users:
        raise UserError('The owner must allow your user ID to import packs using this account.')
    slug = pack_slug(value)
    response = await transport.client(tl_functions.messages.GetStickerSetRequest(tl_types.InputStickerSetShortName(slug), hash=0))
    sticker_set = getattr(response, 'set', None)
    if not sticker_set or not getattr(sticker_set, 'emojis', False):
        raise UserError('This is not a custom emoji pack.')
    items = []
    for document in response.documents:
        attribute = next((a for a in document.attributes if isinstance(a, tl_types.DocumentAttributeCustomEmoji)), None)
        if attribute and attribute.alt and emoji.is_emoji(attribute.alt):
            transport.documents[document.id] = document, attribute.alt
            items.append({'id': str(document.id), 'emoji': attribute.alt, 'name': emoji.demojize(attribute.alt).strip(':').replace('_', ' ')})
    if not items or len(items) > 2000:
        raise UserError('Choose an available custom emoji pack with up to 2000 emojis.')
    return slug, sticker_set.title, items


