def cache_existing_media(chat_id, user_id):
    owner_only(chat_id, user_id)
    if USER_CLIENT is None:
        raise UserError('Connect the Premium account first.')
    def work():
        saved, failed = 0, []
        with STORE.db() as c:
            rows = c.execute('SELECT id,data_json FROM nxt_posts WHERE owner_id=?', (user_id,)).fetchall()
        for row in rows:
            if STOP.is_set():
                break
            data = json.loads(row['data_json'])
            try:
                for item, key in media_slots(data):
                    value = item[key]
                    if vault_reference(value):
                        STORE.media_path(value)
                        continue
                    with tempfile.TemporaryDirectory(prefix='kd-cache-') as temporary:
                        path = USER_CLIENT.call(USER_CLIENT._media(value, temporary))
                        reference = STORE.source_media(value)
                        if not reference and isinstance(path, (str, os.PathLike)):
                            kind = item.get('type') or {'photo_id': 'photo', 'video_id': 'video', 'animation_id': 'animation'}.get(key, 'document')
                            reference = STORE.store_media(value, path, kind)
                        if not reference:
                            raise UserError('This old source cannot be stored. Reattach its media.')
                        item[key] = reference
                STORE.save_post(user_id, chat_id, data, row['id'])
                saved += 1
            except Exception as error:
                failed.append(row['id'] + ': ' + scrub(error)[:100])
        with contextlib.suppress(Exception):
            ui(chat_id, f'🗄️ Media storage complete\nPosts processed: {saved}\nFailed: {len(failed)}\n' + '\n'.join(failed[:8]))
    threading.Thread(target=work, name='media-storage-import', daemon=True).start()
    ui(chat_id, 'Storing existing post media. Results will appear here.')


def safe_profile_settings(values):
    if not isinstance(values, dict):
        raise UserError('Invalid profile settings in backup.')
    result = {key: value for key, value in values.items() if key in SAFE_RESTORE_PREFS}
    if result.get('font', 'normal') not in {'normal', 'smallcaps'} or result.get('pack', 'classic') not in set(PACKS) | {'imported'}:
        raise UserError('Unknown font or emoji pack in backup.')
    for key in ('quote_theme', 'reminders'):
        if key in result and not isinstance(result[key], bool):
            raise UserError('Invalid preference flag in backup.')
    favorites = result.get('favorites', {})
    if not isinstance(favorites, dict) or len(favorites) > 30 or any(not emoji.is_emoji(glyph) or not str(value).isdigit() for glyph, value in favorites.items()):
        raise UserError('Invalid favourite emojis in backup.')
    imported = result.get('imported_map', {})
    if not isinstance(imported, dict) or len(imported) > 2000 or any(not emoji.is_emoji(glyph) or not isinstance(ids, list) or not ids or len(ids) > 2000 or any(not str(value).isdigit() for value in ids) for glyph, ids in imported.items()):
        raise UserError('Invalid imported emoji mapping in backup.')
    if result.get('imported_pack'):
        pack_slug(result['imported_pack'])
    return result


def inspect_backup(path):
    path = Path(path)
    if path.is_symlink() or not path.is_file() or path.stat().st_size > RESTORE_MAX_BYTES:
        raise UserError('Backup is missing or exceeds RESTORE_MAX_MB.')
    plan = {'posts': [], 'meta': [], 'profiles': [], 'channels': [], 'destinations': [], 'packs': [], 'media': [], 'sources': []}
    try:
        with zipfile.ZipFile(path) as archive:
            entries = archive.infolist()
            names = [item.filename for item in entries]
            if len(entries) > 20000 or len(names) != len(set(names)) or 'bot.db' not in names or sum(item.file_size for item in entries) > RESTORE_MAX_BYTES:
                raise UserError('Backup contains too many files, duplicate names, or too much expanded data.')
            for item in entries:
                allowed = item.filename in {'bot.db', 'metrics.db', 'users.json', 'redeem.txt', 'posts.json', 'backup-info.json'} or re.fullmatch(r'media/[a-f0-9]{64}\.[a-z0-9]{1,8}', item.filename)
                mode = item.external_attr >> 16
                if not allowed or stat.S_ISLNK(mode) or item.flag_bits & 1 or item.is_dir():
                    raise UserError('Backup contains an unsafe or unsupported archive entry.')
            with tempfile.TemporaryDirectory(prefix='kd-restore-check-') as temporary:
                database = Path(temporary) / 'snapshot.db'
                with archive.open('bot.db') as source, database.open('wb') as target:
                    shutil.copyfileobj(source, target, 1024 * 1024)
                with sqlite3.connect(database.as_uri() + '?mode=ro', uri=True) as c:
                    c.row_factory = sqlite3.Row
                    c.execute('PRAGMA trusted_schema=OFF')
                    c.execute('PRAGMA query_only=ON')
                    if c.execute('PRAGMA quick_check').fetchone()[0] != 'ok':
                        raise UserError('Backup database failed its integrity check.')
                    tables = {row[0] for row in c.execute("SELECT name FROM sqlite_master WHERE type='table'")}
                    if 'nxt_posts' not in tables or 'nxt_meta' not in tables:
                        raise UserError('This is not a supported KD bot database backup.')
                    def rows(table, columns):
                        if table not in tables:
                            return []
                        values = [dict(row) for row in c.execute('SELECT ' + columns + ' FROM ' + table + ' LIMIT 20001')]
                        if len(values) > 20000:
                            raise UserError('Backup table exceeds the restore record limit.')
                        return values
                    for row in rows('nxt_posts', 'id,owner_id,chat_id,data_json,created_at'):
                        if not isinstance(row['id'], str) or not re.fullmatch(r'[A-Za-z0-9_-]{1,64}', row['id']):
                            raise UserError('Invalid post ID in backup.')
                        if row['owner_id'] is not None and (not isinstance(row['owner_id'], int) or row['owner_id'] <= 0):
                            raise UserError('Invalid post owner in backup.')
                        if not isinstance(row['data_json'], str) or len(row['data_json']) > 200000:
                            raise UserError('Backup post data is too large.')
                        data = json.loads(row['data_json'])
                        if not isinstance(data, dict):
                            raise UserError('Invalid post in backup.')
                        validate_post(data)
                        data['id'] = row['id']
                        row['data_json'] = json.dumps(data, ensure_ascii=False)
                        plan['posts'].append(row)
                    for row in rows('nxt_meta', 'key,value'):
                        if row['key'] in SAFE_RESTORE_META and isinstance(row['value'], str) and len(row['value']) <= 20000:
                            plan['meta'].append(row)
                    for row in rows('nxt_profiles', 'user_id,settings_json'):
                        prefs = safe_profile_settings(json.loads(row['settings_json']))
                        plan['profiles'].append({'user_id': int(row['user_id']), 'settings': prefs})
                    for row in rows('kd_channel_settings', 'user_id,target_id,settings_json'):
                        row['settings_json'] = json.dumps(channel_settings(json.loads(row['settings_json'])), ensure_ascii=False)
                        if int(row['target_id']) >= 0 or int(row['user_id']) <= 0:
                            raise UserError('Invalid channel settings in backup.')
                        plan['channels'].append(row)
                    for row in rows('nxt_destinations', 'user_id,chat_id,title'):
                        if int(row['chat_id']) >= 0 or int(row['user_id']) <= 0:
                            raise UserError('Invalid saved destination in backup.')
                        row['title'] = str(row['title'])[:100]
                        plan['destinations'].append(row)
                    for row in rows('kd_emoji_packs', 'user_id,slug,title,items_json'):
                        pack_slug(row['slug'])
                        items = json.loads(row['items_json'])
                        if not isinstance(items, list) or not 1 <= len(items) <= 2000 or any(not isinstance(item, dict) or not str(item.get('id', '')).isdigit() or not emoji.is_emoji(item.get('emoji', '')) or not isinstance(item.get('name', ''), str) for item in items):
                            raise UserError('Invalid imported emoji pack in backup.')
                        row['items_json'] = json.dumps(items, ensure_ascii=False)
                        plan['packs'].append(row)
                    for row in rows('kd_media', 'digest,name,bytes,created_at'):
                        if not re.fullmatch(r'[a-f0-9]{64}', str(row['digest'])) or not re.fullmatch(re.escape(row['digest']) + r'\.[a-z0-9]{1,8}', str(row['name'])):
                            raise UserError('Invalid media filename in backup.')
                        name = 'media/' + row['name']
                        if name in names:
                            if archive.getinfo(name).file_size != row['bytes'] or not 0 < row['bytes'] <= VAULT_FILE_LIMIT:
                                raise UserError('Invalid media size in backup.')
                            plan['media'].append(row)
                    for row in rows('kd_media_sources', 'source,reference'):
                        if vault_reference(row['reference']) and isinstance(row['source'], str) and len(row['source']) <= 500:
                            plan['sources'].append(row)
    except UserError:
        raise
    except (sqlite3.Error, zipfile.BadZipFile, OSError, ValueError, TypeError, KeyError) as error:
        raise UserError('Backup could not be validated: ' + type(error).__name__) from None
    return plan


def restore_source(name):
    if not re.fullmatch(r'[A-Za-z0-9_.-]+\.zip', name) or '..' in name:
        raise UserError('Choose a backup listed in the restore menu.')
    for folder in ('backups', 'restore-uploads'):
        path = STORE.folder / folder / name
        if path.is_file() and not path.is_symlink():
            return path
    raise UserError('Backup file not found.')


def restore_preview(chat_id, user_id, name, replace=False):
    owner_only(chat_id, user_id)
    private_only(chat_id, user_id)
    path = restore_source(name)
    plan = inspect_backup(path)
    with STORE.db() as c:
        existing = {row[0] for row in c.execute('SELECT id FROM nxt_posts')}
    conflicts = sum(row['id'] in existing for row in plan['posts'])
    token = secrets.token_hex(8)
    keyboard = types.InlineKeyboardMarkup().add(button('Restore These Items', action='kd_restore_apply:' + token, glyph='✅', color='green'), button('Matching Items: ' + ('Replace' if replace else 'Keep Current'), action='kd_restore_mode:' + token, glyph='⚙️'), button('Cancel', action='cancel', glyph='❌', color='red'))
    prompt = ui(chat_id, f'💾 Restore Preview\nFile: {name}\nNew posts: {len(plan["posts"]) - conflicts}\nMatching post IDs: {conflicts}\nGlobal settings: {len(plan["meta"])}\nProfile settings: {len(plan["profiles"])}\nChannel settings: {len(plan["channels"])}\nMedia files: {len(plan["media"])}\nMode: {"Replace matching posts/settings" if replace else "Recover missing posts/settings; keep current values"}\n\nA fresh backup is made first. Users, balances, subscriptions, payments, bans, schedules and delivery history stay as they are. Scheduled jobs from the backup are not imported. Media absent from this archive needs its existing source.', keyboard)
    STORE.set_state(chat_id, user_id, 'kd_restore_preview', {'name': name, 'sha256': file_sha256(path), 'token': token, 'replace': replace}, prompt.message_id)


def apply_restore(path, expected_hash, replace=False):
    if not RESTORE_LOCK.acquire(blocking=False):
        raise UserError('Another restore is running.')
    STORE.setting('restore_active', '1')
    try:
        with PUBLICATION_LOCK:
            if file_sha256(path) != expected_hash:
                raise UserError('Backup changed since preview. Open a fresh preview.')
            plan = inspect_backup(path)
            # Verify every media payload before changing any database rows.
            with tempfile.TemporaryDirectory(prefix='kd-restore-media-') as temporary, zipfile.ZipFile(path) as archive:
                # Open the source first; retention of the new safety backup may prune an old source archive.
                safety_backup = STORE.create_backup()
                verified = []
                for row in plan['media']:
                    destination = Path(temporary) / row['name']
                    with archive.open('media/' + row['name']) as source, destination.open('wb') as target:
                        shutil.copyfileobj(source, target, 1024 * 1024)
                    if file_sha256(destination) != row['digest']:
                        raise UserError('Media checksum mismatch. Restore stopped before database changes.')
                    verified.append((row, destination))
                with VAULT_LOCK:
                    with STORE.db() as c:
                        known_media = {row[0] for row in c.execute('SELECT digest FROM kd_media')}
                        total = c.execute('SELECT COALESCE(SUM(bytes),0) FROM kd_media').fetchone()[0]
                    if total + sum(row['bytes'] for row, _ in verified if row['digest'] not in known_media) > VAULT_TOTAL_LIMIT:
                        raise UserError('Restored media would exceed MEDIA_VAULT_TOTAL_MB.')
                    folder = STORE.folder / 'media'
                    folder.mkdir(mode=0o700, exist_ok=True)
                    for row, source in verified:
                        destination = folder / row['name']
                        if destination.is_symlink():
                            raise UserError('Unsafe media destination.')
                        if not destination.exists() or file_sha256(destination) != row['digest']:
                            partial = folder / (row['name'] + '.partial')
                            shutil.copyfile(source, partial)
                            os.chmod(partial, 0o600)
                            os.replace(partial, destination)
                    restored = 0
                    with STORE.db() as c:
                        users = {row[0] for row in c.execute('SELECT user_id FROM users')}
                        for row in plan['posts']:
                            if row['owner_id'] is not None and row['owner_id'] not in users:
                                continue
                            previous = c.execute('SELECT owner_id FROM nxt_posts WHERE id=?', (row['id'],)).fetchone()
                            if previous and (not replace or previous[0] != row['owner_id']):
                                continue
                            c.execute('INSERT OR REPLACE INTO nxt_posts VALUES (?,?,?,?,?)', tuple(row[key] for key in ('id', 'owner_id', 'chat_id', 'data_json', 'created_at')))
                            restored += 1
                        for row in plan['meta']:
                            if replace:
                                c.execute('INSERT INTO nxt_meta VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', (row['key'], row['value']))
                            else:
                                c.execute('INSERT OR IGNORE INTO nxt_meta VALUES (?,?)', (row['key'], row['value']))
                        for row in plan['profiles']:
                            current = c.execute('SELECT settings_json FROM nxt_profiles WHERE user_id=?', (row['user_id'],)).fetchone()
                            if not current:
                                continue
                            prefs = json.loads(current[0])
                            prefs = dict(prefs, **row['settings']) if replace else dict(row['settings'], **prefs)
                            c.execute('UPDATE nxt_profiles SET settings_json=? WHERE user_id=?', (json.dumps(prefs, ensure_ascii=False), row['user_id']))
                        for row in plan['channels']:
                            if row['user_id'] not in users:
                                continue
                            query = 'INSERT OR REPLACE' if replace else 'INSERT OR IGNORE'
                            c.execute(query + ' INTO kd_channel_settings VALUES (?,?,?)', (row['user_id'], row['target_id'], row['settings_json']))
                        for row in plan['destinations']:
                            if row['user_id'] in users:
                                c.execute('INSERT OR IGNORE INTO nxt_destinations(user_id,chat_id,title) VALUES (?,?,?)', (row['user_id'], row['chat_id'], row['title']))
                        for row in plan['packs']:
                            if row['user_id'] in users:
                                query = 'INSERT OR REPLACE' if replace else 'INSERT OR IGNORE'
                                c.execute(query + ' INTO kd_emoji_packs VALUES (?,?,?,?)', tuple(row[key] for key in ('user_id', 'slug', 'title', 'items_json')))
                        for row, _ in verified:
                            c.execute('INSERT OR REPLACE INTO kd_media VALUES (?,?,?,?)', tuple(row[key] for key in ('digest', 'name', 'bytes', 'created_at')))
                        for row in plan['sources']:
                            if c.execute('SELECT 1 FROM kd_media WHERE digest=?', (vault_reference(row['reference'])[0],)).fetchone():
                                c.execute('INSERT OR IGNORE INTO kd_media_sources VALUES (?,?)', (row['source'], row['reference']))
                        c.execute('INSERT INTO nxt_audit(action,user_id,detail,created_at) VALUES (?,?,?,?)', ('backup_restore', ADMIN_ID, f'{path.name}; posts={restored}; replace={replace}', int(time.time())))
            return restored, safety_backup
    finally:
        STORE.setting('restore_active', '0')
        RESTORE_LOCK.release()


def restore_panel(chat_id, user_id):
    owner_only(chat_id, user_id)
    private_only(chat_id, user_id)
    paths = sorted((STORE.folder / 'backups').glob('*.zip'), key=lambda p: p.stat().st_mtime, reverse=True)[:12]
    keyboard = types.InlineKeyboardMarkup()
    for path in paths:
        keyboard.add(button(path.name[:42], action='kd_restore_file:' + hashlib.sha256(path.name.encode()).hexdigest()[:12], glyph='💾'))
    keyboard.add(button('Upload Backup ZIP', action='kd_restore_upload', glyph='📤'), button('Backups', action='admin_backups', glyph='⬅️'))
    ui(chat_id, '💾 Restore Posts & Settings\nChoose a backup for a preview or upload its ZIP. Restore merges selected data into the current database.', keyboard)


def restore_worker(chat_id, user_id, data):
    owner_only(chat_id, user_id)
    path = restore_source(data['name'])
    def work():
        try:
            count, safety = apply_restore(path, data['sha256'], data['replace'])
            STORE.clear_state(chat_id, user_id)
            ui(chat_id, f'✅ Restore complete\nPosts recovered: {count}\nSafety backup: {safety.name}\nUse My Posts, channel settings and imported packs to inspect the recovered data.', home_keys())
        except Exception as error:
            log_error('backup restore', error)
            with contextlib.suppress(Exception):
                ui(chat_id, '❌ Restore stopped: ' + scrub(error)[:400])
    threading.Thread(target=work, name='backup-restore', daemon=True).start()
    ui(chat_id, 'Restoring the previewed items. Results will appear here.')


_backups_panel_base = backups_panel


def backups_panel(chat_id, user_id):
    owner_only(chat_id, user_id)
    files = list((STORE.folder / 'backups').glob('*.zip'))
    keyboard = types.InlineKeyboardMarkup().add(button('Create & Download Backup', action='admin_backup_now', glyph='💾'), button('Download Latest', action='admin_backup_latest', glyph='📥'), button('Restore Posts & Settings', action='kd_restore', glyph='♻️'), button('Toggle Media in Backups', action='kd_backup_media', glyph='🗄️'), button('Toggle Daily Backup', action='admin_backup_toggle', glyph='⏰'), button('Owner Panel', action='admin_owner_panel', glyph='⬅️'))
    ui(chat_id, f'💾 Backups\nArchives: {len(files)}\nDaily: {"On" if setting_on("automatic_backups") else "Off"}\nInclude media: {"On" if STORE.meta("backup_include_media", "1") == "1" else "Off"}\nKeeps 7 automatic and 10 manual archives. Credentials stay in environment variables. Restore previews posts/settings/media and creates a fresh safety backup.', keyboard)


def alerts_panel(chat_id, user_id):
    owner_only(chat_id, user_id)
    with STORE.db() as c:
        rows = c.execute('SELECT text,status,updated_at FROM kd_alerts ORDER BY updated_at DESC LIMIT 8').fetchall()
    text = '🔔 Account & Delivery Alerts\n' + ('\n\n'.join(f'[{row["status"]}] {row["text"][:280]}' for row in rows) if rows else 'No alerts recorded.')
    ui(chat_id, text + '\n\nIf the account cannot connect, alerts stay stored for delivery after reconnection. Hybrid mode can notify through the bot.', types.InlineKeyboardMarkup().add(button('Owner Panel', action='admin_owner_panel', glyph='⬅️')))


def start_delivery_edit(chat_id, user_id, publication_id):
    row = STORE.publication(publication_id, user_id)
    if row['status'] not in {'success', 'edited'}:
        raise UserError('Only confirmed published posts can be edited. Inspect this delivery first.')
    ask(chat_id, user_id, 'kd_edit_text', f'✏️ Send the new text/caption for delivery #{publication_id}.\nExisting media and URL links are retained. Channel footer and hashtags will be appended.', {'publication_id': int(publication_id)})


def confirm_delivery_delete(chat_id, user_id, publication_id):
    row = STORE.publication(publication_id, user_id)
    if not row['ids']:
        raise UserError('No confirmed message IDs are available for deletion.')
    keyboard = types.InlineKeyboardMarkup().add(button('Delete From Channel', action=f'kd_delete_yes:{row["id"]}', glyph='🗑️', color='red'), button('Keep Messages', action=f'kd_delivery:{row["id"]}', glyph='⬅️'))
    message = ui(chat_id, f'🗑️ Delete {len(row["ids"])} tracked messages from {row["title"]}?\nThis removes the published messages. Your saved post is kept. Any unconfirmed message without a stored ID must be checked in the channel.', keyboard)
    STORE.set_state(chat_id, user_id, 'kd_delete_confirm', {'id': row['id']}, message.message_id)


_feature_command_base = feature_command


def feature_command(message):
    name, _, argument = (message.text or '').partition(' ')
    name, argument = name.split('@')[0].lower(), argument.strip()
    names = {'/history', '/sent', '/pause', '/resume', '/draft', '/restore', '/packs', '/pack', '/findemoji', '/channel', '/vault', '/alerts', '/publisher', '/edit', '/delete'}
    if name not in names:
        return _feature_command_base(message)
    chat_id, user_id = message.chat.id, message.from_user.id
    private_only(chat_id, user_id)
    guard_user(user_id)
    if name in {'/pause', '/resume', '/restore', '/vault', '/alerts', '/publisher'}:
        owner_only(chat_id, user_id)
    elif not require_join(chat_id, user_id):
        return True
    if name in {'/history', '/sent'}:
        history_panel(chat_id, user_id)
    elif name in {'/pause', '/resume'}:
        STORE.pause(name == '/pause')
        publisher_panel(chat_id, user_id)
    elif name == '/draft':
        recover_draft(chat_id, user_id)
    elif name == '/restore':
        restore_preview(chat_id, user_id, argument) if argument else restore_panel(chat_id, user_id)
    elif name == '/packs':
        imported_panel(chat_id, user_id)
    elif name == '/pack':
        if argument:
            import_pack(chat_id, user_id, argument)
        else:
            ask(chat_id, user_id, 'kd_pack_import', '🎨 Send a t.me/addemoji/PACK link.')
    elif name == '/findemoji':
        if argument:
            pack_preview(chat_id, user_id, 'all', query=argument)
        else:
            ask(chat_id, user_id, 'kd_emoji_search', '🔎 Search imported emojis by name (fire, heart), normal emoji or document ID.')
    elif name == '/channel':
        if not argument:
            raise UserError('Use /channel @YourChannel or open My Channels.')
        channel_panel(chat_id, user_id, int(argument) if argument.lstrip('-').isdigit() else argument)
    elif name == '/vault':
        vault_panel(chat_id, user_id)
    elif name == '/alerts':
        alerts_panel(chat_id, user_id)
    elif name == '/publisher':
        publisher_panel(chat_id, user_id)
    elif name == '/edit':
        parts = argument.split()
        if len(parts) not in (1, 2) or not parts[0].isdigit():
            raise UserError('Use /edit DELIVERY_ID, or /edit DELIVERY_ID SAVED_POST_ID for updated text and existing links.')
        if len(parts) == 1:
            start_delivery_edit(chat_id, user_id, int(parts[0]))
        else:
            row = STORE.publication(int(parts[0]), user_id)
            replacement = apply_channel_settings(STORE.post(parts[1], user_id), STORE.config_for(user_id, row['target_id']))
            update_delivery(chat_id, user_id, int(parts[0]), replacement)
    elif name == '/delete':
        if not argument.isdigit():
            raise UserError('Use /delete DELIVERY_ID. A confirmation is shown before deletion.')
        confirm_delivery_delete(chat_id, user_id, int(argument))
    return True


_feature_callback_base = feature_callback


def feature_callback(call):
    action = call.data or ''
    if not action.startswith('kd_'):
        if action == 'emoji_pack:imported':
            imported_panel(call.message.chat.id, call.from_user.id)
            return True
        return _feature_callback_base(call)
    chat_id, user_id = call.message.chat.id, call.from_user.id
    private_only(chat_id, user_id)
    guard_user(user_id)
    verb, _, value = action.partition(':')
    owner_actions = {'kd_pause', 'kd_resume', 'kd_publisher', 'kd_vault', 'kd_vault_cache', 'kd_restore', 'kd_restore_file', 'kd_restore_upload', 'kd_restore_mode', 'kd_restore_apply', 'kd_backup_media', 'kd_alerts'}
    if verb in owner_actions:
        owner_only(chat_id, user_id)
    elif not require_join(chat_id, user_id):
        return True
    if verb == 'kd_history':
        history_panel(chat_id, user_id, int(value or 0))
    elif verb == 'kd_delivery':
        delivery_panel(chat_id, user_id, int(value))
    elif verb == 'kd_edit':
        start_delivery_edit(chat_id, user_id, int(value))
    elif verb == 'kd_delete':
        confirm_delivery_delete(chat_id, user_id, int(value))
    elif verb == 'kd_delete_yes':
        data = active_prompt(call, {'kd_delete_confirm'})
        if data['id'] != int(value):
            raise UserError('Open a fresh deletion confirmation.')
        update_delivery(chat_id, user_id, int(value), delete=True)
    elif verb in {'kd_pause', 'kd_resume'}:
        STORE.pause(verb == 'kd_pause')
        publisher_panel(chat_id, user_id)
    elif verb == 'kd_publisher':
        publisher_panel(chat_id, user_id)
    elif verb == 'kd_draft':
        recover_draft(chat_id, user_id)
    elif verb == 'kd_channels':
        channels_panel(chat_id, user_id)
    elif verb == 'kd_channel':
        channel_panel(chat_id, user_id, int(value))
    elif verb == 'kd_cfg':
        target, _, key = value.partition(':')
        if key not in {'footer', 'hashtags', 'timezone', 'daily_limit'}:
            raise UserError('Unknown setting.')
        checked_destination(user_id, int(target))
        help_text = {'footer': 'Send a footer (up to 500 units), or CLEAR.', 'hashtags': 'Send #news #KD style hashtags, or CLEAR.', 'timezone': 'Send an IANA timezone such as Asia/Kolkata, UTC or Europe/London.', 'daily_limit': 'Send a daily post limit from 0 to 10000. 0 disables this local limit.'}[key]
        ask(chat_id, user_id, 'kd_channel_setting', help_text, {'target': int(target), 'key': key})
    elif verb == 'kd_packs':
        imported_panel(chat_id, user_id)
    elif verb in {'kd_pack_import', 'kd_emoji_search'}:
        ask(chat_id, user_id, verb, 'Send a t.me/addemoji/PACK link.' if verb == 'kd_pack_import' else 'Search imported emojis by name, normal emoji or document ID.')
    elif verb == 'kd_pack':
        pack_preview(chat_id, user_id, value)
    elif verb == 'kd_pack_page':
        key, _, offset = value.partition(':')
        pack_preview(chat_id, user_id, key, max(0, int(offset)))
    elif verb == 'kd_search_page':
        pack_preview(chat_id, user_id, 'all', max(0, int(value)), STORE.profile(user_id)['settings'].get('emoji_search_query', ''))
    elif verb == 'kd_pack_use':
        pack = pack_from_key(user_id, value)
        mapping = {}
        for item in pack['items']:
            mapping.setdefault(item['emoji'], []).append(item['id'])
        STORE.update_profile(user_id, pack='imported', imported_pack=pack['slug'], imported_map=mapping)
        emoji_panel(chat_id, user_id)
    elif verb == 'kd_pack_remove':
        pack = pack_from_key(user_id, value)
        with STORE.db() as c:
            c.execute('DELETE FROM kd_emoji_packs WHERE user_id=? AND slug=?', (user_id, pack['slug']))
        if STORE.profile(user_id)['settings'].get('imported_pack') == pack['slug']:
            STORE.update_profile(user_id, pack='classic', imported_pack='', imported_map={})
        imported_panel(chat_id, user_id)
    elif verb == 'kd_vault':
        vault_panel(chat_id, user_id)
    elif verb == 'kd_vault_cache':
        cache_existing_media(chat_id, user_id)
    elif verb == 'kd_restore':
        restore_panel(chat_id, user_id)
    elif verb == 'kd_restore_file':
        path = next((p for p in (STORE.folder / 'backups').glob('*.zip') if hashlib.sha256(p.name.encode()).hexdigest()[:12] == value), None)
        if path is None:
            raise UserError('That backup is no longer available.')
        restore_preview(chat_id, user_id, path.name)
    elif verb == 'kd_restore_upload':
        ask(chat_id, user_id, 'kd_restore_upload', 'Upload your KD backup ZIP as a document. It will be validated before a restore preview.')
    elif verb in {'kd_restore_mode', 'kd_restore_apply'}:
        data = active_prompt(call, {'kd_restore_preview'})
        if data['token'] != value:
            raise UserError('Open a fresh restore preview.')
        if verb == 'kd_restore_mode':
            restore_preview(chat_id, user_id, data['name'], not data['replace'])
        else:
            STORE.set_state(chat_id, user_id, 'kd_restore_running', {})
            restore_worker(chat_id, user_id, data)
    elif verb == 'kd_backup_media':
        STORE.setting('backup_include_media', '0' if STORE.meta('backup_include_media', '1') == '1' else '1')
        backups_panel(chat_id, user_id)
    elif verb == 'kd_alerts':
        alerts_panel(chat_id, user_id)
    else:
        raise UserError('Unknown publishing control.')
    return True


def accept_restore_upload(chat_id, user_id, path):
    owner_only(chat_id, user_id)
    inspect_backup(path)
    digest = file_sha256(path)
    folder = STORE.folder / 'restore-uploads'
    folder.mkdir(mode=0o700, exist_ok=True)
    destination = folder / ('upload-' + digest[:20] + '.zip')
    if Path(path) != destination:
        shutil.copyfile(path, destination)
        os.chmod(destination, 0o600)
    for old in sorted(folder.glob('upload-*.zip'), key=lambda p: p.stat().st_mtime, reverse=True)[5:]:
        if old != destination:
            old.unlink()
    restore_preview(chat_id, user_id, destination.name)


_feature_input_base = feature_input


def feature_input(message, state):
    stage, data = state['stage'], state['data']
    chat_id, user_id = message.chat.id, message.from_user.id
    text = (message.text or '').strip()
    if stage in {'schedule_time', 'schedule_edit_time'}:
        if not require_post(chat_id, user_id):
            return True
        job = STORE.schedule(data['job_id'], user_id) if stage == 'schedule_edit_time' else None
        targets = job['targets'] if job else data['targets']
        zone = schedule_zone(user_id, targets, text)
        when, repeat = parse_schedule(text, zone)
        if job:
            STORE.change_schedule(job['id'], user_id, 'time', run_at=when, repeat_seconds=repeat)
            post = dict(job['post'], _schedule_timezone=zone)
            STORE.change_schedule(job['id'], user_id, 'content', post=post)
            job_id = job['id']
        else:
            post = dict(STORE.post(data['id'], user_id), _schedule_timezone=zone)
            job_id = STORE.create_schedule(user_id, chat_id, post, targets, when, repeat)
        STORE.clear_state(chat_id, user_id)
        schedule_panel(chat_id, user_id, job_id)
        return True
    if not stage.startswith('kd_'):
        return _feature_input_base(message, state)
    private_only(chat_id, user_id)
    guard_user(user_id)
    if stage.startswith('kd_restore'):
        owner_only(chat_id, user_id)
    elif not require_join(chat_id, user_id):
        return True
    if stage == 'kd_edit_text':
        if message.content_type != 'text':
            raise UserError('Send the replacement text/caption as a text message.')
        row = STORE.publication(data['publication_id'], user_id)
        content, entities = premium_text(message.text or '', entity_dicts(message.entities), preferences=STORE.profile(user_id)['settings'])
        replacement = dict(row['payload'], content=content, entities=entities, raw_text=message.text, raw_entities=entity_dicts(message.entities))
        replacement = apply_channel_settings(replacement, STORE.config_for(user_id, row['target_id']))
        update_delivery(chat_id, user_id, row['id'], replacement)
    elif stage == 'kd_channel_setting':
        checked_destination(user_id, data['target'])
        config = STORE.config_for(user_id, data['target'])
        config[data['key']] = '' if text.upper() == 'CLEAR' and data['key'] in {'footer', 'hashtags'} else text
        STORE.configure_channel(user_id, data['target'], config)
        STORE.clear_state(chat_id, user_id)
        channel_panel(chat_id, user_id, data['target'])
    elif stage == 'kd_pack_import':
        import_pack(chat_id, user_id, text)
    elif stage == 'kd_emoji_search':
        STORE.clear_state(chat_id, user_id)
        pack_preview(chat_id, user_id, 'all', query=text)
    elif stage == 'kd_restore_upload':
        document = getattr(message, 'document', None)
        if not document or not str(getattr(document, 'file_name', '') or '').lower().endswith('.zip'):
            raise UserError('Send a ZIP backup document.')
        if isinstance(BOT, UserBotAPI):
            raise UserError('Use .restore as a reply to the ZIP, or upload it after opening the restore menu.')
        with tempfile.TemporaryDirectory(prefix='kd-restore-upload-') as temporary:
            path = download_bot_media(document.file_id, temporary)
            accept_restore_upload(chat_id, user_id, path)
    elif stage in {'kd_restore_preview', 'kd_delete_confirm'}:
        raise UserError('Use the confirmation choices on the latest prompt or /cancel.')
    elif stage == 'kd_restore_running':
        raise UserError('Restore is running. Its result will appear here.')
    else:
        raise UserError('Use the latest menu choices or /cancel.')
    return True


