async def advanced_user_event(self, event):
    if event.sender_id != self.transport.me.id or event.chat_id != self.transport.me.id or not event.out:
        return
    text = event.raw_text or ''
    name, _, argument = text.partition(' ')
    state = STORE.state(event.chat_id, event.sender_id)
    if state and not text.startswith(".") and METRICS is not None:
        self._metrics_input_seen = METRICS.interaction(event.sender_id, ("message", event.chat_id, event.id), text)
    advanced_commands = {'.history', '.sent', '.pause', '.resume', '.draft', '.restore', '.packs', '.pack', '.findemoji', '.channel', '.vault', '.alerts', '.publisher', '.edit', '.delete'}
    restore_message = None
    if name.lower() == '.restore' and event.is_reply and not argument.strip():
        restore_message = await event.get_reply_message()
    elif not text.startswith('.') and state and state['stage'] == 'kd_restore_upload':
        restore_message = event.message
    if restore_message is not None:
        owner_only(event.chat_id, event.sender_id)
        document = getattr(restore_message, 'document', None)
        filename = next((a.file_name for a in getattr(document, 'attributes', []) if isinstance(a, tl_types.DocumentAttributeFilename)), '')
        if not document or not filename.lower().endswith('.zip') or document.size > RESTORE_MAX_BYTES:
            raise UserError('Reply to a KD ZIP backup within RESTORE_MAX_MB.')
        with tempfile.TemporaryDirectory(prefix='kd-restore-upload-') as temporary:
            path = await self.transport.client.download_media(restore_message, file=str(Path(temporary) / 'backup.zip'))
            if not path:
                raise UserError('Backup download failed.')
            await asyncio.to_thread(accept_restore_upload, event.chat_id, event.sender_id, path)
        return
    if name.lower() in advanced_commands:
        converted = self.convert_message(event.message, '/' + name[1:].lower() + (' ' + argument.strip() if argument.strip() else ''))
        await asyncio.to_thread(on_message, converted)
        return
    if name.lower() == '.new' and event.is_reply:
        reply = await event.get_reply_message()
        if not getattr(reply, 'grouped_id', None):
            await capture_user_media(self.transport, reply)
    elif not text.startswith('.') and state and not state['stage'].startswith('kd_restore'):
        await capture_user_media(self.transport, event.message)
    await _handle_user_event_base(self, event)


UserBotAPI._handle_event = advanced_user_event
