def send_post(chat_id, data):
    if isinstance(chat_id, int) and chat_id < 0:
        with PUBLICATION_LOCK:
            return _managed_send_post(chat_id, data)
    return _managed_send_post(chat_id, data)


def publish(chat_id, user_id, post_id, target):
    if not require_post(chat_id, user_id):
        return False
    data = STORE.post(post_id, user_id)
    destination = checked_destination(user_id, target)
    try:
        result = send_post(destination.id, data)
    except Exception as error:
        if not isinstance(error, (PublisherPaused, PublishDeferred)):
            STORE.record_delivery(user_id, data['id'], destination.id, 'uncertain' if isinstance(error, DeliveryUncertain) else 'failed', str(error))
        raise
    STORE.record_delivery(user_id, data['id'], destination.id, 'success')
    first = (result[0] if result else None) if isinstance(result, list) else result
    publication_id = getattr(first, 'publication_id', None)
    keyboard = types.InlineKeyboardMarkup().add(button('View Delivery', action=f'kd_delivery:{publication_id}', glyph='📨')) if publication_id else home_keys()
    ui(chat_id, '✅ Sent successfully.' + (f'\nDelivery ID: {publication_id}' if publication_id else ''), keyboard)
    return True


def publish_many(chat_id, user_id, post_id, targets):
    data = STORE.post(post_id, user_id)
    with PUBLISH_GUARD:
        if user_id in PUBLISHING:
            raise UserError('Your previous multi-channel delivery is still running.')
        PUBLISHING.add(user_id)
    STORE.clear_state(chat_id, user_id)
    def work():
        success, failed = [], []
        try:
            for target in targets:
                while not STOP.is_set():
                    if STORE.paused():
                        STOP.wait(1)
                        continue
                    try:
                        guard_user(user_id)
                        if not has_access(user_id) or missing_channels(user_id):
                            raise UserError('Access expired or required channel membership is missing.')
                        chat = checked_destination(user_id, target)
                        send_post(chat.id, data)
                        STORE.record_delivery(user_id, post_id, chat.id, 'success')
                        success.append(str(chat.id))
                    except PublisherPaused:
                        continue
                    except Exception as error:
                        STORE.record_delivery(user_id, post_id, target, 'uncertain' if isinstance(error, DeliveryUncertain) else 'failed', str(error))
                        failed.append(f'{target}: {scrub(error)[:100]}')
                    break
                if STOP.is_set():
                    break
            with contextlib.suppress(Exception):
                ui(chat_id, f'📢 Delivery finished\nSent: {len(success)}\nFailed / deferred: {len(failed)}\n' + '\n'.join(failed[:10]), home_keys())
        finally:
            with PUBLISH_GUARD:
                PUBLISHING.discard(user_id)
    threading.Thread(target=work, name=f'publish-{user_id}', daemon=True).start()
    ui(chat_id, f'📤 Publishing to {len(targets)} destinations. Emergency pause holds the remaining targets until resume.')


_broadcast_base = broadcast


def broadcast(message):
    if STORE.paused():
        raise PublisherPaused('Publishing is paused. Resume before starting a broadcast.')
    return _broadcast_base(message)


def schedule_ledger(job, target, status, ids=None, detail=''):
    with STORE.db() as c:
        c.execute("INSERT INTO nxt_deliveries(job_id,cycle_at,target_id,status,message_ids,detail) VALUES (?,?,?,?,?,?) ON CONFLICT(job_id,cycle_at,target_id) DO UPDATE SET status=excluded.status,message_ids=excluded.message_ids,detail=excluded.detail", (job['id'], job['run_at'], target, status, json.dumps(ids or []), detail[:500]))


def process_schedule(job):
    job_id, user_id, cycle = job['id'], job['user_id'], job['run_at']
    failure, uncertain, deferred, wait_until = [], False, False, 0
    try:
        guard_user(user_id)
        if not has_access(user_id):
            raise UserError('Access expired. Renew access before retrying.')
        if missing_channels(user_id):
            raise UserError('Required channel membership is missing.')
        for target in job['targets']:
            if STOP.is_set():
                raise DeliveryUncertain('Application stopped during delivery. Check channels before retrying.')
            if STORE.paused():
                deferred = True
                break
            with STORE.db() as c:
                previous = c.execute('SELECT status FROM nxt_deliveries WHERE job_id=? AND cycle_at=? AND target_id=?', (job_id, cycle, target)).fetchone()
            if previous and previous[0] == 'success':
                continue
            if previous and previous[0] in {'sending', 'uncertain'}:
                uncertain = True
                failure.append(f'{target}: previous delivery unconfirmed')
                continue
            try:
                guard_user(user_id)
                if not has_access(user_id):
                    raise UserError('Access expired during delivery.')
                chat = checked_destination(user_id, target)
            except Exception as error:
                detail = scrub(error)[:250]
                schedule_ledger(job, target, 'failed', detail=detail)
                STORE.record_delivery(user_id, job['post_id'], target, 'failed', detail)
                failure.append(f'{target}: {detail}')
                continue
            schedule_ledger(job, target, 'sending')
            try:
                result = send_post(chat.id, job['post'])
            except (PublisherPaused, PublishDeferred) as error:
                schedule_ledger(job, target, 'retry', detail=str(error))
                deferred, wait_until = True, getattr(error, 'until', 0)
                break
            except Exception as error:
                ambiguous = isinstance(error, DeliveryUncertain) or not isinstance(error, (ApiTelegramException, UserError))
                status, detail = ('uncertain' if ambiguous else 'failed'), scrub(error)[:250]
                uncertain = uncertain or ambiguous
                schedule_ledger(job, target, status, getattr(error, 'message_ids', []), detail)
                STORE.record_delivery(user_id, job['post_id'], target, status, detail)
                failure.append(f'{target}: {detail}')
            else:
                schedule_ledger(job, target, 'success', delivered_ids(result))
                STORE.record_delivery(user_id, job['post_id'], target, 'success')
            STOP.wait(0.1)
    except Exception as error:
        uncertain = uncertain or isinstance(error, DeliveryUncertain)
        failure.append(scrub(error)[:250])
    status = 'needs_review' if uncertain else 'failed' if failure else 'pending' if deferred else 'done'
    next_run = cycle
    if not failure and not deferred and job['repeat_seconds']:
        next_run, status = next_schedule_cycle(job), 'pending'
    with STORE.db() as c:
        c.execute("UPDATE nxt_schedules SET status=?,run_at=?,last_error=? WHERE id=? AND status='running'", (status, next_run, '\n'.join(failure)[:1500] or ('Waiting for publishing to resume / daily limit reset.' if deferred else ''), job_id))
        if wait_until:
            c.execute('INSERT OR REPLACE INTO kd_schedule_wait VALUES (?,?)', (job_id, wait_until))
        elif not deferred:
            c.execute('DELETE FROM kd_schedule_wait WHERE job_id=?', (job_id,))
    if failure:
        queue_alert('schedule:' + job_id, f'Scheduled post {job_id}: {status}. ' + '\n'.join(failure)[:700])
    if not deferred:
        with contextlib.suppress(Exception):
            keyboard = types.InlineKeyboardMarkup().add(button('View Schedule', action='schedule_open:' + job_id, glyph='⏰'))
            ui(job['origin_chat'], f'⏰ Scheduled post {job_id}\nResult: {status}\n' + ('\n'.join(failure)[:1200] if failure else 'Delivered to all selected destinations.'), keyboard, codes=[job_id])


