def flush_alerts():
    now = int(time.time())
    with STORE.db() as c:
        rows = c.execute("SELECT key,text FROM kd_alerts WHERE status='pending' AND last_sent<=? ORDER BY updated_at LIMIT 3", (now - 60,)).fetchall()
    for row in rows:
        if STOP.is_set() or BOT is None:
            return
        with STORE.db() as c:
            changed = c.execute("UPDATE kd_alerts SET status='sending',last_sent=? WHERE key=? AND status='pending'", (now, row['key'])).rowcount
        if not changed:
            continue
        try:
            tg(BOT.send_message, ADMIN_ID, '🔔 KD Userbot Alert\n' + row['text'], max_wait=0)
        except Exception as error:
            status = 'pending' if isinstance(error, (UserError, ApiTelegramException)) and not isinstance(error, DeliveryUncertain) else 'unconfirmed'
        else:
            status = 'sent'
        with STORE.db() as c:
            c.execute('UPDATE kd_alerts SET status=? WHERE key=?', (status, row['key']))


def account_health_tick():
    now = int(time.time())
    if USER_CLIENT is None or now - int(STORE.meta('last_account_health_check', '0')) < 60:
        return
    STORE.setting('last_account_health_check', now)
    if not USER_CLIENT.thread or not USER_CLIENT.thread.is_alive():
        queue_alert('account_connection', 'The Premium account is disconnected. Check its session and restart the application.')
        return
    try:
        me = USER_CLIENT.call(USER_CLIENT.client.get_me(), timeout=20)
    except Exception as error:
        queue_alert('account_connection', 'Premium account health check failed: ' + scrub(error))
    else:
        premium = bool(getattr(me, 'premium', False))
        if not premium:
            queue_alert('premium_status', 'Telegram Premium is inactive. Channel publishing will reject Premium posts until the account has Premium again.')
        if STORE.meta('last_premium_status') == '0' and premium:
            queue_alert('premium_restored', 'Telegram Premium is active again.')
        STORE.setting('last_premium_status', '1' if premium else '0')


