from collections import Counter, OrderedDict

METRICS = None
METRIC_NAMES = {'messages', 'commands', 'callbacks', 'posts_created', 'published', 'publish_failed',
                'publish_uncertain', 'handler_errors', 'input_rejected', 'handler_count', 'handler_us',
                'activity_overflow'}
METRIC_COMMANDS = {'start', 'help', 'new', 'send', 'posts', 'preview', 'channels', 'schedules', 'templates',
                   'emojis', 'emoji', 'owner', 'backup', 'cancel', 'access', 'history', 'sent', 'pause',
                   'resume', 'draft', 'restore', 'packs', 'pack', 'findemoji', 'channel', 'vault', 'alerts',
                   'publisher', 'edit', 'delete', 'stats', 'metrics', 'effects', 'effect', 'theme', 'other'}
METRIC_NAMES.update('command.' + name for name in METRIC_COMMANDS)


class InteractionMetrics:
    """Bounded RAM counters; one independent, batched WAL writer; SQL-free stats reads."""
    def __init__(self, folder, interval=5, retention=90, autostart=True, clock=None, actor_limit=16384):
        self.folder = Path(folder)
        self.folder.mkdir(mode=0o700, parents=True, exist_ok=True)
        self.path = self.folder / 'metrics.db'
        self.interval = min(60.0, max(1.0, float(interval)))
        self.retention = min(366, max(1, int(retention)))
        self.clock = clock or time.time
        self.actor_limit = max(1, int(actor_limit))
        self.guard = threading.Condition(threading.RLock())
        self.writer_guard = threading.Lock()
        self.stop_event = threading.Event()
        self.wake = threading.Event()
        self.pending, self.total = Counter(), Counter()
        self.actors, self.unique, self.recent = {}, Counter(), OrderedDict()
        self.loaded, self.closed, self.connection, self.salt = False, False, None, None
        self.state, self.last_error, self.last_flush = 'buffering', '', 0
        self.last_prune = ''
        self.maintenance_ticks = 0
        self.thread = None
        if autostart:
            self.thread = threading.Thread(target=self._run, name='interaction-metrics', daemon=True)
            self.thread.start()

    def day(self, stamp=None):
        return datetime.fromtimestamp(self.clock() if stamp is None else stamp, IST).strftime('%Y-%m-%d')

    def add(self, name, value=1, actor=None, event_key=None):
        if name not in METRIC_NAMES or not isinstance(value, int) or value < 0:
            return False
        today, now = self.day(), self.clock()
        with self.guard:
            if self.closed:
                return False
            if event_key is not None:
                previous = self.recent.get(event_key)
                if previous is not None and now - previous < 600:
                    return False
                self.recent[event_key] = now
                self.recent.move_to_end(event_key)
                while len(self.recent) > 8192:
                    self.recent.popitem(last=False)
            key = today, name
            self.pending[key] += value
            self.total[key] += value
            if actor is not None:
                actors = self.actors.setdefault(today, set())
                actor = int(actor)
                if actor > 0:
                    if actor in actors or sum(map(len, self.actors.values())) < self.actor_limit:
                        actors.add(actor)
                    else:
                        self.pending[today, 'activity_overflow'] += 1
                        self.total[today, 'activity_overflow'] += 1
                        self.wake.set()
            self.maintenance_ticks += 1
            if self.maintenance_ticks % 512 == 0:
                cutoff = (datetime.fromtimestamp(now, IST).date() - timedelta(days=self.retention - 1)).isoformat()
                for collection in (self.total, self.unique, self.pending):
                    for entry in list(collection):
                        if (entry[0] if isinstance(entry, tuple) else entry) < cutoff:
                            del collection[entry]
            if len(self.actors.get(today, ())) >= 256:
                self.wake.set()
        return True

    def interaction(self, actor, key, text='', callback=False):
        name = 'callbacks' if callback else 'messages'
        if not self.add(name, actor=actor, event_key=key):
            return False
        if not callback and text.startswith(('/', '.')):
            command = text.split(maxsplit=1)[0][1:].split('@', 1)[0].lower()
            command = command if command in METRIC_COMMANDS else 'other'
            self.add('commands')
            self.add('command.' + command)
        return True

    def observe(self, seconds):
        self.add('handler_count')
        self.add('handler_us', max(0, int(seconds * 1000000)))

    def _open(self):
        if self.connection is not None:
            return self.connection
        if self.path.is_symlink():
            raise OSError('Metrics database must be a regular file.')
        c = sqlite3.connect(str(self.path), timeout=0.2, check_same_thread=False, isolation_level=None)
        try:
            os.chmod(self.path, 0o600)
            c.execute('PRAGMA busy_timeout=200')
            c.execute('PRAGMA journal_mode=WAL')
            c.execute('PRAGMA synchronous=NORMAL')
            c.execute('PRAGMA cache_size=-1024')
            c.execute('PRAGMA wal_autocheckpoint=256')
            c.execute('CREATE TABLE IF NOT EXISTS metrics_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL) WITHOUT ROWID')
            c.execute('CREATE TABLE IF NOT EXISTS metrics_daily (day TEXT NOT NULL,metric TEXT NOT NULL,value INTEGER NOT NULL,PRIMARY KEY(day,metric)) WITHOUT ROWID')
            c.execute('CREATE TABLE IF NOT EXISTS metrics_active (day TEXT NOT NULL,actor TEXT NOT NULL,PRIMARY KEY(day,actor)) WITHOUT ROWID')
            c.execute('INSERT OR IGNORE INTO metrics_meta VALUES (?,?)', ('actor_salt', secrets.token_hex(32)))
            c.execute('INSERT OR IGNORE INTO metrics_meta VALUES (?,?)', ('started_at', str(int(self.clock()))))
            self.salt = bytes.fromhex(c.execute("SELECT value FROM metrics_meta WHERE key='actor_salt'").fetchone()[0])
            if not self.loaded:
                cutoff = (datetime.fromtimestamp(self.clock(), IST).date() - timedelta(days=self.retention - 1)).isoformat()
                baseline = Counter({(day, metric): value for day, metric, value in c.execute('SELECT day,metric,value FROM metrics_daily WHERE day>=?', (cutoff,))})
                unique = Counter(dict(c.execute('SELECT day,COUNT(*) FROM metrics_active WHERE day>=? GROUP BY day', (cutoff,))))
                with self.guard:
                    self.total.update(baseline)
                    self.unique.update(unique)
                    self.loaded = True
            self.connection = c
            return c
        except Exception:
            c.close()
            raise

    def flush(self):
        with self.writer_guard:
            batch, actors = Counter(), {}
            try:
                c = self._open()
                with self.guard:
                    batch, self.pending = self.pending, Counter()
                    actors, self.actors = self.actors, {}
                new_unique = Counter()
                if batch or actors:
                    c.execute('BEGIN IMMEDIATE')
                    c.executemany('INSERT INTO metrics_daily VALUES (?,?,?) ON CONFLICT(day,metric) DO UPDATE SET value=value+excluded.value', ((day, name, value) for (day, name), value in batch.items()))
                    for day, users in actors.items():
                        before = c.total_changes
                        values = ((day, hashlib.blake2b(str(uid).encode(), key=self.salt, digest_size=12).hexdigest()) for uid in users)
                        c.executemany('INSERT OR IGNORE INTO metrics_active VALUES (?,?)', values)
                        new_unique[day] = c.total_changes - before
                    c.commit()
                with self.guard:
                    self.unique.update(new_unique)
                    self.state, self.last_error, self.last_flush = 'ready', '', int(self.clock())
                # From this point the batch is durable: optional cleanup must never requeue it.
                batch, actors = Counter(), {}
                today = self.day()
                if self.last_prune != today:
                    cutoff = (datetime.fromtimestamp(self.clock(), IST).date() - timedelta(days=self.retention - 1)).isoformat()
                    c.execute('DELETE FROM metrics_daily WHERE day<?', (cutoff,))
                    # Bound cleanup work on any one tick; later ticks continue it.
                    removed = c.execute('DELETE FROM metrics_active WHERE (day,actor) IN (SELECT day,actor FROM metrics_active WHERE day<? LIMIT 10000)', (cutoff,)).rowcount
                    if removed < 10000:
                        self.last_prune = today
                return True
            except (sqlite3.Error, OSError, ValueError) as error:
                if self.connection is not None:
                    with contextlib.suppress(sqlite3.Error):
                        self.connection.rollback()
                with self.guard:
                    self.pending.update(batch)
                    for day, users in actors.items():
                        self.actors.setdefault(day, set()).update(users)
                    self.state, self.last_error = 'buffering', type(error).__name__
                return False

    def snapshot(self, days=7):
        days = min(self.retention, max(1, int(days)))
        now = datetime.fromtimestamp(self.clock(), IST)
        cutoff = (now.date() - timedelta(days=days - 1)).isoformat()
        with self.guard:
            sums = Counter()
            for (day, name), value in self.total.items():
                if day >= cutoff:
                    sums[name] += value
            return {'days': days, 'counts': dict(sums), 'active_today': self.unique.get(self.day(), 0),
                    'daily_active': {day: value for day, value in self.unique.items() if day >= cutoff},
                    'state': self.state, 'error': self.last_error, 'last_flush': self.last_flush,
                    'pending_cells': len(self.pending), 'pending_actors': sum(map(len, self.actors.values())),
                    'retention_days': self.retention}

    def _run(self):
        try:
            while not self.stop_event.is_set():
                self.flush()
                self.wake.wait(self.interval)
                self.wake.clear()
            self.flush()
        finally:
            if self.connection is not None:
                self.connection.close()
                self.connection = None

    def close(self, timeout=3):
        with self.guard:
            if self.closed:
                return
            self.closed = True
        self.stop_event.set()
        self.wake.set()
        if self.thread is not None:
            self.thread.join(timeout=timeout)
        else:
            self.flush()
            if self.connection is not None:
                self.connection.close()
                self.connection = None


def metric_add(name, value=1):
    if METRICS is not None:
        METRICS.add(name, value)


def make_metrics(folder):
    try:
        interval = float(os.environ.get('METRICS_FLUSH_SECONDS', '5'))
    except ValueError:
        interval = 5
        LOG.warning('Invalid METRICS_FLUSH_SECONDS; using 5 seconds.')
    try:
        retention = int(os.environ.get('METRICS_RETENTION_DAYS', '90'))
    except ValueError:
        retention = 90
        LOG.warning('Invalid METRICS_RETENTION_DAYS; using 90 days.')
    return InteractionMetrics(folder, interval=interval, retention=retention)


def metrics_panel(chat_id, user_id, days=7):
    owner_only(chat_id, user_id)
    if METRICS is None:
        return ui(chat_id, '📊 Interaction metrics are disabled for this deployment.')
    snapshot = METRICS.snapshot(days)
    values = snapshot['counts']
    average = values.get('handler_us', 0) / max(1, values.get('handler_count', 0)) / 1000
    commands = sorted(((name.split('.', 1)[1], count) for name, count in values.items() if name.startswith('command.')), key=lambda item: item[1], reverse=True)[:6]
    keyboard = types.InlineKeyboardMarkup()
    keyboard.row(*(button(f'{days} day' + ('s' if days > 1 else ''), action=f'admin_metrics:{days}', glyph='📊') for days in (1, 7, 30)))
    keyboard.add(button('Refresh', action=f'admin_metrics:{snapshot["days"]}', glyph='🔄'), button('Owner Panel', action='admin_owner_panel', glyph='⬅️'))
    text = f'📊 Interaction Statistics · {snapshot["days"]} days\nMessages: {values.get("messages", 0)}\nCommands: {values.get("commands", 0)}\nButton / numbered choices: {values.get("callbacks", 0)}\nActive users today: {snapshot["active_today"]}\nPosts created: {values.get("posts_created", 0)}\nPublished: {values.get("published", 0)}\nFailed: {values.get("publish_failed", 0)}\nUnconfirmed: {values.get("publish_uncertain", 0)}\nUnexpected handler errors: {values.get("handler_errors", 0)}\nAverage handler time: {average:.1f} ms\nStorage: {snapshot["state"]}\nRetention: {snapshot["retention_days"]} days\n\nTop commands:\n' + ('\n'.join(f'/{name}: {count}' for name, count in commands) or 'No commands yet.')
    text += '\n\nTracking starts when this version runs. Counters update in memory; active users update after each batch (normally 5 seconds). Private Saved Messages mode normally has one active user.'
    if values.get('activity_overflow'):
        text += '\nActivity buffer reached capacity; the active-user count may be incomplete.'
    ui(chat_id, text, keyboard)


