def send_post(chat_id, data):
    tracked = isinstance(chat_id, int) and chat_id < 0
    try:
        result = _metrics_send_post_base(chat_id, data)
    except (PublisherPaused, PublishDeferred):
        raise
    except Exception as error:
        if tracked:
            metric_add('publish_uncertain' if isinstance(error, DeliveryUncertain) or not isinstance(error, (UserError, ApiTelegramException)) else 'publish_failed')
        raise
    if tracked:
        metric_add('published')
    return result


