def metrics_storage_init(self, folder):
    _metrics_storage_init_base(self, folder)
    self._touch_cache, self._touch_guard = OrderedDict(), threading.RLock()


Storage.__init__ = metrics_storage_init


def throttled_touch_user(self, user_id, name='', newly_created=False):
    name, now = name[:200], time.monotonic()
    with self._touch_guard:
        previous = self._touch_cache.get(user_id)
        if previous and previous[1] == name and now - previous[0] < 60 and not newly_created:
            return
        _touch_user_base(self, user_id, name, newly_created)
        self._touch_cache[user_id] = now, name
        self._touch_cache.move_to_end(user_id)
        while len(self._touch_cache) > 4096:
            self._touch_cache.popitem(last=False)


Storage.touch_user = throttled_touch_user


THEME_ACCENTS = {'blue': '💎', 'green': '💚', 'red': '❤️', 'yellow': '⭐'}
SAFE_RESTORE_META.update({'text_background_style', 'ui_accent'})


def theme_accent_glyph():
    return THEME_ACCENTS.get(STORE.meta('ui_accent', 'blue') if STORE is not None else 'blue', '💎')


def background_entity_type():
    style = STORE.meta('text_background_style', 'quote') if STORE is not None else 'quote'
    return 'expandable_blockquote' if style == 'expandable' else 'blockquote'


def ui_background(text, entities):
    if not text or not setting_on('quote_theme') or any(item['type'] in {'blockquote', 'expandable_blockquote', 'pre'} for item in entities):
        return entities
    protected = [(item['offset'], item['offset'] + item['length']) for item in entities if item['type'] == 'code']
    ranges, position, start, end = [], 0, None, 0
    for line in text.splitlines(keepends=True):
        length = u16(line)
        blocked = any(position < right and position + length > left for left, right in protected)
        if blocked:
            if start is not None:
                ranges.append((start, end))
                start = None
        elif line.strip():
            if start is None:
                start = position
            end = position + u16(line.rstrip('\n'))
        position += length
    if start is not None:
        ranges.append((start, end))
    result = entity_dicts(entities)
    for left, right in ranges[:max(0, 98 - len(result))]:
        if right > left:
            result.append({'type': background_entity_type(), 'offset': left, 'length': right - left})
    return result


async def send_with_effect(self, method, destination, *args, message_effect_id=None, **kwargs):
    value = str(message_effect_id or '')
    if not hasattr(self, 'unsupported_effects'):
        self.unsupported_effects = set()
    allowed = isinstance(destination, tl_types.User) and value.isdigit() and 0 < int(value) < 2**63 and value not in self.unsupported_effects
    options = {'message_effect_id': int(value)} if allowed else {}
    try:
        result = await method(destination, *args, **kwargs, **options)
    except telethon_errors.RPCError as error:
        # Only a confirmed effect-specific rejection permits a no-effect retry.
        if not options or getattr(error, 'message', '') not in {'EFFECT_ID_INVALID', 'EFFECT_ID_NOT_ALLOWED', 'EFFECTS_NOT_SUPPORTED', 'EFFECT_PREMIUM_REQUIRED'}:
            raise
        self.unsupported_effects.add(value)
        return await method(destination, *args, **kwargs)
    if options:
        for message in result if isinstance(result, list) else [result]:
            with contextlib.suppress(Exception):
                message._requested_effect_id = value
    return result


UserTransport.send_with_effect = send_with_effect


async def fetch_effects(transport):
    cached = getattr(transport, 'effect_list', None)
    if cached and time.monotonic() - cached[0] < 600:
        return cached[1]
    response = await transport.client(tl_functions.messages.GetAvailableEffectsRequest(hash=0))
    values = [{'id': str(item.id), 'emoji': item.emoticon, 'premium': bool(getattr(item, 'premium_required', False))} for item in getattr(response, 'effects', [])]
    if not values:
        raise UserError('Telegram did not return available message effects. Try again later.')
    transport.effect_list = time.monotonic(), values
    return values


