_metrics_feature_command_base = feature_command


def feature_command(message):
    name, _, argument = (message.text or '').partition(' ')
    name, argument = name.split('@')[0].lower(), argument.strip()
    if name in {'/stats', '/metrics', '/effects', '/theme'}:
        owner_only(message.chat.id, message.from_user.id)
        if name in {'/stats', '/metrics'}:
            if argument and (not argument.isdigit() or int(argument) not in (1, 7, 30, 90)):
                raise UserError('Use /stats 1, 7, 30 or 90.')
            metrics_panel(message.chat.id, message.from_user.id, int(argument or 7))
        elif name == '/effects':
            effects_panel(message.chat.id, message.from_user.id)
        else:
            if argument in THEME_ACCENTS:
                STORE.setting('ui_accent', argument)
            elif argument:
                set_background(argument)
            theme_panel(message.chat.id)
        return True
    return _metrics_feature_command_base(message)


_metrics_feature_callback_base = feature_callback


def feature_callback(call):
    verb, _, value = (call.data or '').partition(':')
    if verb not in {'admin_metrics', 'admin_background', 'admin_accent', 'admin_effects', 'admin_effect_pick', 'admin_effect_off'}:
        return _metrics_feature_callback_base(call)
    chat_id, user_id = call.message.chat.id, call.from_user.id
    owner_only(chat_id, user_id)
    if verb == 'admin_metrics':
        metrics_panel(chat_id, user_id, int(value or 7))
    elif verb == 'admin_background':
        set_background(value)
        theme_panel(chat_id)
    elif verb == 'admin_accent':
        if value not in THEME_ACCENTS:
            raise UserError('Unknown accent.')
        STORE.setting('ui_accent', value)
        theme_panel(chat_id)
    elif verb == 'admin_effects':
        effects_panel(chat_id, user_id, max(0, int(value or 0)))
    elif verb == 'admin_effect_off':
        set_effect(SimpleNamespace(chat=SimpleNamespace(id=chat_id), from_user=SimpleNamespace(id=user_id)), 'off')
    else:
        effects = USER_CLIENT.call(fetch_effects(USER_CLIENT))
        if value not in {item['id'] for item in effects}:
            raise UserError('Choose a currently available Telegram effect.')
        set_effect(SimpleNamespace(chat=SimpleNamespace(id=chat_id), from_user=SimpleNamespace(id=user_id)), value)
    return True


_metrics_user_event_base = UserBotAPI._handle_event


async def metrics_user_event(self, event):
    eligible = event.out and event.sender_id == self.transport.me.id and event.chat_id == self.transport.me.id
    if not eligible:
        return
    text = event.raw_text or ''
    self._metrics_input_seen = False
    observed = bool(text.startswith('.') and METRICS is not None and METRICS.interaction(event.sender_id, ('message', event.chat_id, event.id), text))
    started = time.perf_counter()
    try:
        command, _, argument = text.partition(' ')
        if command.lower() in {'.stats', '.metrics', '.effects', '.effect', '.theme'}:
            converted = self.convert_message(event.message, '/' + command[1:].lower() + (' ' + argument.strip() if argument.strip() else ''))
            await asyncio.to_thread(on_message, converted)
        else:
            await _metrics_user_event_base(self, event)
    except UserError:
        metric_add('input_rejected')
        raise
    except Exception:
        metric_add('handler_errors')
        raise
    finally:
        if observed or self._metrics_input_seen:
            METRICS.observe(time.perf_counter() - started)


UserBotAPI._handle_event = metrics_user_event
