def backup_metrics(folder, staging):
    path = Path(folder) / 'metrics.db'
    if not path.is_file():
        return None
    snapshot = Path(staging) / 'metrics.db'
    try:
        source = sqlite3.connect(path.as_uri() + '?mode=ro', uri=True, timeout=0.2)
        target = sqlite3.connect(str(snapshot))
        try:
            deadline = time.monotonic() + 2
            def progress(status, remaining, total):
                if time.monotonic() > deadline:
                    raise TimeoutError('Metrics snapshot timed out.')
            source.backup(target, pages=256, sleep=0.01, progress=progress)
        finally:
            source.close()
            target.close()
        os.chmod(snapshot, 0o600)
        return snapshot
    except (sqlite3.Error, OSError, TimeoutError) as error:
        log_error('optional metrics backup', error)
        return None


def metrics_self_test():
    from unittest.mock import patch as mock_patch
    global METRICS, STORE, BOT
    saved = METRICS, STORE, BOT
    checks, collectors = 0, []
    def check(condition, label):
        nonlocal checks
        if not condition:
            raise AssertionError(label)
        checks += 1
    def collector(folder, **kwargs):
        instance = InteractionMetrics(folder, **kwargs)
        collectors.append(instance)
        return instance
    try:
        with tempfile.TemporaryDirectory(prefix='kd-metrics-tests-') as temporary:
            now = [time.time()]
            metrics = collector(temporary, autostart=False, clock=lambda: now[0])
            METRICS = metrics
            with mock_patch.object(sqlite3, 'connect', side_effect=AssertionError('handler attempted SQLite I/O')):
                check(metrics.interaction(111, ('message', 111, 1), '/send PRIVATE_SESSION_ARGUMENT'), 'incoming command recorded without SQL')
                check(not metrics.interaction(111, ('message', 111, 1), '/send PRIVATE_SESSION_ARGUMENT'), 'duplicate message delivery deduplicates')
                metrics.interaction(333, ('callback', 'cb1'), callback=True)
                metrics.observe(0.02)
                snapshot = metrics.snapshot(7)
                check(snapshot['counts']['messages'] == 1 and snapshot['counts']['commands'] == 1 and snapshot['counts']['callbacks'] == 1, 'RAM statistics immediately available without database I/O')
                check(snapshot['active_today'] == 0 and snapshot['pending_actors'] == 2, 'unflushed active users are not misreported as confirmed unique users')
            check(metrics.flush(), 'first batch initializes WAL metrics store')
            check(metrics.snapshot()['active_today'] == 2, 'batched daily active count is exact')
            with sqlite3.connect(metrics.path) as c:
                check(c.execute('PRAGMA journal_mode').fetchone()[0] == 'wal', 'metrics database uses WAL')
                dump = '\n'.join(c.iterdump())
                check('PRIVATE_SESSION_ARGUMENT' not in dump, 'command arguments and content excluded from metrics')
                check(all(row[0] not in {'111', '333'} and len(row[0]) == 24 for row in c.execute('SELECT actor FROM metrics_active')), 'only salted actor hashes persisted')
            with ThreadPoolExecutor(max_workers=8) as pool:
                def add_many(_):
                    for _ in range(1000):
                        metrics.add('messages')
                list(pool.map(add_many, range(8)))
            check(metrics.snapshot()['counts']['messages'] == 8001, 'concurrent interaction counters do not lose updates')
            check(metrics.flush(), 'concurrent counters persisted in one batch')
            blocker = sqlite3.connect(metrics.path, isolation_level=None)
            blocker.execute('BEGIN IMMEDIATE')
            metrics.add('messages', 7)
            check(not metrics.flush(), 'busy metrics writer defers rather than crashing')
            with mock_patch.object(sqlite3, 'connect', side_effect=AssertionError('blocked handler attempted I/O')):
                metrics.add('messages', 2)
                check(metrics.snapshot()['counts']['messages'] == 8010, 'statistics and recording remain available while SQLite is locked')
            blocker.rollback()
            blocker.close()
            check(metrics.flush(), 'deferred batch recovers after lock release')
            with sqlite3.connect(metrics.path) as c:
                check(c.execute("SELECT SUM(value) FROM metrics_daily WHERE metric='messages'").fetchone()[0] == 8010, 'lock retry neither loses nor doubles counters')
            real = metrics.connection
            class CleanupFailure:
                def __getattr__(self, name):
                    return getattr(real, name)
                def execute(self, statement, *args):
                    if statement.startswith('DELETE FROM metrics_daily'):
                        raise sqlite3.OperationalError('simulated cleanup lock')
                    return real.execute(statement, *args)
            metrics.last_prune, metrics.connection = '', CleanupFailure()
            metrics.add('messages', 3)
            check(not metrics.flush(), 'optional cleanup failure reports buffering')
            metrics.connection = real
            check(metrics.flush(), 'cleanup resumes on a later tick')
            with sqlite3.connect(metrics.path) as c:
                check(c.execute("SELECT SUM(value) FROM metrics_daily WHERE metric='messages'").fetchone()[0] == 8013, 'post-commit cleanup failure cannot replay a committed batch')
            metrics.close()
            restarted = collector(temporary, autostart=False, clock=lambda: now[0])
            restarted.interaction(111, ('message', 111, 2), '/help')
            check(restarted.flush(), 'restart loads baseline and new buffered interactions together')
            check(restarted.snapshot()['counts']['messages'] == 8014 and restarted.snapshot()['active_today'] == 2, 'restart preserves counters and stable daily actor hashing')
            check(not restarted.add('unbounded.user.supplied.label'), 'metric names use bounded cardinality')
            now[0] += 100 * 86400
            restarted.add('messages')
            check(restarted.flush(), 'retention cleanup runs after the local day changes')
            with sqlite3.connect(restarted.path) as c:
                check(c.execute("SELECT SUM(value) FROM metrics_daily WHERE metric='messages'").fetchone()[0] == 1, 'expired daily metrics pruned with bounded retention')
            restarted.close()
            tiny = collector(Path(temporary) / 'tiny', actor_limit=2, autostart=False)
            for uid in (111, 222, 333):
                tiny.interaction(uid, ('tiny', uid), '/help')
            check(tiny.snapshot()['pending_actors'] == 2 and tiny.snapshot()['counts']['activity_overflow'] == 1, 'activity buffer is bounded and overflow is visible')
            tiny.flush()
            check(tiny.snapshot()['active_today'] == 2, 'overflow does not invent active users')
            tiny.close()
            STORE = Storage(Path(temporary) / 'application')
            STORE.register(111, 'owner')
            with STORE.db() as c:
                c.execute('UPDATE users SET balance=456 WHERE user_id=111')
            current = collector(STORE.folder, autostart=False)
            METRICS = current
            old_touch = globals()['_touch_user_base']
            touch_calls = []
            def spy_touch(*args, **kwargs):
                touch_calls.append(args[1])
                return old_touch(*args, **kwargs)
            globals()['_touch_user_base'] = spy_touch
            try:
                STORE.touch_user(111, 'Owner')
                for _ in range(100):
                    STORE.touch_user(111, 'Owner')
                check(len(touch_calls) == 1, 'unchanged profile activity is throttled to reduce main-database writes')
                STORE.touch_user(111, 'New Name')
                check(len(touch_calls) == 2, 'profile name change bypasses activity throttle')
                STORE.touch_user(111, 'New Name', newly_created=True)
                check(len(touch_calls) == 3, 'new-user initialization bypasses activity throttle')
            finally:
                globals()['_touch_user_base'] = old_touch
            old_handler, old_callback = globals()['_metrics_on_message_base'], globals()['_metrics_on_callback_base']
            globals()['_metrics_on_message_base'] = lambda message: None
            globals()['_metrics_on_callback_base'] = lambda call: None
            BOT = SimpleNamespace()
            try:
                message = types.Message.de_json({'message_id': 77, 'date': int(time.time()), 'chat': {'id': 111, 'type': 'private'}, 'from': {'id': 111, 'is_bot': False, 'first_name': 'Owner'}, 'text': '/start'})
                on_message(message)
                on_message(message)
                on_callback(SimpleNamespace(id='choice-1', from_user=message.from_user))
                stats = current.snapshot()['counts']
                check(stats['messages'] == 1 and stats['callbacks'] == 1 and stats['handler_count'] == 2, 'handler hooks count genuine interactions once')
            finally:
                globals()['_metrics_on_message_base'], globals()['_metrics_on_callback_base'] = old_handler, old_callback
            current.flush()
            backup = STORE.create_backup()
            with zipfile.ZipFile(backup) as archive:
                check('metrics.db' in archive.namelist(), 'consistent backup includes separate metrics snapshot')
            check(isinstance(inspect_backup(backup), dict), 'selective restore accepts the new backup format')
            check(STORE.user(111)['balance'] == 456, 'metrics tracking does not change existing business data')
            background = collector(Path(temporary) / 'background', interval=1)
            for index in range(200):
                background.interaction(111, ('background', index), '/help')
            background.close()
            check(not background.thread.is_alive(), 'graceful shutdown joins the metrics writer')
            persisted = collector(Path(temporary) / 'background', autostart=False)
            persisted.flush()
            check(persisted.snapshot()['counts']['messages'] == 200, 'graceful shutdown flushes pending metrics')
            check(not background.add('messages'), 'closed metrics collector cannot accumulate more data')
    finally:
        for item in collectors:
            with contextlib.suppress(Exception):
                item.close()
        METRICS, STORE, BOT = saved
    print(f'PASS: {checks} lightweight metrics and concurrency checks; no live account used.')


def theme_self_test():
    from types import MethodType
    import io
    global METRICS, STORE, BOT, USER_CLIENT, ADMIN_ID, CATALOG
    saved = METRICS, STORE, BOT, USER_CLIENT, ADMIN_ID, CATALOG
    checks = 0
    def check(condition, label):
        nonlocal checks
        if not condition:
            raise AssertionError(label)
        checks += 1
    async def run_checks():
        global BOT, USER_CLIENT
        owner = tl_types.User(id=111, first_name='Owner', premium=True)
        channel = tl_types.Channel(id=444, title='Test Channel', photo=tl_types.ChatPhotoEmpty(), date=datetime.now(timezone.utc), broadcast=True)
        records, mode = [], ['ok']
        async def send(target, text, **kwargs):
            records.append((target, text, kwargs))
            if mode[0] == 'effect-rejected' and kwargs.get('message_effect_id'):
                raise telethon_errors.BadRequestError(None, 'EFFECT_ID_INVALID')
            if mode[0] == 'lost':
                raise TimeoutError('confirmation lost')
            if mode[0] == 'unrelated':
                raise telethon_errors.BadRequestError(None, 'MESSAGE_TOO_LONG')
            return SimpleNamespace(id=len(records), raw_text=text)
        transport = SimpleNamespace(me=owner)
        transport.send_with_effect = MethodType(send_with_effect, transport)
        result = await transport.send_with_effect(send, owner, 'Hello', message_effect_id='123')
        check(records[-1][2]['message_effect_id'] == 123 and result._requested_effect_id == '123', 'native effect ID reaches Telethon as an integer')
        await transport.send_with_effect(send, channel, 'Channel', message_effect_id='123')
        check('message_effect_id' not in records[-1][2], 'private-chat effects omitted from channel posts')
        mode[0] = 'effect-rejected'
        before = len(records)
        await transport.send_with_effect(send, owner, 'Fallback', message_effect_id='456')
        check(len(records) == before + 2 and 'message_effect_id' not in records[-1][2], 'confirmed effect rejection permits one plain-message fallback')
        before = len(records)
        await transport.send_with_effect(send, owner, 'Cached fallback', message_effect_id='456')
        check(len(records) == before + 1 and 'message_effect_id' not in records[-1][2], 'unsupported effect cached to avoid repeated rejected requests')
        for failure in ('lost', 'unrelated'):
            mode[0] = failure
            before = len(records)
            try:
                await transport.send_with_effect(send, owner, 'No retry', message_effect_id='789')
            except (TimeoutError, telethon_errors.RPCError):
                pass
            else:
                raise AssertionError('expected simulated delivery failure')
            check(len(records) == before + 1, failure + ' cannot trigger an automatic effect retry')
        mode[0] = 'ok'
        async def checked(target, actor=None):
            return owner if target == 111 else channel
        async def prepare(text, entities):
            return text, mt_entities(entities)
        async def emit(operation, **kwargs):
            return await operation
        async def send_file(target, file, **kwargs):
            return await send(target, kwargs.get('caption', ''), **kwargs)
        transport.checked_target, transport.prepare, transport.emit = checked, prepare, emit
        transport.client = SimpleNamespace(send_message=send, send_file=send_file)
        transport.entities = {}
        api = UserBotAPI(transport)
        BOT, USER_CLIENT = api, transport
        message = await api._send_text(111, 'Effect preview', requested_effect='123')
        check(message.effect_id == '123', 'userbot facade reports the accepted effect for owner preview')
        await api._send_media(111, io.BytesIO(b'media'), 'video', {'caption': 'Video', 'message_effect_id': '123'})
        check(records[-1][2]['message_effect_id'] == 123, 'media effects reach the user-account sender')
        await api._send_text(tl_utils.get_peer_id(channel), 'No private effect here', requested_effect='123')
        check('message_effect_id' not in records[-1][2], 'facade keeps channel sends free of unsupported effects')
        calls = []
        class EffectsClient:
            async def __call__(self, request):
                bytes(request)
                calls.append(request)
                return SimpleNamespace(effects=[SimpleNamespace(id=123, emoticon='🔥', premium_required=False)])
        picker = SimpleNamespace(client=EffectsClient())
        first = await fetch_effects(picker)
        second = await fetch_effects(picker)
        check(first == second and len(calls) == 1 and first[0]['id'] == '123', 'available effects use the genuine Telegram request and a ten-minute cache')
        metrics = METRICS
        original_event = globals()['_metrics_user_event_base']
        async def no_op(*args):
            return None
        globals()['_metrics_user_event_base'] = no_op
        try:
            event = SimpleNamespace(id=9999, out=True, sender_id=111, chat_id=111, raw_text='.help')
            await metrics_user_event(api, event)
            before = metrics.snapshot()['counts']['messages']
            await metrics_user_event(api, SimpleNamespace(id=10000, out=False, sender_id=333, chat_id=111, raw_text='.help'))
            await metrics_user_event(api, SimpleNamespace(id=10001, out=True, sender_id=111, chat_id=111, raw_text='Ordinary saved note'))
            check(metrics.snapshot()['counts']['messages'] == before == 1, 'personal metrics count commands while ignoring outsiders and ordinary saved notes')
        finally:
            globals()['_metrics_user_event_base'] = original_event
    collector = None
    try:
        ADMIN_ID = 111
        with tempfile.TemporaryDirectory(prefix='kd-theme-tests-') as temporary:
            STORE, CATALOG = Storage(temporary), EmojiCatalog()
            STORE.register(111, 'owner')
            collector = InteractionMetrics(temporary, autostart=False)
            METRICS = collector
            set_background('expandable')
            text = 'Header 🔥\nID: ABC123\nDetails'
            code_start = u16('Header 🔥\nID: ')
            entities = [{'type': 'code', 'offset': code_start, 'length': 6}, {'type': 'custom_emoji', 'offset': 7, 'length': 2, 'custom_emoji_id': '1010101010101010101'}]
            formatted = ui_background(text, entities)
            blocks = [item for item in formatted if item['type'] == 'expandable_blockquote']
            check(len(blocks) == 2, 'background styling wraps eligible text around copyable code lines')
            check(all(not (item['offset'] < code_start + 6 and item['offset'] + item['length'] > code_start) for item in blocks), 'quote backgrounds never overlap code spans')
            for item in mt_entities(formatted):
                bytes(item)
            check(valid_entities(text, formatted) is None, 'background and custom emoji formatting preserve valid UTF-16 spans')
            set_background('plain')
            check(ui_background(text, entities) == entities, 'plain theme removes automatic background blocks')
            set_background('quote')
            check(background_entity_type() == 'blockquote', 'quote theme maps to native Telegram blockquote entity')
            STORE.setting('ui_accent', 'red')
            check(theme_accent_glyph() == '❤️', 'UI accent follows the configured theme')
            asyncio.run(run_checks())
            captured, old_ui = [], globals()['ui']
            globals()['ui'] = lambda chat_id, text, *args, **kwargs: captured.append(text)
            try:
                metrics_panel(111, 111)
                check('Interaction Statistics' in captured[-1] and 'Active users today' in captured[-1], 'owner statistics panel presents recorded metrics')
                try:
                    metrics_panel(333, 333)
                except UserError:
                    check(True, 'statistics restricted to owner')
                else:
                    raise AssertionError('non-owner accessed statistics')
            finally:
                globals()['ui'] = old_ui
    finally:
        if collector is not None:
            collector.close()
        METRICS, STORE, BOT, USER_CLIENT, ADMIN_ID, CATALOG = saved
    print(f'PASS: {checks} dynamic theme, native effect and statistics UI checks; no live account used.')


def main():
    global BOT, STORE, CATALOG, BOT_ME, INTRO_POOL, USER_CLIENT, METRICS
    setup_logging()
    CATALOG = EmojiCatalog()
    if "--self-test" in sys.argv:
        self_test()
        userbot_self_test()
        advanced_self_test()
        metrics_self_test()
        theme_self_test()
        return
    try:
        config = userbot_config()
    except UserError as error:
        raise SystemExit(scrub(error)) from None
    if config.mode == "hybrid" and (TOKEN == "PASTE_BOT_TOKEN_HERE" or not re.fullmatch(r"\d+:[A-Za-z0-9_-]+", TOKEN)):
        raise SystemExit("Set TOKEN or BOT_TOKEN first.")
    if ADMIN_ID <= 0:
        raise SystemExit("Set ADMIN_ID or BOT_ADMIN_ID to your positive Telegram user ID.")
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    lock_file = (DATA_DIR / ".kd-emoji.lock").open("a")
    try:
        try:
            import fcntl
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise SystemExit("Another bot instance is using this data directory.")
        except ImportError:
            LOG.warning("Instance file locking unavailable on this OS.")
        STORE = Storage(DATA_DIR)
        if os.environ.get("METRICS_ENABLED", "1").strip().lower() not in {"0", "false", "off"}:
            METRICS = make_metrics(DATA_DIR)
        try:
            USER_CLIENT = UserTransport(config).start()
        except Exception as error:
            raise SystemExit(scrub(error)) from None
        BOT = UserBotAPI(USER_CLIENT) if config.mode == "userbot" else telebot.TeleBot(TOKEN, threaded=True, num_threads=8)
        if config.mode == "userbot":
            me = USER_CLIENT.me
            STORE.register(me.id, me.username)
            STORE.touch_user(me.id, " ".join(filter(None, [me.first_name, me.last_name])))
        INTRO_POOL = ThreadPoolExecutor(max_workers=4, thread_name_prefix="start-animation")
        BOT.register_message_handler(on_message, content_types=["text", "photo", "video", "document", "animation", "sticker", "audio", "voice", "video_note", "contact", "location", "venue", "poll", "dice"], func=lambda message: True)
        BOT.register_callback_query_handler(on_callback, func=lambda call: True)
        signal.signal(signal.SIGINT, shutdown)
        signal.signal(signal.SIGTERM, shutdown)
        while not STOP.is_set():
            try:
                BOT_ME = tg(BOT.get_me, max_wait=30)
                tg(BOT.remove_webhook, max_wait=30)
                break
            except ApiTelegramException as error:
                if (getattr(error, "result_json", {}) or {}).get("error_code") in {401, 404}:
                    raise SystemExit("Telegram rejected BOT_TOKEN.")
                log_error("startup API", error)
                STOP.wait(5)
            except Exception as error:
                log_error("startup connection", error)
                STOP.wait(5)
        if STOP.is_set():
            return
        CATALOG.initialize()
        if STORE.state(ADMIN_ID, ADMIN_ID):
            queue_alert('draft_recovery', 'An unfinished workflow was recovered after startup. Use .draft in Saved Messages (or /draft in hybrid mode) to continue it.')
        with contextlib.suppress(Exception):
            tg(BOT.set_my_commands, [types.BotCommand("start", "Open menu"), types.BotCommand("access", "Check access"), types.BotCommand("cancel", "Cancel current step"), types.BotCommand("send", "Publish saved post"), types.BotCommand("help", "Show help")])
        start_health()
        start_feature_worker()
        LOG.info("KD bot @%s ready; owner=%s; users=%s", BOT_ME.username, ADMIN_ID, len(STORE.audience()))
        while not STOP.is_set():
            try:
                BOT.infinity_polling(timeout=30, long_polling_timeout=25, skip_pending=False, allowed_updates=["message", "callback_query"])
            except Exception as error:
                log_error("polling restart", error)
            if not STOP.is_set():
                STOP.wait(5)
    finally:
        shutdown()
        if INTRO_POOL is not None:
            INTRO_POOL.shutdown(wait=True, cancel_futures=True)
        if FEATURE_THREAD is not None:
            FEATURE_THREAD.join(timeout=10)
        if METRICS is not None:
            METRICS.close()
        lock_file.close()


def self_test():
    """Run storage and real-handler regression checks without a Telegram token.

    All API calls below go to a local fake. Test data is confined to a fresh
    temporary directory; no production database or account is opened.
    """
    from types import SimpleNamespace
    global BOT, STORE, BOT_ME, ADMIN_ID, CATALOG, INTRO_POOL, OWNER_NAME
    saved_globals = (BOT, STORE, BOT_ME, ADMIN_ID, CATALOG, INTRO_POOL, OWNER_NAME)
    counts = {"checks": 0, "flows": 0}

    def check(condition, message):
        if not condition:
            raise AssertionError(message)
        counts["checks"] += 1

    def rejected(function, description, code=400, parameters=None):
        payload = {"ok": False, "error_code": code, "description": description}
        if parameters is not None:
            payload["parameters"] = parameters
        return ApiTelegramException(function, None, payload)

    class FakeTelegram:
        def __init__(self):
            self.events = []
            self.sequence = 100
            self.joined = True
            self.reject_custom_reaction = True
            self.lock = threading.RLock()

        def message(self, user_id, text=None, kind="text", chat_id=None, message_id=None, **extra):
            payload = {"message_id": message_id or self.sequence + 1, "date": int(time.time()),
                       "chat": {"id": chat_id if chat_id is not None else user_id, "type": "private" if (chat_id or user_id) > 0 else "supergroup"},
                       "from": {"id": user_id, "is_bot": False, "first_name": "Test User"}}
            if text is not None:
                payload["text"] = text
            if kind == "photo":
                payload["photo"] = [{"file_id": "PHOTO_FILE", "file_unique_id": "PHOTO_UNIQUE", "width": 640, "height": 480}]
            elif kind == "video":
                payload["video"] = {"file_id": "VIDEO_FILE", "file_unique_id": "VIDEO_UNIQUE", "width": 640, "height": 480, "duration": 5}
            payload.update(extra)
            return types.Message.de_json(payload)

        def callback(self, user_id, data, chat_id=None, message_id=None):
            target = chat_id if chat_id is not None else user_id
            state = STORE.state(target, user_id)
            chosen_id = message_id or (state["prompt_id"] if state else self.sequence)
            message = self.message(999, "prompt", chat_id=target, message_id=chosen_id)
            return types.CallbackQuery.de_json({"id": secrets.token_hex(4), "chat_instance": "test", "data": data,
                                               "from": {"id": user_id, "is_bot": False, "first_name": "Test User"}, "message": message.json})

        def get_chat(self, target):
            if int(target) > 0:
                return SimpleNamespace(id=int(target), type="private", first_name="Test Owner", last_name="", username=None)
            return SimpleNamespace(id=int(target), type="channel", title="Test Channel", username="test_channel", invite_link=None)

        def get_chat_member(self, target, user_id):
            if user_id == 999 or user_id == ADMIN_ID:
                return SimpleNamespace(status="administrator", can_post_messages=True, can_invite_users=True)
            if user_id == 222:
                return SimpleNamespace(status="administrator" if self.joined else "left", is_member=self.joined)
            return SimpleNamespace(status="member" if self.joined else "left", is_member=self.joined)

        def get_custom_emoji_stickers(self, values):
            check(len(values) <= 200, "custom emoji batch limit")
            return [SimpleNamespace(custom_emoji_id=str(value), emoji=CATALOG.alt(value), file_id="STICKER_" + str(value), is_animated=True, is_video=False) for value in values]

        def create_chat_invite_link(self, target, **kwargs):
            return SimpleNamespace(invite_link="https://t.me/+TEST_INVITE")

        def send(self, kind, chat_id, content, options):
            text = content if kind == "text" else options.get("caption", "")
            entities = entity_dicts(options.get("entities") if kind == "text" else options.get("caption_entities"))
            valid_entities(text, entities)
            check(u16(text) <= (4096 if kind == "text" else 1024), "message/caption budget")
            markup = options.get("reply_markup")
            markup_dict = json.loads(markup.to_json()) if markup else None
            if markup_dict:
                for row in markup_dict.get("inline_keyboard", markup_dict.get("keyboard", [])):
                    for item in row:
                        check(item.get("style") in {None, "primary", "danger", "success"}, "only documented native button styles")
                        if item.get("icon_custom_emoji_id"):
                            check(not emoji.emoji_list(item["text"]), "custom icon is not duplicated in button text")
                        if "callback_data" in item:
                            check(len(item["callback_data"].encode()) <= 64, "callback byte budget")
            with self.lock:
                self.sequence += 1
                self.events.append({"kind": kind, "chat": chat_id, "content": content, "text": text,
                                    "entities": entities, "markup": markup_dict,
                                    "options": options, "id": self.sequence})
                payload = {"message_id": self.sequence, "date": int(time.time()), "chat": {"id": chat_id, "type": "private" if chat_id > 0 else "channel"}, "text": text}
                if options.get("message_effect_id"):
                    payload["effect_id"] = options["message_effect_id"]
                return types.Message.de_json(payload)

        def send_message(self, chat_id, text, **kwargs):
            return self.send("text", chat_id, text, kwargs)

        def send_photo(self, chat_id, photo, **kwargs):
            return self.send("photo", chat_id, photo, kwargs)

        def send_video(self, chat_id, video, **kwargs):
            return self.send("video", chat_id, video, kwargs)

        def delete_message(self, chat_id, message_id):
            self.events.append({"kind": "delete", "chat": chat_id, "id": message_id})
            return True

        def set_message_reaction(self, chat_id, message_id, reaction, **kwargs):
            value = reaction[0].to_dict()
            self.events.append({"kind": "reaction", "reaction": value, "chat": chat_id})
            if value["type"] == "custom_emoji" and self.reject_custom_reaction:
                raise rejected("setMessageReaction", "Bad Request: REACTION_INVALID")
            return True

        def answer_callback_query(self, *args, **kwargs):
            return True

        def copy_message(self, *args, **kwargs):
            self.events.append({"kind": "copy", "chat": args[0]})
            return SimpleNamespace(message_id=123)

    try:
        ADMIN_ID = 111
        BOT, BOT_ME, CATALOG, INTRO_POOL = FakeTelegram(), SimpleNamespace(id=999, username="kd_test_bot"), EmojiCatalog(), None
        OWNER_NAME = ("Test Owner", time.monotonic() + 1000)

        for character in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz":
            check(u16(character.translate(SMALL_TABLE)) == u16(character), "small-caps UTF-16 length stability")
        check(len(SMALL_ALPHABET) == 26, "small-caps alphabet")
        text = "A😀 B🔥"
        link = {"type": "text_link", "offset": 4, "length": 3, "url": "https://example.com"}
        rendered, entities = premium_text(text, [link])
        check(rendered == "ᴀ😀 ʙ🔥", "small caps preserve supplementary emoji positions")
        check(link in entities, "text link metadata preserved")
        check(any(item["type"] == "custom_emoji" and item["offset"] == 1 and item["length"] == 2 for item in entities), "UTF-16 custom emoji offsets")
        check(not any(item["type"] == "custom_emoji" and item["offset"] == 5 for item in entities), "link entity is not overlapped by new emoji entities")
        compound = "👨‍👩‍👧‍👦 🇮🇳 1️⃣"
        rendered, entities = premium_text(compound)
        check(rendered == compound, "composite emoji text preserved")
        check(sum(item["type"] == "custom_emoji" for item in entities) == 3, "ZWJ, flag and keycap treated as whole emoji")
        valid_entities(rendered, entities)
        existing = {"type": "custom_emoji", "offset": 0, "length": 2, "custom_emoji_id": "4956222745814762495"}
        _, entities = premium_text("🔥", [existing])
        check(sum(item["type"] == "custom_emoji" for item in entities) == 1, "existing custom emoji entity preserved without duplication")
        code = {"type": "code", "offset": 0, "length": 2}
        check(premium_text("🔥", [code])[1] == [code], "code span formatting preserved")
        value = "OPEN https://example.com/Aa?Token=ABC /start CODE"
        code_range = {"type": "code", "offset": u16(value[:value.index("CODE")]), "length": 4}
        result = smallcaps(value, [code_range])
        check("https://example.com/Aa?Token=ABC" in result and "/start" in result and result.endswith("CODE"), "URL, command and code case retained")
        for color in ("blue", "red", "green", "yellow"):
            data = button("🔥 ⭐ 💎 Action", action="test", color=color).to_dict()
            check(bool(data.get("icon_custom_emoji_id")), "one custom button icon")
            check(not emoji.emoji_list(data["text"]), "button text contains no second icon")
            check(data.get("style") == {"blue": "primary", "red": "danger", "green": "success", "yellow": None}[color], "documented button colour mapping")

        with tempfile.TemporaryDirectory(prefix="kd-emoji-selftest-") as folder:
            root = Path(folder)
            connection = sqlite3.connect(root / "bot.db")
            connection.execute("CREATE TABLE users(user_id INTEGER PRIMARY KEY,username TEXT,referrer INTEGER,balance INTEGER DEFAULT 0)")
            connection.execute("INSERT INTO users VALUES (111,'legacy',NULL,321)")
            connection.commit()
            connection.close()
            (root / "users.json").write_text("[111]", encoding="utf-8")
            (root / "redeem.txt").write_text(f"OLD|100|2|0|{int(time.time())+3600}\n# keep this legacy comment\n", encoding="utf-8")
            (root / "posts.json").write_text(json.dumps({"LEGACY": {"content": "Old post", "entities": [], "photo_id": None}}), encoding="utf-8")
            STORE = Storage(root)
            check(STORE.user(111)["balance"] == 321, "legacy balance survives additive migration")
            check(STORE.user(111)["access_expiry"] == 0, "existing access is not reset to a new trial")
            check(bool(list(root.glob("bot.db.before-update-*.bak"))), "pre-migration SQLite backup exists")
            STORE.register(222, "new", 111)
            check(not STORE.register(222, "new", 111), "repeat start does not re-register user")
            initial_expiry = STORE.user(222)["access_expiry"]
            STORE.register(222)
            check(STORE.user(222)["access_expiry"] == initial_expiry, "repeat start does not reset expiry")
            with ThreadPoolExecutor(max_workers=8) as pool:
                results = list(pool.map(lambda _: STORE.reward_referral(222), range(16)))
            check(sum(value is not None for value in results) == 1, "concurrent referral credits exactly once")
            check(STORE.user(111)["balance"] == 371, "referral amount preserved")
            STORE.register(333)
            STORE.register(444)
            with ThreadPoolExecutor(max_workers=8) as pool:
                results = list(pool.map(lambda _: STORE.bonus(444, 17), range(16)))
            check(sum(value[0] for value in results) == 1, "concurrent daily bonus exactly once")
            check(STORE.redeem("OLD", 222) == 100, "legacy redeem imported")
            try:
                STORE.redeem("OLD", 222)
                raise AssertionError("duplicate redeem accepted")
            except UserError:
                counts["checks"] += 1
            check(STORE.redeem("OLD", 333) == 100, "second permitted redeem succeeds")
            check("# keep this legacy comment" in (root / "redeem.txt").read_text(), "legacy redeem comments retained")
            STORE.create_code("ONLYONE", 25, 1, 24)
            with ThreadPoolExecutor(max_workers=8) as pool:
                def redeem_race(uid):
                    try:
                        STORE.redeem("ONLYONE", uid)
                        return True
                    except UserError:
                        return False
                results = list(pool.map(redeem_race, [222, 333, 444] * 4))
            check(sum(results) == 1, "redeem use limit enforced across concurrent users")
            STORE.set_state(-900, 222, "photo", {"value": "one"}, 10)
            STORE.set_state(-900, 333, "redeem", {"value": "two"}, 11)
            check(STORE.state(-900, 222)["data"]["value"] == "one" and STORE.state(-900, 333)["data"]["value"] == "two", "group workflows isolated by user")
            legacy = STORE.post("LEGACY", ADMIN_ID)
            STORE.save_post(ADMIN_ID, ADMIN_ID, dict(legacy, content="Adopted legacy"), "LEGACY")
            check(STORE.post("LEGACY", ADMIN_ID)["content"] == "Adopted legacy", "owner can edit ownerless legacy import")

            # Exercise every menu, including original small-caps reply labels.
            for action in MENU:
                menu_action(BOT.message(ADMIN_ID if action == "owner" else 222, MENU[action]), action)
            check(MENU_ACTIONS[normal_label("Mᴀᴋᴇ Pᴏsᴛ 🎀")] == "post", "original reply-label compatibility")
            check(MENU_ACTIONS[normal_label("👑 Owner Panel")] == "owner", "owner-panel label connected")

            # All six media/button combinations use the actual input handlers.
            for media in (None, "photo", "video"):
                for with_button in (False, True):
                    menu_action(BOT.message(222, "Make Post"), "post")
                    raw = "Hello 😀 family 👨‍👩‍👧‍👦 https://example.com/Aa?Token=ABC"
                    process_input(BOT.message(222, raw), STORE.state(222, 222))
                    old_prompt = STORE.state(222, 222)["prompt_id"]
                    callback_action(BOT.callback(222, "no_media" if media is None else "add_" + media))
                    if media:
                        wrong = "video" if media == "photo" else "photo"
                        try:
                            process_input(BOT.message(222, kind=wrong), STORE.state(222, 222))
                            raise AssertionError("wrong media type accepted")
                        except UserError:
                            counts["checks"] += 1
                        process_input(BOT.message(222, kind=media), STORE.state(222, 222))
                    if with_button:
                        callback_action(BOT.callback(222, "add_button"))
                        process_input(BOT.message(222, "🔥 ⭐ Open"), STORE.state(222, 222))
                        try:
                            process_input(BOT.message(222, "javascript:bad"), STORE.state(222, 222))
                            raise AssertionError("invalid URL accepted")
                        except UserError:
                            counts["checks"] += 1
                        process_input(BOT.message(222, "https://example.com"), STORE.state(222, 222))
                    else:
                        callback_action(BOT.callback(222, "no_button"))
                    latest = STORE.post("latest", 222)
                    check(latest["raw_text"] == raw, "raw post text retained for editing")
                    check("https://example.com/Aa?Token=ABC" in latest["content"], "post URL case retained")
                    check(STORE.state(222, 222) is None, "post workflow completed")
                    check(bool(latest.get("photo_id")) == (media == "photo"), "photo attachment preserved")
                    check(bool(latest.get("video_id")) == (media == "video"), "video attachment preserved")
                    check(bool(latest.get("btn_url")) == with_button, "optional URL button preserved")
                    try:
                        callback_action(BOT.callback(222, "add_photo", message_id=old_prompt))
                        raise AssertionError("stale workflow button accepted")
                    except UserError:
                        counts["checks"] += 1
                    callback_action(BOT.callback(222, "post_preview:" + latest["id"]))
                    publish(222, 222, latest["id"], -100100)
                    counts["flows"] += 1

            latest = STORE.post("latest", 222)
            callback_action(BOT.callback(222, "post_send:" + latest["id"]))
            process_input(BOT.message(222, "-100100"), STORE.state(222, 222))
            check(STORE.state(222, 222) is None, "send-to-channel button completes destination workflow")
            callback_action(BOT.callback(222, "post_edit:" + latest["id"]))
            process_input(BOT.message(222, "Edited 🔥"), STORE.state(222, 222))
            callback_action(BOT.callback(222, "no_button"))
            check(STORE.post(latest["id"], 222)["raw_text"] == "Edited 🔥", "post editing updates saved post")
            try:
                STORE.post(latest["id"], 333)
                raise AssertionError("cross-user post access allowed")
            except UserError:
                counts["checks"] += 1
            try:
                publish(333, 333, "latest", 222)
            except UserError:
                counts["checks"] += 1

            # Owner-only actions, dynamic Force Join and theme controls.
            for action in ("admin_status", "admin_create_redeem", "admin_broadcast", "admin_force_join", "admin_theme"):
                callback_action(BOT.callback(ADMIN_ID, action))
            try:
                callback_action(BOT.callback(333, "admin_status"))
                raise AssertionError("non-owner admin action accepted")
            except UserError:
                counts["checks"] += 1
            callback_action(BOT.callback(ADMIN_ID, "admin_join_add"))
            process_input(BOT.message(ADMIN_ID, "-100100"), STORE.state(ADMIN_ID, ADMIN_ID))
            check(len(STORE.channels()) == 1, "channel setup requires no source-code username")
            BOT.joined = False
            check(not require_join(222, 222), "missing membership blocks access")
            BOT.joined = True
            check(require_join(222, 222), "verified membership restores access")
            callback_action(BOT.callback(ADMIN_ID, "admin_join_remove_-100100"))
            check(not STORE.channels(), "channel removal works")
            for action in ("admin_toggle_theme", "admin_toggle_theme", "admin_toggle_popup", "admin_toggle_popup", "admin_toggle_reaction", "admin_toggle_reaction", "admin_toggle_effect", "admin_toggle_effect", "admin_theme_preview"):
                callback_action(BOT.callback(ADMIN_ID, action))
            callback_action(BOT.callback(ADMIN_ID, "admin_set_effect"))
            process_input(BOT.message(ADMIN_ID, "Effect input", effect_id=DEFAULT_EFFECT_ID), STORE.state(ADMIN_ID, ADMIN_ID))
            check(effect_id() == DEFAULT_EFFECT_ID, "message effects configured from confirmed response")
            callback_action(BOT.callback(ADMIN_ID, "admin_set_start_emoji"))
            custom_id = CATALOG.choose("✨", ui=True)
            glyph = CATALOG.alt(custom_id)
            process_input(BOT.message(ADMIN_ID, glyph, entities=[{"type": "custom_emoji", "offset": 0, "length": u16(glyph), "custom_emoji_id": custom_id}]), STORE.state(ADMIN_ID, ADMIN_ID))
            check(STORE.meta("start_custom_emoji_id") == custom_id, "start custom emoji configured without sticker/effect ID confusion")

            menu_action(BOT.message(222, "Make Post"), "post")
            process_input(BOT.message(222, "Navigation check"), STORE.state(222, 222))
            callback_action(BOT.callback(222, "add_photo"))
            callback_action(BOT.callback(222, "back_media"))
            check(STORE.state(222, 222)["stage"] == "media_choice", "media back button restores options")
            callback_action(BOT.callback(222, "no_media"))
            callback_action(BOT.callback(222, "add_button"))
            callback_action(BOT.callback(222, "back_buttons"))
            callback_action(BOT.callback(222, "add_button"))
            process_input(BOT.message(222, "Open"), STORE.state(222, 222))
            callback_action(BOT.callback(222, "back_buttons"))
            check(STORE.state(222, 222)["stage"] == "button_choice", "URL back button restores options")
            callback_action(BOT.callback(222, "cancel"))
            check(STORE.state(222, 222) is None, "cancel clears only the current user's workflow")

            copied_before = sum(event["kind"] == "copy" for event in BOT.events)
            broadcast(BOT.message(ADMIN_ID, "Broadcast check"))
            deadline = time.monotonic() + 5
            while BROADCAST_LOCK.locked() and time.monotonic() < deadline:
                time.sleep(0.01)
            check(not BROADCAST_LOCK.locked(), "broadcast worker completes outside handler threads")
            copied_after = sum(event["kind"] == "copy" for event in BOT.events)
            check(copied_after - copied_before == len(STORE.audience()), "broadcast reaches each registered recipient once")

            # The reaction attempt, fallback, popup, deletion and welcome order.
            STORE.setting("start_popup", "1")
            STORE.setting("start_reaction", "1")
            start_at = len(BOT.events)
            start_animation(BOT.message(222, "/start", message_id=8000))
            events = BOT.events[start_at:]
            reactions = [event for event in events if event["kind"] == "reaction"]
            check([event["reaction"]["type"] for event in reactions] == ["custom_emoji", "emoji"], "custom reaction gracefully falls back when forbidden")
            popup = next(event for event in events if event["kind"] == "text")
            deleted_index = next(index for index, event in enumerate(events) if event["kind"] == "delete" and event["id"] == popup["id"])
            check(any(index > deleted_index and event["kind"] == "text" for index, event in enumerate(events)), "popup deleted before welcome")
            check(any(item["type"] == "custom_emoji" for item in popup["entities"]), "popup uses a custom emoji entity")
            check(popup["options"].get("message_effect_id") == DEFAULT_EFFECT_ID, "popup receives private-chat message effect")

            # Optional-visual API rejection retries remove only those visuals.
            attempts = []
            def reject_visuals(chat_id, text, **kwargs):
                attempts.append(copy.deepcopy(kwargs))
                if len(attempts) == 1:
                    raise rejected("sendMessage", "Bad Request: CUSTOM_EMOJI_INVALID")
                return True
            keyboard = types.InlineKeyboardMarkup().add(button("Test", action="home", color="yellow"))
            tg(reject_visuals, 222, "✨", entities=entity_objects([{"type": "custom_emoji", "offset": 0, "length": 1, "custom_emoji_id": custom_id}]), reply_markup=keyboard)
            check(len(attempts) == 2 and not attempts[-1].get("entities"), "rejected custom entities fall back")
            item = keyboard.to_dict()["inline_keyboard"][0][0]
            check(not item.get("icon_custom_emoji_id") and len(emoji.emoji_list(item["text"])) == 1, "fallback button has one ordinary icon")
            attempts = []
            def reject_effect(chat_id, text, **kwargs):
                attempts.append(kwargs)
                if len(attempts) == 1:
                    raise rejected("sendMessage", "Bad Request: EFFECT_ID_INVALID")
                return True
            tg(reject_effect, 222, "test", message_effect_id="bad")
            check(len(attempts) == 2 and "message_effect_id" not in attempts[-1], "effect rejection preserves ordinary delivery")

            feature_regression(BOT, check, rejected)

            saved_balance = STORE.user(111)["balance"]
            saved_post = STORE.post("latest", 222)
            STORE.set_state(222, 222, "redeem", {"checkpoint": True}, 9000)
            STORE = Storage(root)
            check(STORE.user(111)["balance"] == saved_balance, "balance survives repeated startup")
            check(STORE.user(222)["access_expiry"] == initial_expiry, "access survives repeated startup")
            check(STORE.post("latest", 222) == saved_post, "posts and formatting survive restart")
            check(STORE.state(222, 222)["data"]["checkpoint"], "workflow survives restart")
            check(STORE.reward_referral(222) is None, "referral ledger survives restart")
            with STORE.db() as connection:
                used = connection.execute("SELECT used FROM nxt_redeem_codes WHERE code='OLD'").fetchone()[0]
            check(used == 2, "redeem use count not reset on re-import")
            check(scrub("123456789:ABCDEFGHIJKLMNOPQRSTUVWXYZ123456789") == "<BOT_TOKEN>", "log token redaction")
    finally:
        BOT, STORE, BOT_ME, ADMIN_ID, CATALOG, INTRO_POOL, OWNER_NAME = saved_globals
    print(f"PASS: {counts['checks']} checks; {counts['flows']} media/button workflows; no live Telegram API used.")


if __name__ == "__main__":
    main()
